    // 代码表运行时状态（全屏文档式参考查看器）
    private int codeTableSection = 0;           // 0=触发层宾语代码 1=地图代码 2=1.15单位表
    private boolean codeTableInited = false;
    private java.util.List<String[]> codeTableTrigger;
    private java.util.List<String[]> codeTableMap;
    private java.util.List<String[]> codeTableUnit;

    private void ensureCodeTableData(){
        if (codeTableInited) return;
        codeTableInited = true;
        codeTableTrigger = new java.util.ArrayList<String[]>();
        codeTableMap = new java.util.ArrayList<String[]>();
        codeTableUnit = new java.util.ArrayList<String[]>();
        for (String s : CODE_TABLE_TRIGGER) codeTableTrigger.add( s.startsWith("#") ? new String[]{ s } : s.split("\\|", -1) );
        for (String s : CODE_TABLE_MAP) codeTableMap.add( s.startsWith("#") ? new String[]{ s } : s.split("\\|", -1) );
        parseUnitTable( codeTableUnit );
    }

    // 解析 1.15 单位表原始文本 -> 查看器行：分类标题为单元素 {"#标题"}，单位行为 {代码, 名称, "", 价格}
    private void parseUnitTable( java.util.List<String[]> out ){
        java.util.regex.Pattern patPrice = java.util.regex.Pattern.compile( "¥(\\d+)" );
        java.util.regex.Pattern patCode = java.util.regex.Pattern.compile( "♢([A-Za-z0-9_]+)" );
        java.util.regex.Pattern patHead = java.util.regex.Pattern.compile( "^([A-Za-z_][A-Za-z0-9_]*)\\s*(.*)$" );
        for (String raw : UNIT_TABLE_RAW){
            if (raw==null) continue;
            String t = raw.trim();
            if (t.length()==0) continue;
            boolean major = t.startsWith( "◢" );
            if (major || t.startsWith( "·" )) t = t.substring( 1 ).trim();
            int ni = t.indexOf( "注：" );
            if (ni>=0) t = t.substring( 0, ni ).trim();
            // 名称 = 第一个 ¥ 或 ♢ 之前的部分
            int cut = t.length();
            int p1 = t.indexOf( "¥" ); if (p1>=0 && p1<cut) cut = p1;
            int p2 = t.indexOf( "♢" ); if (p2>=0 && p2<cut) cut = p2;
            String name = t.substring( 0, cut ).trim();
            // 价格
            java.util.List<String> prices = new java.util.ArrayList<String>();
            java.util.regex.Matcher mp = patPrice.matcher( t );
            while (mp.find()) prices.add( mp.group( 1 ) );
            // 代码
            java.util.List<String> codes = new java.util.ArrayList<String>();
            java.util.regex.Matcher mc = patCode.matcher( t );
            while (mc.find()) codes.add( mc.group( 1 ) );
            if (major){
                out.add( new String[]{ "#" + name + (prices.isEmpty()? "": "  ¥" + prices.get(0)) } );
            }
            if (codes.isEmpty()){
                if (prices.isEmpty() && !major){
                    // 形如「code中文名」的旧式条目：拆出前导 ASCII 代码，其余作名称
                    java.util.regex.Matcher mh = patHead.matcher( name );
                    if (mh.matches() && mh.group(2).trim().length()>0){
                        out.add( new String[]{ mh.group(1), mh.group(2).trim(), "", "" } );
                        continue;
                    }
                }
                if (!major) out.add( new String[]{ "#" + name + (prices.isEmpty()? "": "  ¥" + prices.get(0)) } );
            } else {
                for (int i=0;i<codes.size();i++){
                    String price = i<prices.size() ? prices.get(i) : (prices.isEmpty()? "": prices.get(prices.size()-1));
                    out.add( new String[]{ codes.get(i), name, "", price.isEmpty()? "": ("¥"+price) } );
                }
            }
        }
    }

    // ===== 代码表查看器：全屏文档式参考，滚动浏览，界面过长自动省略，点「码/值」复制完整内容 =====
    private void buildCodeTableDialog(){
        final Dialog dlg = new Dialog( "代码表 · 参考", lightDialog ){
            @Override
            protected void result(Object object){
                Gdx.input.setInputProcessor( im );
            }
        };
        dlg.setFillParent( true );

        final Table body = new Table();
        body.pad( 12f );
        body.top();

        final Label tip = colLabel( "点「码」或「值」打开复制框，可手动删减/选中后再复制（长内容自动省略）", uiSub );
        tip.setFontScale( uiFontScale() );
        tip.setWrap( true );
        body.add( tip ).growX().left().padBottom( 8 ).row();

        final TextButton bTrig = mkBtnL( "宾语代码表" );
        final TextButton bMap = mkBtnL( "地图代码表" );
        final TextButton bUnit = mkBtnL( "单位表" );
        bTrig.getLabel().setFontScale( uiFontScale() );
        bMap.getLabel().setFontScale( uiFontScale() );
        bUnit.getLabel().setFontScale( uiFontScale() );
        bTrig.pad( 14f );
        bMap.pad( 14f );
        bUnit.pad( 14f );
        Table tabRow = new Table();
        tabRow.add( bTrig ).growX().padRight( 6 );
        tabRow.add( bMap ).growX().padRight( 6 );
        tabRow.add( bUnit ).growX().row();
        body.add( tabRow ).growX().left().padBottom( 8 ).row();

        final Table listTable = new Table();
        listTable.top().left();
        final ScrollPane listSP = new ScrollPane( listTable, lightScroll );
        listSP.setFadeScrollBars( false );
        listSP.setScrollingDisabled( true, false );
        body.add( listSP ).grow().row();

        final TextButton bClose = mkBtnL( "关闭" );
        bClose.getLabel().setFontScale( uiFontScale() );
        bClose.pad( 16f );
        body.add( bClose ).growX().padTop( 10 ).row();

        final int[] section = { codeTableSection };
        final float vw = landscape ? (float) ssy : (float) ssx;
        final float codeW = vw * 0.30f;
        final float zhW = vw * 0.22f;

        final Runnable build = new Runnable(){
            @Override
            public void run(){
                ensureCodeTableData();
                java.util.List<String[]> rows = section[0]==0 ? codeTableTrigger : (section[0]==1 ? codeTableMap : codeTableUnit);
                bTrig.setColor( section[0]==0 ? Color.WHITE : new Color( 1f, 1f, 1f, 0.5f ) );
                bMap.setColor( section[0]==1 ? Color.WHITE : new Color( 1f, 1f, 1f, 0.5f ) );
                bUnit.setColor( section[0]==2 ? Color.WHITE : new Color( 1f, 1f, 1f, 0.5f ) );
                String secName = section[0]==0? "宾语" : (section[0]==1? "地图" : "单位");
                dlg.getTitleLabel().setText( "代码表 · " + secName + "（共 " + rows.size() + " 行）" );
                listTable.clearChildren();
                int dataIdx = 0;
                for (String[] r : rows){
                    // 分类标题行
                    if (r.length==1 && r[0].startsWith("#")){
                        Label h = colLabel( r[0].substring(1), uiOrange );
                        h.setFontScale( uiFontScale() );
                        h.setEllipsis( true );
                        listTable.add( h ).growX().left().padTop( 10 ).padBottom( 2 ).row();
                        continue;
                    }
                    final String code = r.length>0 ? r[0] : "";
                    String zh = r.length>1 ? r[1] : "";
                    String val = (r.length>3 && r[3]!=null) ? r[3] : "";
                    final String copyVal = val.isEmpty() ? code : val;

                    Label lCode = colLabel( code, uiBlue );
                    lCode.setFontScale( uiFontScale() );
                    lCode.setEllipsis( true );
                    Label lZh = colLabel( zh, uiTxt );
                    lZh.setFontScale( uiFontScale() );
                    lZh.setEllipsis( true );
                    Label lVal = colLabel( val.isEmpty()? "—":val, val.isEmpty()? uiWeak : uiGreen );
                    lVal.setFontScale( uiFontScale() );
                    lVal.setEllipsis( true );

                    Table row = new Table();
                    row.setBackground( skin.newDrawable( "white_pixel", (dataIdx&1)==0 ? new Color( 0f, 0f, 0f, 0.05f ) : new Color( 0f, 0f, 0f, 0.015f ) ) );
                    row.pad( 7f, 8f, 7f, 8f );
                    row.add( lCode ).width( codeW ).left();
                    row.add( lZh ).width( zhW ).left().padLeft( 4 );
                    row.add( lVal ).growX().left().padLeft( 4 );

                    final String codeCopy = code;
                    lCode.addListener( new com.badlogic.gdx.scenes.scene2d.utils.ClickListener(){
                        @Override
                        public void clicked(com.badlogic.gdx.scenes.scene2d.InputEvent e, float x, float y){
                            openCopyTextDialog( codeCopy, "代码" );
                        }
                    } );
                    row.addListener( new com.badlogic.gdx.scenes.scene2d.utils.ClickListener(){
                        @Override
                        public void clicked(com.badlogic.gdx.scenes.scene2d.InputEvent e, float x, float y){
                            openCopyTextDialog( copyVal, val.isEmpty()? "代码":"值" );
                        }
                    } );
                    listTable.add( row ).growX().left().padBottom( 2 ).row();
                    dataIdx++;
                }
            }
        };

        bTrig.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){ section[0]=0; build.run(); listSP.setScrollY( 0f ); }
        } );
        bMap.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){ section[0]=1; build.run(); listSP.setScrollY( 0f ); }
        } );
        bUnit.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){ section[0]=2; build.run(); listSP.setScrollY( 0f ); }
        } );
        bClose.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){
                dlg.hide();
                Gdx.input.setInputProcessor( im );
            }
        } );

        dlg.getContentTable().add( body ).grow();
        build.run();
        dlg.show( stage );
        Gdx.input.setInputProcessor( stage );
    }

    // 手动截断复制：弹出可编辑文本，用户手动删减或选中片段后再复制（有选区时仅复制选区）
    private void openCopyTextDialog(final String content, final String caption){
        final Dialog dlg = new Dialog( "复制 · " + caption, lightDialog ){
            @Override
            protected void result(Object object){
                Gdx.input.setInputProcessor( stage );
            }
        };
        dlg.setFillParent( true );

        final Table body = new Table();
        body.pad( 12f );
        body.top();

        Label cap = colLabel( "来源：" + caption + "（可手动删减，或选中片段后点「复制」；有选区时仅复制选区）", uiSub );
        cap.setFontScale( uiFontScale() );
        cap.setWrap( true );
        body.add( cap ).growX().left().padBottom( 6 ).row();

        final TextArea ta = new TextArea( content==null? "":content, lightField );
        ScrollPane taScroll = new ScrollPane( ta, lightScroll );
        taScroll.setFadeScrollBars( false );
        taScroll.setScrollingDisabled( true, false );
        Table card = cardTableL();
        card.add( taScroll ).growX().minHeight( 220f ).left().row();
        body.add( card ).growX().left().row();

        final Label feed = colLabel( "当前 " + (content==null?0:content.length()) + " 字符", uiSub );
        feed.setFontScale( uiFontScale() );
        feed.setWrap( true );
        body.add( feed ).growX().left().padTop( 8 ).row();

        TextButton bCopy = primaryBtnL( "复制" );
        bCopy.getLabel().setFontScale( uiFontScale() );
        bCopy.pad( 16f );
        TextButton bClose = mkBtnL( "关闭" );
        bClose.getLabel().setFontScale( uiFontScale() );
        bClose.pad( 16f );
        body.add( bCopy ).growX().padTop( 10 ).row();
        body.add( bClose ).growX().padTop( 8 ).row();

        bCopy.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){
                String sel = ta.getSelection();
                String out = (sel!=null && sel.length()>0) ? sel : ta.getText();
                try {
                    Gdx.app.getClipboard().setContents( out );
                    feed.setColor( uiGreen );
                    String show = out.length()>60 ? out.substring(0,59) + "…" : out;
                    feed.setText( "✔ 已复制 " + out.length() + " 字符：" + show );
                } catch (Exception e){
                    feed.setColor( uiOrange );
                    feed.setText( "复制失败" );
                }
            }
        } );
        bClose.addListener( new ChangeListener(){
            @Override
            public void changed(ChangeEvent event, Actor actor){
                dlg.hide();
                Gdx.input.setInputProcessor( stage );
            }
        } );

        ScrollPane outer = new ScrollPane( body, lightScroll );
        outer.setFadeScrollBars( false );
        outer.setScrollingDisabled( true, false );
        dlg.getContentTable().add( outer ).grow().row();
        dlg.show( stage );
        Gdx.input.setInputProcessor( stage );
    }

