    public static long getUsedMemorySize() {

        long freeSize = 0L;
        long totalSize = 0L;
        long usedSize = -1L;
        try {
            Runtime info = Runtime.getRuntime();
            freeSize = info.freeMemory();
            totalSize = info.totalMemory();
            usedSize = totalSize - freeSize;
        } catch (Exception e) {
            e.printStackTrace();
        }
        return usedSize;

    }

    public static java.util.List<String> splitEqually(String text, int size) {
        // Give the list the right capacity to start with. You could use an array
        // instead if you wanted.
        java.util.List<String> ret = new ArrayList<String>( (text.length() + size - 1) / size );

        for (int start = 0; start < text.length(); start += size) {
            ret.add( text.substring( start, Math.min( text.length(), start + size ) ) );
        }
        return ret;
    }

    private static boolean isPowerOf2(final int n) {
        if (n <= 0) {
            return false;
        }
        return Integer.bitCount( n ) == 1;
    }

    private boolean isAndroid() {
        return OS != null && OS.toLowerCase().contains( "android" );
    }

    // 判定是否为内部样例/临时/工作副本路径（这些路径上的地图不可直接覆盖保存）
    private boolean isInternalWorkPath(String filepath) {
        if (filepath == null) return true;
        String lower = filepath.toLowerCase();
        String base = basepath != null ? basepath.toLowerCase() : "";
        if (!lower.startsWith( base )) return false;
        return lower.contains( "/sample/" ) || lower.contains( "/temp/" ) || lower.contains( "/workspace/" );
    }

