    byte[] nativeData;
    java.util.List<byte[]> nativeDatas = new ArrayList<byte[]>();
    String nativeFilename = "";
    java.util.List<String> nativeFilenames = new ArrayList<String>();
    String nativeStatus = "";
    String nativeUri = "";

    // 原生系统选择器「互斥」标志：同一时刻只允许一个文件/文件夹选择流程在跑。
    // 连击/重复点击/残留线程会各自拉起一个后台等待线程，多个线程会同时回到渲染线程切换界面，
    // 这是造成「糊屏 + 什么都点不了、只能退出重进」的根因，故必须串行化。仅在渲染线程读写。
    private volatile boolean nativePickerRunning = false;
    private volatile long nativePickerStartMs = 0L;

    // 进入原生选择器流程前调用（渲染线程）：若已有流程在跑则忽略本次请求，避免并发
    private boolean beginNativePicker() {
        if (nativePickerRunning) {
            status( "正在等待系统选择器，请稍候…", 2 );
            return false;
        }
        nativePickerRunning = true;
        nativePickerStartMs = System.currentTimeMillis();
        return true;
    }

    // 等待原生系统选择器回调（带限时与休眠，避免 100% CPU 忙等造成的卡顿/ANR）
    private void waitNativeStatus(long timeoutMs) {
        long started = System.currentTimeMillis();
        while (nativeStatus == null || nativeStatus.isEmpty()) {
            nativeStatus = face.getStatus();
            if (nativeStatus == null || nativeStatus.isEmpty()) {
                if (System.currentTimeMillis() - started > timeoutMs) {
                    nativeStatus = "timeout";
                    break;
                }
                try { Thread.sleep( 150 ); } catch (InterruptedException ignored) { }
            }
        }
        // 结果已就绪：解除互斥，允许下一次选择流程
        nativePickerRunning = false;
    }

    private void nativeOpen(final String tujuan, final String[] filter, final Table T) {
        // LOGO 加载刚结束后短窗：防止启动期误触直接拉起系统文件选择器
        if (loadingfile || startupGuardTimer > 0) return;
        // 已有一个原生选择流程在跑时直接忽略，避免并发等待线程互相踩踏界面状态
        if (!beginNativePicker()) return;
        nativeData=null;nativeFilename="";nativeStatus="";
        face.clearSAFstatus();

        new Thread( new Runnable() {
            @Override
            public void run() {
                face.openFile();
                waitNativeStatus( 60000 );


                if (nativeStatus.equalsIgnoreCase( "cancel" )
                        || nativeStatus.equalsIgnoreCase( "timeout" )){
                    log("cancel");
                    Gdx.app.postRunnable( new Runnable() {
                        @Override
                        public void run() { exitDialog( T ); }
                    } );
                    return;
                }else if (nativeStatus.equalsIgnoreCase( "ok" )){
                    log("OK");
                    nativeData=face.getData();
                    nativeFilename=face.getFilename();
                    nativeUri = face.getUri();
                    if (nativeData==null || nativeFilename==null || nativeFilename.isEmpty()){
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                status( z.error, 5 );
                                exitDialog( T );
                            }
                        } );
                        return;
                    }

                    // 校验扩展名白名单
                    boolean extOk = (filter==null || filter.length==0);
                    if (!extOk){
                        for (String ext : filter){
                            if (ext!=null && nativeFilename.toLowerCase().endsWith( ext.toLowerCase() )){
                                extOk = true;
                                break;
                            }
                        }
                    }
                    if (!extOk){
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                status( z.error, 5 );
                                exitDialog( T );
                            }
                        } );
                        return;
                    }

                    String fname = nativeFilename;

                    try {
                        if (tujuan.equalsIgnoreCase( "open" )){
                            // 写入独立工作目录，绝不混入样例/用户原目录
                            FileHandle wsd = Gdx.files.absolute( basepath + "NotTiled/Workspace/" );
                            if (!wsd.exists()) wsd.mkdirs();
                            FileHandle wsub = Gdx.files.absolute( wsd.path() + "/" + System.currentTimeMillis() + "/" );
                            wsub.mkdirs();
                            FileHandle out = Gdx.files.absolute( wsub.path() + "/" + fname );
                            out.writeBytes( nativeData, false );

                            // 出处字段与加载动作都回主线程执行，避免异步加载期间丢失 mapUri
                            final String p = out.path();
                            final String u = nativeUri;
                            final String n = fname;
                            Gdx.app.postRunnable( new Runnable() {
                                @Override
                                public void run() {
                                    mapIsNewOrInternal = false;
                                    mapOwnedByFolder = false;
                                    newFolderTreeUri = "";
                                    curfile = n;
                                    exitDialog( T );
                                    loadtmx( p );
                                    mapUri = u;
                                    mapIsNewOrInternal = false;
                                }
                            } );
                        } else {
                            // 资源文件（含菜单「导入」）：拷贝到当前地图目录以保持相对引用。
                            // 目录无效/不存在时回退到内部可写目录，确保导入不因路径问题而失败；
                            // 写盘异常一律吞掉并提示，无论如何都回到原界面，杜绝停留在空界面上的假死。
                            FileHandle targetDir = null;
                            try {
                                if (curdir != null && !curdir.isEmpty()) {
                                    FileHandle d = Gdx.files.absolute( curdir );
                                    if (d.exists() && d.isDirectory()) targetDir = d;
                                }
                            } catch (Exception ignore) {}
                            if (targetDir == null) {
                                targetDir = Gdx.files.absolute( basepath + "NotTiled/" );
                            }
                            if (!targetDir.exists()) targetDir.mkdirs();
                            final FileHandle out = targetDir.child( fname );
                            try {
                                out.writeBytes( nativeData, false );
                            } catch (Throwable t) {
                                try { ErrorBung( t, "errorlog.txt" ); } catch (Throwable ignore) {}
                            }
                            Gdx.app.postRunnable( new Runnable() {
                                @Override
                                public void run() {
                                    exitDialog( T );
                                    tujuanDialog( tujuan, out );
                                }
                            } );
                        }
                    } catch (Throwable e) {
                        e.printStackTrace();
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                status( z.error, 5 );
                                exitDialog( T );
                            }
                        } );
                    }

                }


            }
        } ).start();
    }

    private void nativeDirectory(final String tujuan, final Table T) {
        // LOGO 加载刚结束后短窗：防止启动期误触直接拉起系统文件夹选择器
        if (loadingfile || startupGuardTimer > 0) return;
        if (!beginNativePicker()) return;
        nativeDatas=null;nativeFilenames=null;nativeFilename="";nativeStatus="";
        face.clearSAFstatus();

        new Thread( new Runnable() {
            @Override
            public void run() {
                face.selectFolder();
                // 文件夹内容在 Android 侧已改为后台线程读取，放宽等待上限，避免大目录误报超时
                waitNativeStatus( 300000 );

                if (nativeStatus.equalsIgnoreCase( "cancel" )){
                    log("cancel");
                    Gdx.app.postRunnable( new Runnable() {
                        @Override
                        public void run() { exitDialog( T ); }
                    } );
                    return;
                } else if (nativeStatus.equalsIgnoreCase( "timeout" )){
                    log("timeout");
                    Gdx.app.postRunnable( new Runnable() {
                        @Override
                        public void run() {
                            status( "读取所选文件夹超时，请重试或换较小的文件夹", 3 );
                            exitDialog( T );
                        }
                    } );
                    return;
                } else if (nativeStatus.equalsIgnoreCase( "error" )){
                    log("error");
                    Gdx.app.postRunnable( new Runnable() {
                        @Override
                        public void run() {
                            status( "读取所选文件夹失败，请重试", 3 );
                            exitDialog( T );
                        }
                    } );
                    return;
                } else if (nativeStatus.equalsIgnoreCase( "ok" )){
                    log("OK");
                    nativeDatas=face.getDatas();
                    nativeFilenames=face.getFilenames();
                    if (nativeDatas==null || nativeFilenames==null || nativeDatas.size()==0){
                        log("no files in folder");
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                status("所选文件夹为空或无可用文件", 3);
                                exitDialog( T );
                            }
                        } );
                        return;
                    }
                    try {
                        String dirname = basepath + "NotTiled/Temp/" + System.currentTimeMillis() + "/";
                        FileHandle wsub = Gdx.files.absolute( dirname );
                        if (!wsub.exists()) wsub.mkdirs();
                        for (int i =0; i<nativeDatas.size(); i++){
                            FileHandle file = Gdx.files.absolute( dirname + nativeFilenames.get(i) );
                            file.writeBytes( nativeDatas.get(i), false );
                        }
                        final FileHandle ff = Gdx.files.absolute( dirname + nativeFilenames.get(0));
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                exitDialog( T );
                                tujuanDialog( tujuan, ff);
                            }
                        } );
                    } catch (Exception e){
                        e.printStackTrace();
                        Gdx.app.postRunnable( new Runnable() {
                            @Override
                            public void run() {
                                exitDialog( T );
                            }
                        } );
                    }
                }
                log("here");


            }
        } ).start();
    }

