    private void nativeFolderOpenInternal() {
        if (!beginNativePicker()) return;
        nativeDatas = null; nativeFilenames = null; nativeFilename = ""; nativeStatus = "";
        face.clearSAFstatus();
        new Thread( new Runnable() {
            @Override
            public void run() {
                face.selectFolder();
                waitNativeStatus( 300000 );
                handleFolderResult();
            }
        } ).start();
    }

    // 二次打开：凭记忆目录的持久化授权直接读取，无需再弹选择器
    private void readOpenTree(final String tree) {
        if (loadingfile || startupGuardTimer > 0) return;
        if (tree == null || tree.isEmpty()) {
            pickOpenFolder();
            return;
        }
        if (!beginNativePicker()) return;
        nativeDatas = null; nativeFilenames = null; nativeFilename = ""; nativeStatus = "";
        face.clearSAFstatus();
        new Thread( new Runnable() {
            @Override
            public void run() {
                face.readTree( tree );
                waitNativeStatus( 300000 );
                handleFolderResult();
            }
        } ).start();
    }

    // 统一处理文件夹读取结果：落盘到独立工作目录 -> 识别 .tmx -> 记忆目录 -> 打开/列表选择
    private void handleFolderResult() {
        final String st = nativeStatus == null ? "" : nativeStatus;
        if (st.equalsIgnoreCase( "cancel" )){
            // 取消选择：优先回到「快捷打开」小框，否则回主菜单
            final String lastTree = prefs.getString( "openTreeUri", "" );
            final String lastName = prefs.getString( "openTreeName", "" );
            Gdx.app.postRunnable( new Runnable(){ public void run(){
                if (lastTree != null && !lastTree.isEmpty()){
                    showQuickOpen( lastTree, lastName );
                } else {
                    gotoStage( tMenu );
                }
            } } );
            return;
        }
        if (st.equalsIgnoreCase( "timeout" )){
            Gdx.app.postRunnable( new Runnable(){ public void run(){
                status( "读取所选文件夹超时，请重试或换较小的文件夹", 4 );
                gotoStage( tMenu );
            } } );
            return;
        }
        if (st.equalsIgnoreCase( "error" )){
            // 目录授权可能失效：清除记忆目录，回退到重新选择
            Gdx.app.postRunnable( new Runnable(){ public void run(){
                prefs.remove( "openTreeUri" );
                prefs.remove( "openTreeName" );
                prefs.flush();
                status( "读取文件夹失败，请重新选择文件夹", 4 );
            } } );
            pickOpenFolder();
            return;
        }
        if (!st.equalsIgnoreCase( "ok" )){
            Gdx.app.postRunnable( new Runnable(){ public void run(){ gotoStage( tMenu ); } } );
            return;
        }
        nativeDatas = face.getDatas();
        nativeFilenames = face.getFilenames();
        final String tree = face.getUri();
        final String disp = face.getFilename();
        if (nativeDatas == null || nativeFilenames == null || nativeFilenames.size() == 0){
            Gdx.app.postRunnable( new Runnable(){ public void run(){
                status( "所选文件夹为空或无可用文件", 4 );
                gotoStage( tMenu );
            } } );
            return;
        }
        try {
            final String dirname = basepath + "NotTiled/Workspace/" + System.currentTimeMillis() + "/";
            FileHandle wsub = Gdx.files.absolute( dirname );
            if (!wsub.exists()) wsub.mkdirs();
            for (int i = 0; i < nativeDatas.size(); i++){
                FileHandle file = Gdx.files.absolute( dirname + nativeFilenames.get( i ) );
                file.writeBytes( nativeDatas.get( i ), false );
            }
            final java.util.List<String> tmxs = new ArrayList<String>();
            for (String n : nativeFilenames){
                if (n != null && n.toLowerCase().endsWith( ".tmx" )) tmxs.add( n );
            }
            if (tmxs.size() == 0){
                Gdx.app.postRunnable( new Runnable(){ public void run(){
                    status( "所选文件夹内没有 .tmx 地图文件", 4 );
                    gotoStage( tMenu );
                } } );
                return;
            }
            Gdx.app.postRunnable( new Runnable() {
                @Override
                public void run() {
                    folderOpenTreeUri = (tree == null ? "" : tree);
                    folderOpenTmpDir = dirname;
                    folderOpenTmxNames = tmxs;
                    if (tree != null && !tree.isEmpty()){
                        prefs.putString( "openTreeUri", tree );
                        prefs.putString( "openTreeName", (disp == null ? "" : disp) );
                        prefs.flush();
                    }
                    if (tmxs.size() == 1){
                        openFolderMap( tmxs.get( 0 ) );
                    } else {
                        showFolderChooser( tmxs, disp );
                    }
                }
            } );
        } catch (Exception e){
            e.printStackTrace();
            Gdx.app.postRunnable( new Runnable(){ public void run(){
                status( z.error, 5 );
                gotoStage( tMenu );
            } } );
        }
    }

    private void showFolderChooser(java.util.List<String> tmxs, String disp) {
        lFolderPath.setText( "目录: " + (disp == null ? "" : disp) );
        lfolderlist.setItems( tmxs.toArray( new String[0] ) );
        lfolderlist.setSelectedIndex( 0 );
        gotoStage( tOpenFolder );
    }

    // 打开文件夹内选定的地图，并把保存归属指回该文件夹
    private void openFolderMap(final String name) {
        try {
            if (name == null || name.isEmpty()) return;
            final String path = folderOpenTmpDir + "/" + name;
            curdir = folderOpenTmpDir;
            backToMap();
            loadtmx( path );
            // loadtmx 内部会清空这些字段，需在其后恢复保存归属
            mapUri = "";
            newFolderTreeUri = folderOpenTreeUri;
            mapOwnedByFolder = (folderOpenTreeUri != null && !folderOpenTreeUri.isEmpty());
            mapIsNewOrInternal = false;
            // 记录到「最近打开的文件」，便于下次直接打开
            recents.addrecent( path, name, "open" );
            saveRecents();
        } catch (Exception e){
            e.printStackTrace();
            status( z.error, 5 );
        }
    }



    private void resetSwatches() {
        Integer sw = 0;
        for (int ii = 0; ii < 6; ii++) {
            swatchValue.set( ii, 0 );
        }


        for (property p : properties) {
            if (p.getName().equalsIgnoreCase( "sw1" )) {
                swatchValue.set( 0, Integer.parseInt( p.getValue() ) );
            }
            if (p.getName().equalsIgnoreCase( "sw2" )) {
                swatchValue.set( 1, Integer.parseInt( p.getValue() ) );
            }
            if (p.getName().equalsIgnoreCase( "sw3" )) {
                swatchValue.set( 2, Integer.parseInt( p.getValue() ) );
            }
            if (p.getName().equalsIgnoreCase( "sw4" )) {
                swatchValue.set( 3, Integer.parseInt( p.getValue() ) );
            }
            if (p.getName().equalsIgnoreCase( "sw5" )) {
                swatchValue.set( 4, Integer.parseInt( p.getValue() ) );
            }
            if (p.getName().equalsIgnoreCase( "sw6" )) {
                swatchValue.set( 5, Integer.parseInt( p.getValue() ) );
            }
        }

    }


