    float loadingtime = 0;
    boolean prevLoadingfile = false;
    // LOGO/加载画面刚结束后短暂防误触窗口：丢弃残留点击，避免误触发文件/文件夹选择器等
    float startupGuardTimer = 0f;
    static final float STARTUP_GUARD_SECONDS = 1.5f;
    // 空图块集拾取器防误触：需短时间两次点击才打开添加图块集文件选择器
    long lastEmptyPickerTap = 0;

    int FPSCount =0;

    @Override
    public void render() {
        renderThread = Thread.currentThread();
        // 联机平铺编辑：把上一帧累积的平铺变更合并成少量包发出（降流量）
        flushPendingDraw();
        // 联机：全房地图同步自动自检（默认约每 25 秒一次；检测到不一致时缩短复检间隔以尽快确认/恢复；
        // 仅在房内；推送/载图中跳过以免误报）
        if (isClient && (isCreateRoom || isJoinRoom) && !pushingUpdate && !loadingfile && !resyncPending) {
            long nowCk = System.currentTimeMillis();
            // 待确认/提醒状态下用更短的复检间隔，尽快确认或恢复；否则用正常间隔
            long ckInterval = (syncReminderActive || desyncStrikes > 0)
                    ? AUTO_MAP_CHECK_INTERVAL_DESYNC_MS : AUTO_MAP_CHECK_INTERVAL_NORMAL_MS;
            if (!mapCheckActive && nowCk - lastAutoMapCheckMs >= ckInterval) {
                // 静默门槛：必须“没有编辑在途”且“距上次改动已静默一段时间”才自检。
                // 边编辑边比对必然因网络/批量延迟产生瞬时指纹差异，是“大量移动频繁误报不同步”的根因；
                // 因此自动自检一律要求静默：编辑期间不检测，一旦停下来即可检测（真正分叉仍会被发现）。
                boolean settled = !isEditInFlight() && (nowCk - lastEditActivityMs >= AUTO_MAP_CHECK_SETTLE_MS);
                if (settled) {
                    lastAutoMapCheckMs = nowCk;
                    requestMapSyncCheck(false);
                }
            }
        }
        if (mapCheckActive && System.currentTimeMillis() >= mapCheckDeadline) {
            finishMapSyncCheck();
        }
        // 非阻塞同步提醒：不同步状态时按秒刷新 HUD，避免提示被其它 status() 覆盖后消失
        refreshSyncReminder();
        // 常驻房投票：定时刷新面板倒计时/票数；服务器未回执时兑底清掉过期投票
        if (voteActive) {
            long nowMs = System.currentTimeMillis();
            if (voteDeadline > 0 && nowMs > voteDeadline + 3000L) {
                resetVoteState();
            } else if (livePanelVisible && nowMs - lastVoteUiTick >= 1000L) {
                lastVoteUiTick = nowMs;
                refreshVoteUi();
            }
        }
        if (kartu.equalsIgnoreCase( "game" )){
            if (!mygame.render()) backToMap();
            return;
        }
        // 联机快捷面板兑底：任何路径（返回键、界面切换、异常）把对话框关掉后，
        // 自动复位面板标志并归还地图输入，避免“聊完天后状态残留、地图点不动”的假死。
        if (livePanelVisible) {
            try {
                if (liveDialog == null || liveDialog.getStage() == null || !liveDialog.isVisible()) {
                    // 仅在地图编辑界面归还输入处理器；其它界面只清面板标志，避免覆盖新界面的输入设置
                    boolean mapKartu = (kartu != null && (kartu.equalsIgnoreCase( "world" )
                            || kartu.equalsIgnoreCase( "editor" ) || kartu.equalsIgnoreCase( "tile" )));
                    if (mapKartu) {
                        hideLivePanel();
                    } else {
                        livePanelVisible = false;
                        prevLiveInput = null;
                        if (liveDialog != null) liveDialog.setVisible( false );
                    }
                }
            } catch (Exception e) {}
        }
        // 弹窗输入兜底：任意弹窗（确认框/信息框/更新框/聊天面板等）由“显示中”变为“已关闭”时，
        // 依据当前界面归还输入处理器，修复“取消/关闭弹窗后地图或屏幕点不动/屏幕不动”。
        try {
            boolean dialogShowing = stageHasVisibleDialog();
            if (dialogWasShowing && !dialogShowing) restoreMapInputIfStuckOnStage();
            dialogWasShowing = dialogShowing;
        } catch (Exception ignore) {}
        delta = Gdx.graphics.getDeltaTime();
        // 选框工具：长按起手后由本帧轮询驱动选区跟随与收尾
        //（libGDX GestureDetector 长按触发后会吞掉 pan/tap，故拉框不能依赖 pan/panStop 完成）
        mqPollDrag();
        // 图块选框：拉框跟随/收尾 与 拖动预览跟手，同样依赖本帧轮询
        tmqPollDraw();
        tmqPollMove();
        // 拖到目标位置松手后：弹出模态「确认放置」框（弹出期间屏蔽地图点击防误触）
        mqPollAskPlace();
        tmqPollAskPlace();
        //undolayer.clear();

        // 对象层点击由 tap() 直接命中检测并弹选择面板，此处仅复位计时，避免重复弹出
        if (waittoloadlist>0) waittoloadlist-=delta;
        if (waittoloadlist<=0 && waittoloadlist!=-1) {
            waittoloadlist=-1;
        }

        if (movepointer>0) movepointer-=delta;
        if (movepointer<=0 && movepointer!=-1){
            if (body !=null){
                body.setTransform( -99,99,0 );
                body.setAwake( true );
            }
            movepointer=-1;
        }

        if (requestavailable) fullfilrequest();
        pointerremoval(delta);
        fulfilloldfunction();

        FPSCount +=1;
        if (FPSCount ==60) FPSCount=0;

        try {
            if (firstrun) {
                asyncinitiation();
                firstrun = false;
            }
            if (loadingfile) {
                loadingtime += delta;
                prevLoadingfile = true;
                // 安全兑底：非首次初始化时若加载标志异常卡死超 120 秒则自动解除，避免永久停留在加载页
                if (!firstrun && loadingtime > 120f){
                    loadingfile = false;
                    loadingtime = 0;
                } else {
                    drawLoadingScreen();
                }

            } else {
                // LOGO/加载画面刚结束：开启短暂防误触窗口（期间 tap/pan 等手势与文件对话框被忽略）
                if (prevLoadingfile) {
                    startupGuardTimer = STARTUP_GUARD_SECONDS;
                }
                prevLoadingfile = false;
                if (startupGuardTimer > 0) {
                    startupGuardTimer -= delta;
                }
                // 原生选择器互斥标志安全兜底：异常情况下（回调丢失/后台线程崩溃）避免永久锁死文件选择；
                // 阈值取大于最长合法等待(文件夹读取 300s)，确保不会误判正在进行的正常选择流程
                if (nativePickerRunning && nativePickerStartMs > 0L
                        && System.currentTimeMillis() - nativePickerStartMs > 330000L) {
                    nativePickerRunning = false;
                }
                world.step( 1 / 60f, 6, 2 );

                Gdx.gl.glClearColor( bgr, bgg, bgb, 1f );
                clsEnter();
                if (firstload > 0) {
                    firstload -= 1;
                    Gdx.gl.glClearColor( 0f, 0f, 0f, 1f );
                    Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                    return;
                }
                if (firstload == 0) {
                    uiAnim();
                    firstload = -1;
                }


                    if (timeToPan >= 0) {
                        timeToPan -= delta;
                        float progress = timeToPan < 0 ? 1 : 1f - timeToPan / panDuration;
                        OrthographicCamera cammy;
                        switch (panType) {
                            case 1:
                                cammy = tilecam;
                                break;
                            case 2:
                                cammy = uicam;
                                break;
                            default:
                                cammy = cam;
                        }


                        cammy.position.x = Interpolation.fade.apply( panOriginX, panTargetX, progress );
                        cammy.position.y = Interpolation.fade.apply( panOriginY, panTargetY, progress );
                        cammy.zoom = Interpolation.fade.apply( panOriginZoom, panTargetZoom, progress );
                        //cammy.position.x = (float) Math.round(cammy.position.x * 100f) / 100f;
                        //cammy.position.y = (float) Math.round(cammy.position.y * 100f) / 100f;

                        cammy.update();
                    }




                autosave += delta;

                if (autosave > 60f * autosaveInterval) {
                    //log(autosaveInterval+"");
                    autosave = 0;
                    if (sAutoSave) {
                        // 自动保存改到后台线程，避免大地图保存时冻结渲染线程
                        runHeavyOp( z.autosaving, new Runnable(){ public void run(){ saveCurrentMap(); } }, null );
                    }
                }

                redraw += delta;

                if (redraw > 0.1f) {
                    redraw = 0;
                    cacheTiles();
                }

                undohistory += delta;

                if (undohistory > 5f) {
                    undohistory = 0;
                    //  Gdx.app.log("Cache","Clearing...");
                    if (undolayer.size() > 100000) {
                        undolayer.subList( 0, undolayer.size() - 100000 ).clear();
                    }
                    // Gdx.app.log("Cache","Cleared");
                }


                rotator += delta;

                if (rotator > 0.15f) {
                    rotator = 0;
                    if (rotating && layers.size() > 0) {
                        viewMode = ViewMode.SINGLE;

                        int lastvis = -1;
                        int firstvis = -1;

                        for (int i = 0; i < layers.size(); i++) {
                            if (layers.get( i ).isVisible()) {
                                if (firstvis == -1) {
                                    firstvis = i;
                                }

                                lastvis = i;
                            }
                        }
                        Gdx.app.log( firstvis + "", lastvis + "" );
                        if (firstvis != -1) {
                            if (selLayer >= lastvis) {
                                selLayer = firstvis;
                            } else {

                                for (int i = 0; i < layers.size(); i++) {
                                    if (layers.get( i ).isVisible() && i > selLayer) {
                                        selLayer = i;
                                        resetCaches();
                                        break;
                                    }
                                }
                            }
                        }

                    }
                }

                animate( delta );



                checkConnectionStatus();


                if (nofling > 0) nofling -= delta;
                mqAutoPanFollow(); // 选框拖动中：手指贴边时镜头自动跟随
                switch (kartu) {
                    case "world":
                        bloom.setEnabled( false );
                        vignette.setEnabled( false );
                        Gdx.gl.glEnable( GL20.GL_BLEND );
                        Gdx.gl.glBlendFunc( GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA );

                        postProcessor.capture();
                        Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                        batch.totalRenderCalls = 0;


                        if (layers.size() > 0 && mode != "newpoly") {
                            if (selLayer >= layers.size()) selLayer = 0;
                            if (layers.get( selLayer ).getType() == layer.Type.TILE) {
                                mode = "tile";
                            } else if (layers.get( selLayer ).getType() == layer.Type.OBJECT) {
                                mode = "object";
                            } else if (layers.get( selLayer ).getType() == layer.Type.IMAGE) {
                                mode = "image";
                            }
                            // 离开地块层自动退出图块选框（避免残留选择/状态）
                            if (tileMqOn && mode != null && !mode.equals("tile")) {
                                tmqCancelAll();
                                tileMqOn = false;
                            }
                        }

                        if (midiplaying) {
                            if (composerPlayer != null) {
                                if (!composerPlayer.isPlaying()) {
                                    composerPlayer = null;
                                    midiplaying = false;
                                }
                            }
                        }

                        resetMinimap();

                        drawTiles();
                        drawGrid();
                        drawTileMq();
                        drawObjects();
                        drawObjectsInfo();
                        //drawCollisions();
                        postProcessor.render();
                        drawWorldUI();
                        //draw debug for collision detection
                        //b2dr.render(world,cam.combined);

                        drawstage( delta );

                        break;
                    case "stage":
                        //crt.setEnabled(true);
                        bloom.setEnabled( true );

                        Gdx.gl.glEnable( GL20.GL_BLEND );
                        Gdx.gl.glBlendFunc( GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA );

                        postProcessor.capture();
                        Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                        batch.totalRenderCalls = 0;
                        drawTiles();
                        //drawGrid();
                        postProcessor.render();
                        //drawObjects();
                        //drawObjectsInfo();
                        //drawWorldUI();
                        drawstage( delta );
                        stage.getCamera().update();

                        break;
                    case "tile":
                    case "pickanim":
                    case "pick":
                        Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                        drawpicker();
                        drawstage( delta );

                        break;
                    case "editor":
                        switch (mode) {
                            case "tile":
                            case "object":
                            case "image":
                                bloom.setEnabled( false );
                                vignette.setEnabled( false );
                                Gdx.gl.glEnable( GL20.GL_BLEND );
                                Gdx.gl.glBlendFunc( GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA );

                                postProcessor.capture();
                                Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                                batch.totalRenderCalls = 0;


                                resetMinimap();

                                drawTiles();
                                drawGrid();
                                drawTileMq();
                                drawObjects();
                                drawObjectsInfo();
                                postProcessor.render();
                                drawWorldUI();

                                drawstage( delta );
                                break;
                            case "pick":
                                Gdx.gl.glClear( GL20.GL_COLOR_BUFFER_BIT );

                                drawpicker();
                                drawstage( delta );

                                break;

                        }


                        break;

                    //case "stage":

                    //break;
                }

                keyinput( delta );
                if (timeToPan2 >= 0) {
                    timeToPan2 -= delta;
                    float progress = timeToPan2 < 0 ? 1 : 1f - timeToPan2 / panDuration2;
                    uicam.zoom = Interpolation.fade.apply( panOriginZoom2, panTargetZoom2, progress );

                    uicam.update();
                    uis.setProjectionMatrix( uicam.combined );
                    uis.begin( ShapeRenderer.ShapeType.Filled );
                    Gdx.gl.glEnable( GL20.GL_BLEND );
                    Gdx.gl.glBlendFunc( GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA );

                    float alfa = timeToPan2;
                    Color cc = new Color( 0, 0, 0, alfa );
                    if (!landscape) {
                        uis.rect( 0f, 0f, (float) ssx, (float) ssy, cc, cc, cc, cc );
                    } else {
                        uis.rect( 0f, 0f, (float) ssy, (float) ssx, cc, cc, cc, cc );
                    }
                    uis.end();

                }

                if (firstload > 0) {
                    uis.setProjectionMatrix( uicam.combined );
                    uis.begin( ShapeRenderer.ShapeType.Filled );
                    Gdx.gl.glEnable( GL20.GL_BLEND );
                    Gdx.gl.glBlendFunc( GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA );

                    Color cc = new Color( 0, 0, 0, 1 );
                    uis.rect( 0f, 0f, (float) ssx, (float) ssy, cc, cc, cc, cc );
                    uis.end();
                    firstload -= 1;
                }


            }
        } catch (Exception e) {
            ErrorBung( e, "errorlog2.txt" );
            //status("Error in render", 5);
            if (batch.isDrawing()) batch.end();
            if (ui.isDrawing()) ui.end();
            if (sr.isDrawing()) sr.end();
            if (uis.isDrawing()) uis.end();


            //newtmxfile(false);
        }

    }

    void drawCoordinates() {

        if (sShowCoords) {
            str1.getData().setScale( 0.01f + Tsw / 160f );
            for (int yy = 0; yy < Th; yy++) {
                for (int xx = 0; xx < Tw; xx++) {
                    if (orientation.equalsIgnoreCase( "isometric" )) {
                        float offsetx = (xx * Tsw / 2) + (yy * Tsw / 2);
                        float offsety = (xx * Tsh / 2) - (yy * Tsh / 2);

                        str1.draw( batch, xx + "," + yy, (xx * Tsw + Tsw / 8f) - offsetx, (-yy * Tsh + Tsh / 3f) - offsety );

                    } else {
                        str1.draw( batch, xx + "," + yy, xx * Tsw + Tsw / 8f, -yy * Tsh + Tsh / 3f );
                    }
                }

            }
            str1.getData().setScale( uiFontScale() );
        }

        if (layers.size()>0) {
            for (int l=0;l<layers.size();l++) {
                if (layers.get( l).getType()== layer.Type.TILE && l==selLayer) {
                    if (sShowGIDmap) {
                        str1.getData().setScale( 0.01f + Tsw / 160f );
                        for (int yy = 0; yy < Th; yy++) {
                            for (int xx = 0; xx < Tw; xx++) {
                                int num = yy * Tw + xx;
                                long spr = layers.get( l ).getStr().get( num );

                                if (orientation.equalsIgnoreCase( "isometric" )) {
                                    float offsetx = (xx * Tsw / 2) + (yy * Tsw / 2);
                                    float offsety = (xx * Tsh / 2) - (yy * Tsh / 2);


                                    if (spr != 0)
                                        str1.draw( batch, spr + "", (xx * Tsw + Tsw / 8f) - offsetx, (-yy * Tsh + Tsh) - offsety );

                                } else {
                                    if (spr != 0)
                                        str1.draw( batch, spr + "", xx * Tsw + Tsw / 8f, -yy * Tsh + Tsh );
                                }
                            }

                        }
                        str1.getData().setScale( uiFontScale() );
                    }
                }
            }
        }


    }

    void initializePostProcessor() { //I DONT EVEN KNOW WHAT THESE MEANS LOL
        ShaderLoader.BasePath = "data/shaders/";
        postProcessor = new PostProcessor( false, true, isDesktop );

        postProcessor.setClearColor( .5f, .5f, .5f, 1 );
        int vpW = Gdx.graphics.getWidth();
        int vpH = Gdx.graphics.getHeight();
        // create the effects you want
        bloom = new Bloom( (int) (Gdx.graphics.getWidth() * 0.25f), (int) (Gdx.graphics.getHeight() * 0.25f) );
        curvature = new Curvature();
        zoomer = new Zoomer( vpW, vpH, isDesktop ? RadialBlur.Quality.VeryHigh : RadialBlur.Quality.Low );
        int effects = CrtScreen.Effect.TweakContrast.v | CrtScreen.Effect.PhosphorVibrance.v | CrtScreen.Effect.Scanlines.v | CrtScreen.Effect.Tint.v;
        crt = new CrtMonitor( vpW, vpH, false, false, CrtScreen.RgbMode.ChromaticAberrations, effects );
        crt.setTint( 0.8f, 0.8f, .8f );
        Combine combine = crt.getCombinePass();
        combine.setSource1Intensity( 0f );
        combine.setSource2Intensity( 1f );
        combine.setSource1Saturation( 0f );
        combine.setSource2Saturation( 1f );
        vignette = new Vignette( vpW, vpH, false );
        // add them to the postprocessor
        postProcessor.addEffect( curvature );
        postProcessor.addEffect( zoomer );
        postProcessor.addEffect( vignette );
        postProcessor.addEffect( crt );
        postProcessor.addEffect( bloom );
        bloom.setBaseIntesity( 0.0f );
        bloom.setBlurAmount( 1 );//5
        zoomer.setBlurStrength( -0.1f );
        zoomer.setOrigin( Gdx.graphics.getWidth() / 2, Gdx.graphics.getHeight() / 2 );
        curvature.setZoom( 1f );
        vignette.setIntensity( 1f );
        bloom.setEnabled( false );
        crt.setEnabled( false );
        vignette.setEnabled( false );
        curvature.setEnabled( false );
        zoomer.setEnabled( false );
    }

