    @Override
    public void resize(int width, int height) {
        if (kartu == "game") {
            mygame.resize( width, height );
            return;
        }



        //if (loadingfile) return;
        float tx, ty, tz;
        float tx1, ty1, tz1;
        float tx2, ty2, tz2;
        float tx3, ty3, tz3;

        tx = cam.position.x;
        ty = cam.position.y;
        tz = cam.position.z;
        tx1 = tilecam.position.x;
        ty1 = tilecam.position.y;
        tz1 = tilecam.position.z;
        tx3 = uicam.position.x;
        ty3 = uicam.position.y;
        tz3 = uicam.position.z;

        //cam = new OrthographicCamera(Gdx.graphics.getWidth(), Gdx.graphics.getHeight());
        nssx = width;
        nssy = height;
        if (width > height) {
            stage = hstage;
            //stage.addActor(hstage.getRoot());
            cam.setToOrtho( false, ssy, ssx );
            tilecam.setToOrtho( false, ssy, ssx );
            uicam.setToOrtho( false, ssy, ssx );
            minicam.setToOrtho( false, ssy, ssx );
            tx3 = Tsw * Tw * 10f;
            ty3 = 0;
            tz3 = 0;


            landscape = true;
        } else {
            stage = vstage;
            //stage.addActor(vstage.getRoot());
            cam.setToOrtho( false, ssx, ssy );
            tilecam.setToOrtho( false, ssx, ssy );
            uicam.setToOrtho( false, ssx, ssy );
            minicam.setToOrtho( false, ssx, ssy );
            tx3 = 0;
            ty3 = -0;
            tz3 = 0;
            landscape = false;
        }
        stage.getViewport().setScreenSize( width, height );
        if (kartu == "stage") {
            //setMenuMap();
            gotoStage( lastStage );
            if (lastStage == tMenu || lastStage == tMap) {
                setMenuMap();
                gotoStage( tMenu );
            }

            //gotoStage(lastStage);
            //backToMap();
        } else {
            if (dialog != null) {
                dialog.hide();

            }
            if (startup != false) {

            }
            startup = true;

        }


        cam.position.set( tx, ty, tz );
        cam.update();
        tilecam.position.set( tx1, ty1, tz1 );
        tilecam.update();
        // 旋转/尺寸变化：若有「确认放置」弹窗，视为「保留当前移动」关闭，避免悬挂在旧 Stage
        if (mqAskOpen) dismissPlaceAskAsAdjust( false );
        if (tmqAskOpen) dismissPlaceAskAsAdjust( true );
        recenterUI();
        resetMinimap();
        resetCaches();

    }

