        // 找不到时回退到内置字体文件，保证桌面/特殊环境仍可运行。
        String[] systemFonts;
        if (language.equalsIgnoreCase( "Chinese" ) || language.equalsIgnoreCase( "Japanese" )) {
            systemFonts = new String[]{
                    "/system/fonts/NotoSansCJK-Regular.ttc",
                    "/system/fonts/DroidSansFallback.ttf",
                    "/system/fonts/DroidSans.ttf"
            };
        } else {
            systemFonts = new String[]{
                    "/system/fonts/Roboto-Regular.ttf",
                    "/system/fonts/DroidSans.ttf",
                    "/system/fonts/SourceSansPro-Regular.ttf"
            };
        }

        if (sCustomFont.equalsIgnoreCase( "" )) {
            generator = null;
            for (String sf : systemFonts) {
                FileHandle sh = Gdx.files.absolute( sf );
                if (sh.exists()) {
                    try {
                        generator = new FreeTypeFontGenerator( sh );
                        break;
                    } catch (Exception ignored) {
                        generator = null;
                    }
                }
            }
            if (generator == null) {
                generator = new FreeTypeFontGenerator( Gdx.files.internal( filenam ) );
            }
        } else {
            try {
                generator = new FreeTypeFontGenerator( Gdx.files.absolute( sCustomFont ) );
            } catch (Exception e) {
                generator = new FreeTypeFontGenerator( Gdx.files.internal( filenam ) );
            }
        }
        generator.setMaxTextureSize( 99999 );
        str1 = generator.generateFont( parameter );
        generator.dispose();

        skin = new Skin();
        skin2 = new Skin( Gdx.files.internal( "skins/skin/skin.json" ));
        skin.add( "font", str1, BitmapFont.class );

        FileHandle fileHandle = Gdx.files.internal( "skins/holo/Holo-dark-hdpi.json" );
