    // 当前线程是否就是渲染线程（scene2d/GL 操作必须在它上面执行）
    private boolean onRenderThread(){
        return renderThread == null || Thread.currentThread() == renderThread;
    }

    // 把重活（保存/导出/打包等）放到后台线程执行，避免冻结渲染线程：
    //  - 防重入：已有重活在跑时直接提示，不重复启动
    //  - 执行期间冻结地图输入（后台只读地图数据，前台不得再改结构，防并发修改）
    //  - 完成后回到渲染线程复位状态并执行 onDone 回调
    private void runHeavyOp(final String busyMsg, final Runnable work, final Runnable onDone) {
        if (heavyOpRunning) { status( "正在处理，请稍候…", 2 ); return; }
        heavyOpRunning = true;
        if (busyMsg != null) status( busyMsg, 4 );
        final com.badlogic.gdx.InputProcessor prevInput = Gdx.input.getInputProcessor();
        final String prevKartu = kartu;
        try { Gdx.input.setInputProcessor( stage ); } catch (Exception ignore) {}
        new Thread(new Runnable(){
            public void run(){
                try { if (work != null) work.run(); }
                catch (Throwable t) { try { ErrorBung( t, "errorlog.txt" ); } catch (Throwable ignore) {} }
                Gdx.app.postRunnable(new Runnable(){
                    public void run(){
                        heavyOpRunning = false;
                        // 界面未变则归还地图输入处理器；若期间已切换界面，交由该界面自己设置
                        try {
                            if (prevKartu != null && prevKartu.equals( kartu ) && prevInput != null) {
                                Gdx.input.setInputProcessor( prevInput );
                            }
                        } catch (Exception ignore) {}
                        try { if (onDone != null) onDone.run(); } catch (Exception ignore) {}
                    }
                });
            }
        }, "HeavyOp").start();
    }

    private void status(final String msg, final float timeout) {
        if (!onRenderThread()) { Gdx.app.postRunnable(new Runnable(){ public void run(){ status( msg, timeout ); } }); return; }
        debugMe = msg;
        statustimeout = timeout;
    }

