        propCard2.add(propContent).growX().left().row();
        body.add(propCard2).left().growX().padTop(12).row();

        // ===== 对象命名 =====
        final CheckBox cbName0 = new CheckBox("不递增", lightCheck);
        final CheckBox cbName1 = new CheckBox("尾部数字递增", lightCheck);
