    // 根据属性编辑器当前属性名，决定是否显示「选择颜色」/「选择单位」按钮
    private void updatePropButtons() {
        String n = fPropName.getText();
        boolean isColor = n.equalsIgnoreCase("textColor") || n.equalsIgnoreCase("globalMessage_textColor");
        boolean isUnits = n.equalsIgnoreCase("spawnUnits");
        boolean isWaves = n.equalsIgnoreCase("survivalWaves");
        boolean isUnit = n.equalsIgnoreCase("unit");
        boolean isUnitType = n.equalsIgnoreCase("unitType");
        bPropColor.setVisible(isColor);
        bPropUnits.setVisible(isUnits);
        bPropWaves.setVisible(isWaves);
        bPropUnitType.setVisible(isUnitType || isUnit);
        bPropUnitType.setText(isUnit ? "选择单位 ▾" : "选择兵种类型");
    }

    // 自定义属性（属性管理页 增/改/删/移）变更后：实时同步给同房间成员，避免远端不可见
    private void syncEditedObjectProps() {
        try {
            // 图层自定义属性：走图层元数据同步
            if ("layer".equals(sender)) {
                sendLayerOp("meta", Integer.toString(selLayer), layerMetaJson(selLayer), "");
                return;
            }
            if (!"object".equals(sender)) return;
            if (selobjs == null || selobjs.isEmpty()) return;
            obj o = selobjs.get(0);
            if (o == null) return;
            sendObjOp("update", mqLayerIndexOf(o), o);
        } catch (Exception ignore) {}
    }

    // 属性名快捷选择面板：宾语上下文时，将该类型“专属/顶置”条目置顶高亮，下方仍保留原有完整属性表（去重）；否则直接展示全量表
    private void openPropNameQuickPicker() {
        boolean isObj = sender != null && sender.equals("object") && selobjs != null && selobjs.size() > 0;
        String tcode = "";
        int ti = -1;
        if (isObj) {
            tcode = curPropObjType == null ? "" : curPropObjType.trim();
            // 兜底：若未从对象面板下拉捕获到类型，则读取对象已保存的 type
            if (tcode.isEmpty() && selobjs.get(0).getType() != null) tcode = selobjs.get(0).getType();
            if (!tcode.isEmpty()) {
                for (int i = 0; i < PROP_TYPE_CODES.length; i++) {
                    if (PROP_TYPE_CODES[i].equalsIgnoreCase(tcode)) {
                        ti = i;
                        break;
                    }
                }
            }
        }

        final Dialog dlg = new Dialog("属性名快捷选择", skin, "dialog");
        dlg.setFillParent(true);

        Table body = new Table();
        body.pad(14f);
        body.top().left();

        if (ti >= 0) {
            Label typeLb = secLabel("当前类型：" + objTypeCn(tcode));
            typeLb.setFontScale(uiFontScale());
            body.add(typeLb).left().padBottom(6).row();
            Label cap = colLabel("该类型专属属性已置顶并高亮（金色），其余原有属性保留在下方；点击条目即填入属性名（仅填英文代码）。", new Color(0.85f, 0.85f, 0.85f, 1f));
            cap.setWrap(true);
            cap.setFontScale(uiFontScale());
            body.add(cap).left().growX().padBottom(8).row();
        } else {
            Label cap = colLabel("点击条目即填入属性名（仅填英文代码）；留空项用于清空名称。", new Color(0.85f, 0.85f, 0.85f, 1f));
            cap.setWrap(true);
            cap.setFontScale(uiFontScale());
            body.add(cap).left().growX().padBottom(8).row();
        }

        // 顶部固定「留空」项
        addPropQuickRow(body, "（留空）不选择", "", new Color(0.62f, 0.62f, 0.62f, 1f), dlg);

        if (ti >= 0) {
            String[] lab = PROP_TYPE_LABEL[ti];
            String[] val = PROP_TYPE_VAL[ti];
            int pin = PROP_TYPE_PIN[ti];
            int n = lab.length;
            if (pin > n) pin = n;
            if (pin < 0) pin = 0;
            final Color topCol = new Color(1f, 0.84f, 0.35f, 1f);
            final Color normCol = new Color(0.88f, 0.88f, 0.88f, 1f);
            java.util.Set<String> pinCodes = new java.util.HashSet<String>();
            // 1) 顶置区：该类型专属/顶置条目（仅统一强调色高亮）
            if (pin > 0) {
                body.add(propQuickSection("★ 顶置 · 本类型专属属性")).left().growX().padTop(10).padBottom(2).row();
                for (int i = 0; i < pin; i++) {
                    pinCodes.add(val[i] == null ? "" : val[i].toLowerCase());
                    addPropQuickRow(body, lab[i], val[i], topCol, dlg);
                }
            }
            // 2) 下方仍保留原有完整属性表（跳过已顶置的重复项，其余原有选项不受影响）
            body.add(propQuickSection("其余属性（保留原有全部选项）")).left().growX().padTop(10).padBottom(2).row();
            for (int i = 1; i < FALLBACK_PNAME_LABEL.length; i++) {
                String cd = FALLBACK_PNAME_VAL[i];
                if (cd != null && !cd.isEmpty() && pinCodes.contains(cd.toLowerCase())) continue;
                addPropQuickRow(body, FALLBACK_PNAME_LABEL[i], cd, normCol, dlg);
            }
        } else {
            // 回退全量表（跳过首条空项，留空统一由顶部「（留空）不选择」负责）
            body.add(propQuickSection("全部属性")).left().growX().padTop(4).padBottom(2).row();
            final Color normCol = new Color(0.88f, 0.88f, 0.88f, 1f);
            for (int i = 1; i < FALLBACK_PNAME_LABEL.length; i++) {
                addPropQuickRow(body, FALLBACK_PNAME_LABEL[i], FALLBACK_PNAME_VAL[i], normCol, dlg);
            }
        }

        ScrollPane sp = new ScrollPane(body);
        sp.setFadeScrollBars(false);
        sp.setScrollingDisabled(true, false);
        dlg.getContentTable().add(sp).grow().row();
        dlg.show(stage);
    }

    // 属性快捷面板中的分组标题（金色底，仿下拉展开后的分类标题）
    private Table propQuickSection(String title) {
        Table head = new Table();
        head.setBackground(skin.newDrawable("white_pixel", new Color(1f, 0.84f, 0.35f, 0.2f)));
        head.pad(8f, 12f, 8f, 12f);
        Label lb = colLabel(title, new Color(1f, 0.92f, 0.6f, 1f));
        lb.setFontScale(uiFontScale());
        lb.setEllipsis(true);
        head.add(lb).left().growX();
        return head;
    }

    // 属性快捷面板中的一个可点击条目：填入纯英文代码后关闭面板
    private void addPropQuickRow(Table t, String txt, final String code, Color c, final Dialog dlg) {
        Table row = new Table();
        row.setBackground(skin.newDrawable("white_pixel", new Color(1f, 1f, 1f, 0.06f)));
        row.pad(12f, 14f, 12f, 14f);
        Label lb = colLabel(txt, c);
        lb.setEllipsis(true);
        lb.setFontScale(uiFontScale());
        row.add(lb).left().growX();
        row.addListener(new com.badlogic.gdx.scenes.scene2d.utils.ClickListener() {
            @Override
            public void clicked(com.badlogic.gdx.scenes.scene2d.InputEvent event, float x, float y) {
                fPropName.setText(code);
                updatePropButtons();
                dlg.hide();
                Gdx.input.setInputProcessor(stage);
            }
        });
        t.add(row).left().growX().padTop(3).row();
    }

    // 创建红色文字的删除/危险操作按钮（仅文字变红提示，背景保持默认）
