    // 构造一个胶囊形开关按钮样式：up/over/down 为白底灰描边，checked 为指定的实心底色
    private TextButtonStyle makePillStyle(Color onFill, Color onTxt) {
        TextButtonStyle st = new TextButtonStyle();
        st.up = npChipBg;
        st.over = lightNp(new Color(0.957f, 0.965f, 0.973f, 1f), uiBorder);
        st.down = lightNp(new Color(0.898f, 0.918f, 0.937f, 1f), new Color(0.725f, 0.765f, 0.800f, 1f));
        st.checked = lightNp(onFill);
        st.checkedOver = lightNp(onFill);
        st.checkedDown = lightNp(onFill);
        st.font = str1;
        st.fontColor = uiTxt;
        st.overFontColor = uiTxt;
        st.downFontColor = uiTxt;
        st.checkedFontColor = onTxt;
        st.checkedOverFontColor = onTxt;
        st.checkedDownFontColor = onTxt;
        st.disabledFontColor = uiWeak;
        return st;
    }

