    // 构建彩色导航页签并绑定内容容器切换（浅色版）
    private Runnable[] bindPickerTabsL(final Table tabRow, final Table holder, final Table[] pages, final String[] titles, final int initial) {
        final Table[] chips = new Table[titles.length];
        final Label[] labs = new Label[titles.length];
        final Runnable[] go = new Runnable[titles.length];
        for (int i = 0; i < titles.length; i++) {
            final int fi = i;
            go[fi] = new Runnable() {
                @Override
                public void run() {
                    repaintPickerTabsL(chips, labs, holder, pages, fi);
                }
            };
            final Table chip = new Table();
            chip.setBackground(npChipBg);
            chip.pad(8f, 4f, 8f, 4f);
            final Label lb = colLabel(titles[i], uiSub);
            lb.setFontScale(uiFontScale());
            lb.setEllipsis(true);
            chip.add(lb).pad(2f, 12f, 2f, 12f);
            chips[i] = chip;
            labs[i] = lb;
            chip.addListener(new ClickListener() {
                @Override
                public void clicked(InputEvent e, float x, float y) {
                    go[fi].run();
                }
            });
            tabRow.add(chip).padRight(6);
            if ((i + 1) % 2 == 0 && i + 1 < titles.length) tabRow.row();
        }
        repaintPickerTabsL(chips, labs, holder, pages, initial);
        return go;
    }

