    // 选中页签金色底深字，未选中灰底浅字
    private void repaintPickerTabs(Table[] chips, Label[] labs, Table holder, Table[] pages, int idx) {
        for (int i = 0; i < chips.length; i++) {
            boolean on = (i == idx);
            chips[i].setBackground(skin.newDrawable("white_pixel",
                    on ? new Color(1f, 0.84f, 0.35f, 1f) : new Color(1f, 1f, 1f, 0.08f)));
            labs[i].setColor(on ? new Color(0.12f, 0.10f, 0f, 1f) : new Color(0.70f, 0.70f, 0.70f, 1f));
        }
        holder.clearChildren();
        holder.top().left();
        holder.add(pages[idx]).growX().fillX().top().left();
    }

    // 构建页签行并绑定内容容器切换；holder 为滚动区内的内容容器，pages 为各页内容表
    // 返回可用的“跳转到指定页”句柄数组（供页面内逻辑自动切换，例如列表点「编辑」后跳到编辑页）
    private Runnable[] bindPickerTabs(final Table tabRow, final Table holder, final Table[] pages, final String[] titles, final int initial) {
        final Table[] chips = new Table[titles.length];
        final Label[] labs = new Label[titles.length];
        final Runnable[] go = new Runnable[titles.length];
        for (int i = 0; i < titles.length; i++) {
            final int fi = i;
            go[fi] = new Runnable() {
                @Override
                public void run() {
                    repaintPickerTabs(chips, labs, holder, pages, fi);
                }
            };
            final Table chip = new Table();
            chip.setBackground(skin.newDrawable("white_pixel", new Color(1f, 1f, 1f, 0.08f)));
            chip.pad(8f, 4f, 8f, 4f);
            final Label lb = colLabel(titles[i], new Color(0.70f, 0.70f, 0.70f, 1f));
            lb.setFontScale(uiFontScale());
            lb.setEllipsis(true);
            chip.add(lb).pad(2f, 12f, 2f, 12f);
            chips[i] = chip;
            labs[i] = lb;
            chip.addListener(new ClickListener() {
                @Override
                public void clicked(InputEvent e, float x, float y) {
                    go[fi].run();
                }
            });
            tabRow.add(chip).padRight(6);
            // 超过 2 个页签时自动换行，避免页签栏在窄屏横向溢出
            if ((i + 1) % 2 == 0 && i + 1 < titles.length) tabRow.row();
        }
        repaintPickerTabs(chips, labs, holder, pages, initial);
        return go;
    }

