        fBgcolor = new TextField(sBgcolor, skin);
        TextButton tbcustomfont = new TextButton(z.selectfile,skin);
        fBgcolor.setTextFieldFilter(tffcolor);
        fFontsize = new TextField(Integer.toString(fontsize), skin);
