    java.util.List<layerhistory> elha = new ArrayList<layerhistory>();

    public void snapWholeMapPhase1(int zeLayer){
        elha.clear();
        boolean follower = false;
        for (int i=0;i<Tw*Th;i++){
            layerhistory lh = new layerhistory(follower,zeLayer,i,0,layers.get(zeLayer).getStr().get(i),-1,layers.get(zeLayer).getTset().get(i),-1,layers.get(zeLayer).getTile().get(i));
            elha.add(lh);
            follower=true;
        }
    }

    public void snapWholeMapPhase2(int zeLayer){
        for (int i=0;i<Tw*Th;i++){
            elha.get(i).setTo(layers.get(zeLayer).getStr().get(i));
            elha.get(i).setNewtset(layers.get(zeLayer).getTset().get(i));
            undolayer.add(elha.get(i));
        }
        resetCaches();
    }

    private void refreshLayerList(){
        String[] srr = new String[layers.size()];
        for (int i = 0; i < layers.size(); i++) {
            srr[i] = "["+i+"] "+layers.get(i).getName();

        }
        llayerlist.setItems(srr);
        llayerlist.setSelectedIndex(layers.size() - 1);
    }

    /** 统计当前地图中对象组（OBJECT 类型图层）的数量 */
    private int countObjectGroups() {
        int n = 0;
        if (layers != null) {
            for (layer l : layers) {
                if (l != null && l.getType() == layer.Type.OBJECT) n++;
            }
        }
        return n;
    }

    /** 新建一个空的 OBJECT 类型（对象组）图层 */
    private layer createObjectGroupLayer(String nm) {
        layer ol = new layer();
        ol.setType(layer.Type.OBJECT);
        ol.setName(nm);
        ol.setVisible(true);
        return ol;
    }

    /** 创建任何新地图时自动补上默认对象层 Triggers / UnitObjects（已存在则跳过） */
    private void ensureDefaultObjectLayers() {
        if (layers == null) return;
        boolean hasTriggers = false;
        boolean hasUnitObjects = false;
        for (layer l : layers) {
            if (l.getType() != layer.Type.OBJECT || l.getName() == null) continue;
            if (l.getName().equalsIgnoreCase("Triggers")) {
                hasTriggers = true;
            } else if (l.getName().equalsIgnoreCase("UnitObjects")) {
                hasUnitObjects = true;
            }
        }
        if (!hasTriggers) layers.add(createObjectGroupLayer("Triggers"));
        if (!hasUnitObjects) layers.add(createObjectGroupLayer("UnitObjects"));
    }

