    // 应用地图属性（宽/高/图块大小/边距/对象缩放/文件名与格式等）。
    // 本地“应用”按钮与联机“mapResize”远端同步共用同一实现，保证各端执行同一确定性变换、结果一致。
    private void applyMapProperties(int nTh, int nTw, int newTsw, int newTsh,
                                    boolean marginTop, boolean marginLeft, boolean adjustObjects,
                                    String newCurfile, String newFormat, String newRenderOrder, String newOrientation) {
        // ---- 高度 ----
        if (nTh > Th) {//expand height
            java.util.List<Long> tStrs = new ArrayList<Long>();
            java.util.List<Integer> tTsets = new ArrayList<Integer>();
            java.util.List<Integer> tTiles = new ArrayList<Integer>();
            for (int k = 0; k < Tw; k++) {
                tStrs.add((long) 0);
                tTsets.add(-1);
                tTiles.add(-1);
            }
            for (int j = 0; j < layers.size(); j++) {
                if (layers.get(j).getType()!=layer.Type.TILE) continue;
                java.util.List<Long> strs = layers.get(j).getStr();
                java.util.List<Integer> tsets = layers.get(j).getTset();
                java.util.List<Integer> tiles = layers.get(j).getTile();
                for (int i = 0; i < nTh - Th; i++) {
                    if (marginTop) {
                        strs.addAll( 0, tStrs );
                        tsets.addAll( 0, tTsets );
                        tiles.addAll( 0, tTiles );
                    }else{
                        strs.addAll( tStrs );
                        tsets.addAll( tTsets );
                        tiles.addAll( tTiles );
                    }
                }
            }
        } else if (nTh < Th) {//shrink height
            for (int i = 0; i < Th - nTh; i++) {
                for (int k = 0; k < Tw; k++) {
                    for (int j = 0; j < layers.size(); j++) {
                        if (layers.get(j).getType()!=layer.Type.TILE) continue;
                        if (marginTop) {
                            layers.get(j).getStr().remove(0);
                            layers.get(j).getTset().remove(0);
                            layers.get(j).getTile().remove(0);
                        }else{
                            layers.get(j).getStr().remove(layers.get(j).getStr().size() - 1);
                            layers.get(j).getTset().remove(layers.get(j).getTset().size() - 1);
                            layers.get(j).getTile().remove(layers.get(j).getTile().size() - 1);
                        }
                    }
                }
            }
        }
        Th = nTh;

        // ---- 宽度 ----
        if (nTw > Tw) {//expand width
            java.util.List<Long> tStrs = new ArrayList<Long>();
            java.util.List<Integer> tTsets = new ArrayList<Integer>();
            java.util.List<Integer> tTiles = new ArrayList<Integer>();
            for (int k = 0; k < nTw - Tw; k++) {
                tStrs.add((long) 0);
                tTsets.add(-1);
                tTiles.add(-1);
            }
            for (int j = 0; j < layers.size(); j++) {
                if (layers.get(j).getType()!=layer.Type.TILE) continue;
                java.util.List<Long> strs = layers.get(j).getStr();
                java.util.List<Integer> tsets = layers.get(j).getTset();
                java.util.List<Integer> tiles = layers.get(j).getTile();
                for (int i = Th; i > 0; i--) {
                    int moyeng = i * Tw;
                    if (marginLeft) moyeng -=Tw;
                    strs.addAll(moyeng, tStrs);
                    tsets.addAll(moyeng, tTsets);
                    tiles.addAll(moyeng, tTiles);
                }
            }
        } else if (nTw < Tw) {//shrink width
            for (int i = Tw * Th; i > 0; i--) {
                for (int j = 0; j < layers.size(); j++) {
                    if (layers.get(j).getType()!=layer.Type.TILE) continue;
                    if (marginLeft) {
                        if ((i) % Tw == 1) {
                            for (int k = 1; k <= Tw - nTw; k++) {
                                layers.get(j).getStr().remove(i);
                                layers.get(j).getTset().remove(i);
                                layers.get(j).getTile().remove(i);
                            }
                        }
                    }else{
                        if ((i) % Tw == 0) {
                            for (int k = 1; k <= Tw - nTw; k++) {
                                layers.get(j).getStr().remove(i - k);
                                layers.get(j).getTset().remove(i - k);
                                layers.get(j).getTile().remove(i - k);
                            }
                        }
                    }
                }
            }
        }
        Tw = nTw;

        // ---- 图块大小 & 对象缩放 ----
        if (adjustObjects) {
            if (Tsw != newTsw || Tsh != newTsh) {
                float scaleX = (float) newTsw / (float) Tsw;
                float scaleY = (float) newTsh / (float) Tsh;
                for (layer lay : layers) {
                    if (lay.getType() == layer.Type.OBJECT) {
                        for (obj ob : lay.getObjects()) {
                            ob.setX( ob.getX() * scaleX );
                            ob.setY( ob.getY() * scaleY );
                            ob.setW( ob.getW() * scaleX );
                            ob.setH( ob.getH() * scaleY );
                        }
                    }
                }
            }
        }
        Tsh = newTsh;
        Tsw = newTsw;

        if (newCurfile != null && !newCurfile.isEmpty()) curfile = newCurfile;
        if (newFormat != null && !newFormat.isEmpty()) mapFormat = newFormat;
        if (newRenderOrder != null && !newRenderOrder.isEmpty()) renderorder = newRenderOrder;
        if (newOrientation != null && !newOrientation.isEmpty()) orientation = newOrientation;
    }

    // 联机：把一次地图属性变更（尺寸/图块大小/边距/对象缩放/格式/朝向/文件名）同步给同房间成员。
    // 各端各自执行同一确定性变换，免去整图重传；携带变更前尺寸供接收端校验，尺寸不一致则忽略，避免错位。
    private void sendMapResizeSync(int oldTw, int oldTh, int oldTsw, int oldTsh,
                                   int newTw, int newTh, int newTsw, int newTsh,
                                   boolean marginTop, boolean marginLeft, boolean adjustObjects,
                                   String format, String renderOrder, String orient, String filename) {
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) return;
            if (liveBanned) return;   // 被禁编：不发送
            command cc = new command();
            cc.command = "mapResize";
            cc.from = myID;
            cc.room = activeRoom;
            // 字段：oldTw,oldTh,oldTsw,oldTsh,newTw,newTh,newTsw,newTsh,mTop,mLeft,adjust,format,render,orient,filename
            cc.data = oldTw + "," + oldTh + "," + oldTsw + "," + oldTsh + ","
                    + newTw + "," + newTh + "," + newTsw + "," + newTsh + ","
                    + (marginTop ? "1" : "0") + "," + (marginLeft ? "1" : "0") + "," + (adjustObjects ? "1" : "0") + ","
                    + (format == null ? "" : format) + "," + (renderOrder == null ? "" : renderOrder) + ","
                    + (orient == null ? "" : orient) + "," + (filename == null ? "" : filename);
            waitTcpBreath();
            client.sendTCP( cc );
        } catch (Exception ignore) { }
    }

    // 接收端：应用远端发来的一次地图属性变更（与本地“应用”按钮同一套逻辑）
    private void applyRemoteMapResize(String data) {
        if (data == null || data.isEmpty()) return;
        try {
            String[] f = data.split(",", 15);
            if (f.length < 15) return;
            int oldTw = Integer.parseInt(f[0].trim());
            int oldTh = Integer.parseInt(f[1].trim());
            int oldTsw = Integer.parseInt(f[2].trim());
            int oldTsh = Integer.parseInt(f[3].trim());
            // 与本地基准校验：各端必须来自同一张图，否则应用会造成错位/丢失
            if (oldTw != Tw || oldTh != Th || oldTsw != Tsw || oldTsh != Tsh) {
                logNet("[C] 忽略地图尺寸同步（本地基准不一致 " + Tw + "x" + Th + "，期望 " + oldTw + "x" + oldTh + "）");
                return;
            }
            int newTw = Integer.parseInt(f[4].trim());
            int newTh = Integer.parseInt(f[5].trim());
            int newTsw = Integer.parseInt(f[6].trim());
            int newTsh = Integer.parseInt(f[7].trim());
            boolean mTop = "1".equals(f[8].trim());
            boolean mLeft = "1".equals(f[9].trim());
            boolean adjust = "1".equals(f[10].trim());
            String format = f[11];
            String render = f[12];
            String orient = f[13];
            String filename = f[14];
            applyMapProperties(newTh, newTw, newTsw, newTsh, mTop, mLeft, adjust, filename, format, render, orient);
            resetCaches();
            resetMinimap();
            logNet("[C] 已同步地图尺寸: " + newTw + "x" + newTh);
        } catch (Exception e) {
            logNet("[C] 地图尺寸同步解析失败: " + e);
        }
    }

