                if (fTsPropFirstGid.getText() != "") {
                    t.setFirstgid(Integer.parseInt(fTsPropFirstGid.getText()));
                }
                sendTsetChanged("图块集属性变更");

                if (fTsPropSpacing.getText() != "") {
                    t.setSpacing(Integer.parseInt(fTsPropSpacing.getText()));
                } else {
                    t.setSpacing(0);
                }
