    public void gotoStage(Table table) {
        try { if (livePanelVisible) hideLivePanel(); } catch (Exception ignore) {}
        try { if (mqAskOpen) dismissPlaceAskAsAdjust( false ); if (tmqAskOpen) dismissPlaceAskAsAdjust( true ); } catch (Exception ignore) {}
        stage.clear();
        stage.addActor(table);
        Gdx.input.setInputProcessor(stage);
        kartu = "stage";
        lastStage = table;

        face.showbanner(false);
        if (!bypassads) {
            if (lastStage == tMenu) face.showbanner(true);
            if (lastStage == tMap) face.showbanner(true);
        }
    }

