//            GESTURE DETECTOR
//////////////////////////////////////////////////////
    @Override
    public boolean touchDown(float p1, float p2, int p3, int p4) {
        if (kartu.equalsIgnoreCase("game") )
        {
            return true;
        }
        if (kartu.equalsIgnoreCase(  "editor" )){
            Vector3 touch2 = new Vector3();
            uicam.unproject(touch2.set(p1, p2, 0));

            if (tapEditorMenu(touch2)) return true;
        }

        // 「选框」工具手势分派：
        //   状态0：仅记录按下，真正起手交给 longPress（长按起点后再拖动即拉框）；
        //   状态2/3：按下选区外框内=开始/继续拖动整组，按下空白=取消并回原位。
        mqDown = false;
        if (kartu == "world" && mode == "object" && activeobjtoolmode == 1
                && layers.size() > 0 && layers.get(selLayer).getType() == layer.Type.OBJECT
                && !mqPressOnUi(p1, p2)) {
            Vector3 tq = new Vector3();
            cam.unproject(tq.set(p1, p2, 0));
            if (mqState == 0) {
                // 长按起手：仅等待 longPress 判定，避免普通按下/拖拽误拉框
            } else if (mqState == 2 || mqState == 3) {
                float[] g = mqGroupBounds();
                boolean inside = g != null
                        && tq.x >= g[0] - Tsw && tq.x <= g[2] + Tsw
                        && tq.y >= g[1] - Tsh && tq.y <= g[3] + Tsh;
                if (inside) {
                    mqStartMove();   // 已选 → 拖动预览（首次按下才拍原始快照）
                } else {
                    mqCancelAll();   // 空白 → 放弃并回原位
                }
            }
        }
        // 图块选框手势分派：状态2/3 时，按下选区(或移动后目标区)内=开始/继续拖动整块图块，按下空白=取消并回原位
        if (kartu == "world" && isTileMqTool() && (tmqState == 2 || tmqState == 3)
                && !tmqPressOnUi(p1, p2)) {
            Vector3 tq = new Vector3();
            cam.unproject(tq.set(p1, p2, 0));
            float[] tg = tmqRectWorld(tmqState == 3);
            boolean inside = tg != null
                    && tq.x >= tg[0] - Tsw && tq.x <= tg[2] + Tsw
                    && tq.y >= tg[1] - Tsh && tq.y <= tg[3] + Tsh;
            if (inside) {
                tmqStartMove();
            } else {
                tmqCancelAll();
            }
        }


        velx = 0;
        vely = 0;
        if (kartu == "world") {
            initialZoom = cam.zoom;
        } else if (kartu == "tile" || kartu == "pickanim") {
            initialZoom = tilecam.zoom;
        }
        return false;
    }

    public boolean requestoldfunction;

    public void fulfilloldfunction(){
        if (requestoldfunction) {
            showPropBox2D( selobjs.get( 0 ) );
            requestoldfunction = false;
        }
    }

    @Override
    public boolean tap(float p1, float p2, int p3, int p4) {
        //Vector3 ve,vo;
        //ve = uicam.project(new Vector3(p1,p2,0f));
        //status (ve.x+"==="+ve.y,5);
        //vo = minicam.unproject(ve);
        if (kartu.equalsIgnoreCase("game")){return true;}

        if (loadingfile) return true;
        // LOGO 加载刚结束后短窗：丢弃残留点击，防误触发
        if (startupGuardTimer > 0) return true;
        Vector3 touch2 = new Vector3();
        uicam.unproject(touch2.set(p1, p2, 0));
        if (!drag) {

            switch (kartu) {
                case "editor":
                    if (tapEditorActions(touch2)) return true;
                    break;
                case "world":

                    if (!roll) if (tapWorldMenu(touch2)) return true;

                    if (layers.size()>0 && layers.get(selLayer).getType()== layer.Type.OBJECT){
                        Vector3 touch = new Vector3();
                        cam.unproject( touch.set( new Vector3(p1,p2,0) ) );
                        float ae = touch.x;
                        float ab = touch.y;
                        updatePointer(ae,-ab);
                    }



                    if (tilesets.size() == 0) {
                        // 地图无任何图块集时不再把每次点击硬切到拾取器（避免误触拉起文件/文件夹选择器），仅提示
                        status("地图暂无图块集，请点“菜单-图块集-添加”导入图片或 .tsx", 2);
                        return true;
                    }

                    Vector3 touch = new Vector3();
                    cam.unproject(touch.set(p1, p2, 0));


                    int ae = (int) touch.x;
                    int ab = (int) touch.y;

                    //this line is to sovlve problem of the first line not clicked on 1 x 1 tile.
                    //but cause error in other places.
                    //if (touch.y > 0) ab = 1;

                    boolean touched = false;

                    if (orientation.equalsIgnoreCase("orthogonal")) {
                        touched = touch.y < Tsh && touch.y > -Tsh * Th + Tsh && touch.x > 0 && touch.x < Tsw * Tw;
                    } else if (orientation.equalsIgnoreCase("isometric")) {
                        touched = true;
                    }
                    log(touched+"");
                    if (mode=="object") touched=true;
                    int num = 0;

                    if (touched) {


                        if (orientation.equalsIgnoreCase("orthogonal")) {

                            num = (Tw * ((-ab + Tsh) / Tsh) + (ae / Tsw));
                        } else if (orientation.equalsIgnoreCase("isometric")) {

                            //cool way to convert isometric to orthogonal, new iso tap detection
                            int newae = ae - ((Tsw/Tsh) * ab) + Tsw/2;
                            int newab = (ae / (Tsw/Tsh)) + ab -Tsh/2;
                            num = (Tw * ((-newab + Tsh) / Tsh) + (newae / Tsw));
                            //status(""+newae/2f+"|"+(newab-Tsh)+" num:"+num,1);
                            if (num<0 || num >Tw*Th) return true;
                            ae =  (int) (newae/2f);
                            ab = newab;
                            // check by the closest to a point, old iso tap detection.
                            /*
                            float closest = 9999;
                            for (int i = 0; i < Tw * Th; i++) {
                                int offsetx = 0, offsety = 0;
                                xpos = i % Tw;
                                ypos = i / Tw;
                                offsetx = (xpos * Tsw / 2) + (ypos * Tsw / 2);
                                offsety = (xpos * Tsh / 2) - (ypos * Tsh / 2);
                                int drawx = xpos * Tsw - offsetx;
                                int drawy = -ypos * Tsh - offsety;
                                int x = ae - drawx;
                                int y = ab - drawy;
                                int Tsws = Tsw / 2;
                                int Tshs = Tsh / 2;
                                float dx = Math.abs(x - Tsws);
                                float dy = Math.abs(y - Tshs);
                                if (dx / Tsws + dy / Tshs < closest) {
                                    num = i;
                                    closest = dx / Tsws + dy / Tshs;
                                }
                            }

                             */
                        }
                    }

                    if (mode == "tile" && touched) {
                        // 「图块选框」：点击不放地块；空白处轻点=取消并回原位，目标区内轻点=保留待拖动
                        if (isTileMqTool()) {
                            if (tmqState == 2 || tmqState == 3) {
                                float[] tg = tmqRectWorld(tmqState == 3);
                                boolean in = tg != null && touch.x >= tg[0] && touch.x <= tg[2]
                                        && touch.y >= tg[1] && touch.y <= tg[3];
                                if (!in) {
                                    tmqCancelAll();
                                }
                            }
                            return true;
                        }
                        tapTile(num, false, true,false,curspr);
                        log(num+"");
                    } else if (mode == "object") {
                        // 「选框」工具：轻点空白处=放弃并回原位；轻点组内=保留待拖动
                        if (activeobjtoolmode == 1) {
                            if (mqState > 0) {
                                if (mqState == 3) mqState = 2; // 抬起未拖动 → 回到待操作态
                                Vector3 mqT = new Vector3();
                                cam.unproject(mqT.set(p1, p2, 0));
                                float[] mqG = mqGroupBounds();
                                boolean mqIn = mqG != null
                                        && mqT.x >= mqG[0] && mqT.x <= mqG[2]
                                        && mqT.y >= mqG[1] && mqT.y <= mqG[3];
                                if (!mqIn) {
                                    mqCancelAll();
                                    return true;
                                }
                            }
                            return true;
                        }
                        //tapObject(num, ae, ab);
                        // 创建：点击地图上的位置 → 显示该位置的所有宾语（几何+物理双保险命中）
                        // 命中 ≥1 条则弹出对象列表，点击任意一条进入属性界面
                        java.util.List<obj> hit = hitTestObjectsAt(ae, ab);
                        if (!hit.isEmpty()) {
                            selobjs.clear();
                            selobjs.addAll(hit);
                            requestupdatemarker = true;
                            loadList("object");
                        }
                        return true;
                    } else if (mode == "newpoly") {
                        tapNewPoly(num, ae, ab);
                    }
                    break;
                case "tile":
                case "pickanim":
                default:
                    if (tapPickUI(p1, p2)) return true;
                    tapPick(p1, p2);
                    break;

            }
        }
        //updateMinimap();
        return false;

    }

    // 点击地图命中宾语：几何命中优先（遍历对象层宾语按坐标宽高范围判断，不依赖物理 body，确保所有宾语可选中）
    // + 物理世界 AABB 补充精确匹配（用于旋转、多边形等复杂形状），合并去重
    private java.util.List<obj> hitTestObjectsAt(float ae, float ab) {
        java.util.List<obj> res = new ArrayList<obj>();
        float pad = 6f;
        // 1. 几何命中优先：按对象渲染包围盒与点击点范围判断
        if (layers != null && !layers.isEmpty() && selLayer >= 0 && selLayer < layers.size()
                && layers.get(selLayer).getType() == layer.Type.OBJECT) {
            for (obj oo : layers.get(selLayer).getObjects()) {
                if (oo == null) continue;
                // body 锚点世界坐标：x 轴为 getX()，y 轴为 -getY()+Tsh（与渲染/物理一致）
                float ax = oo.getX();
                float ay = -oo.getY() + Tsh;
                float w = oo.getW();
                float h = oo.getH();
                float minX, maxX, minY, maxY;
                String shape = oo.getShape();
                if ("image".equals(shape)) {
                    minX = ax; maxX = ax + w;
                    minY = ay; maxY = ay + h;
                } else if ("point".equals(shape)) {
                    float s = Tsh / 4f;
                    minX = ax - s; maxX = ax + s;
                    minY = ay - s; maxY = ay + s;
                } else {
                    // rectangle / ellipse / polygon / polyline / text / 默认
                    minX = ax; maxX = ax + w;
                    minY = ay - h; maxY = ay;
                }
                if (ae >= minX - pad && ae <= maxX + pad && ab >= minY - pad && ab <= maxY + pad) {
                    if (!res.contains(oo)) res.add(oo);
                }
            }
        }
        // 2. 物理补充精确匹配（Box2D AABB），合并去重
        if (world != null) {
            try {
                final java.util.List<obj> phys = new ArrayList<obj>();
                world.QueryAABB(new QueryCallback() {
                    @Override
                    public boolean reportFixture(Fixture fixture) {
                        Object ud = fixture.getUserData();
                        if (ud instanceof obj) {
                            obj oo = (obj) ud;
                            if (!phys.contains(oo)) phys.add(oo);
                        }
                        return true;
                    }
                }, ae - pad, ab - pad, ae + pad, ab + pad);
                for (obj oo : phys) {
                    if (!res.contains(oo)) res.add(oo);
                }
            } catch (Exception e) {
            }
        }
        return res;
    }

    // ==================== 「选框」批量移动工具辅助方法 ====================

    // 深拷贝宾语快照（坐标在移动前固定，供撤销与回退使用）
    private obj mqSnapshotObj(obj o) {
        obj oc = new obj();
        oc.setGid(o.getGid());
        oc.setProperties(o.getProperties());
        oc.setPoints(o.getPoints());
        oc.setWrap(o.isWrap());
        oc.setW(o.getW());
        oc.setH(o.getH());
        oc.setX(o.getX());
        oc.setY(o.getY());
        oc.setId(o.getId());
        oc.setName(o.getName());
        oc.setRotation(o.getRotation());
        oc.setShape(o.getShape());
        oc.setType(o.getType());
        oc.setText(o.getText());
        return oc;
    }

    // 宾语世界坐标包围盒（与 hitTestObjectsAt 几何命中同源：minX,minY,maxX,maxY）
    private float[] mqObjWorldBounds(obj oo) {
        float[] b = new float[]{0, 0, 0, 0};
        if (oo == null) return b;
        float ax = oo.getX();
        float ay = -oo.getY() + Tsh;
        float w = oo.getW();
        float h = oo.getH();
        String shape = oo.getShape();
        if ("image".equals(shape)) {
            b[0] = ax; b[1] = ay; b[2] = ax + w; b[3] = ay + h;
        } else if ("point".equals(shape)) {
            float s = Tsh / 4f;
            b[0] = ax - s; b[1] = ay - s; b[2] = ax + s; b[3] = ay + s;
        } else {
            b[0] = ax; b[1] = ay - h; b[2] = ax + w; b[3] = ay;
        }
        return b;
    }

    // 矩形框选命中：跨所有对象层（未锁定且可见）累加与选区矩形相交/内含的宾语
    private java.util.List<obj> hitTestObjectsInRect(float x1, float y1, float x2, float y2) {
        java.util.List<obj> res = new ArrayList<obj>();
        float minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
        float minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
        if (layers == null || layers.isEmpty()) return res;
        for (int li = 0; li < layers.size(); li++) {
            layer ly = layers.get(li);
            if (ly == null || ly.getType() != layer.Type.OBJECT) continue;
            if (ly.isLocked() || !ly.isVisible()) continue; // 锁定/隐藏的对象层不参与框选与移动
            for (obj oo : ly.getObjects()) {
                if (oo == null) continue;
                float[] bb = mqObjWorldBounds(oo);
                if (bb[2] < minX || bb[0] > maxX || bb[3] < minY || bb[1] > maxY) continue;
                if (!res.contains(oo)) res.add(oo);
            }
        }
        return res;
    }

    // 选框模式下整组的世界包围盒（用于高亮外框）
    private float[] mqGroupBounds() {
        if (selobjs == null || selobjs.isEmpty()) return null;
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE;
        float maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
        for (obj oo : selobjs) {
            float[] bb = mqObjWorldBounds(oo);
            minX = Math.min(minX, bb[0]); minY = Math.min(minY, bb[1]);
            maxX = Math.max(maxX, bb[2]); maxY = Math.max(maxY, bb[3]);
        }
        return new float[]{minX, minY, maxX, maxY};
    }

    // 数值吸附到最近网格线（step=瓦片宽/高）
    private float mqSnapAxis(float v, float step) {
        if (step <= 0f) return v;
        return Math.round(v / step) * step;
    }

    // 定位宾语所属对象层下标（框选跨层移动时按真实层写撤销历史）
    private int mqLayerIndexOf(obj oo) {
        if (layers == null || oo == null) return selLayer;
        for (int i = 0; i < layers.size(); i++) {
            layer ly = layers.get(i);
            if (ly != null && ly.getType() == layer.Type.OBJECT && ly.getObjects().contains(oo)) return i;
        }
        return selLayer;
    }

    // 世界坐标 → UI 悬浮条百分比坐标（与 uisrect/tapped 同源）
    private float[] mqWorldToUiPct(float wx, float wy) {
        Vector3 pix = cam.project(new Vector3(wx, wy, 0));
        Vector3 ui = uicam.unproject(pix);
        float px, py;
        if (!landscape) {
            px = ui.x / ssx * 100f;
            py = ui.y / ssy * 100f;
        } else {
            px = ui.x / ssy * 100f;
            py = ui.y / ssx * 100f;
        }
        return new float[]{px, py};
    }

    // 把就近的「确认放置/取消」浮钮吸附在整组外框旁：
    // 尺寸按当前视口字号自适应（「确认放置」4 字单行不换行、点击区够大），两钮间拉开间距，
    // 并避开左侧菜单列、右侧对象工具列与上/下固定工具条，避免与界面 UI 组件挤制
    private void mqUpdateFloatingButtons() {
        if (!isMqTool()) return;
        if (mqState != 2 && mqState != 3) return;
        float[] g = mqGroupBounds();
        if (g == null) return;
        float xDen = ssx, yDen = ssy;
        if (landscape) {
            xDen = ssy;
            yDen = ssx;
        }
        // 视觉字号：与创建阶段一致（字体按屏宽反推），横屏再叠加 str1draw 的 .7 缩放
        float unit = 48f * Math.min(xDen, yDen) / 1080f;
        float glyph = landscape ? unit * 0.7f : unit;
        float padX = glyph * 0.5f;                // 文字左右留白
        float bOK = 4f * glyph + padX * 2f;       // 「确认放置」4 字整行
        float bCancel = 2f * glyph + padX * 2f;   // 「取消」2 字
        if (bOK < 150f) bOK = 150f;               // 保底可点宽度
        if (bCancel < 112f) bCancel = 112f;
        float bH = Math.max( 72f, glyph * 1.8f ); // 保底可点高度
        float gap = 96f;                          // 两钮间距（防误触、防视觉拥挤）
        // 安全摆放区（百分比，0=屏顶 100=屏底）：
        //   顶部形状/选择/层级横条与底部模式/撤销重做条让位；
        //   左侧避开菜单列(竖屏 0~20 / 横屏 0~10)，右侧避开对象工具列(竖 85 起 / 横 90 起)
        float yLo = 14f, yHi = 84f;
        float xLo = landscape ? 16f : 27f;
        float xHi = landscape ? 84f : 80f;
        float total = bOK + bCancel + gap;
        float availPx = (xHi - xLo) / 100f * xDen; // 安全区内横向可用像素
        if (availPx > 0f && total > availPx) {      // 超窄屏等比收缩，保证不越界
            float k = availPx / total;
            bOK *= k;
            bCancel *= k;
            gap *= k;
            total = availPx;
        }
        float bh = bH / yDen * 100f;          // 钮高（百分比）
        float totalPct = total / xDen * 100f; // 整条宽（百分比）
        float cx = (g[0] + g[2]) / 2f;
        float padY = 30f * cam.zoom;   // 外推量约 30 屏幕像素（随缩放换算世界距离）
        // 世界 y 增大时 UI 百分比是否也增大（决定条带从锚点向哪一侧延伸）
        boolean upPos = cam.project(new Vector3(0f, g[3] + 10f, 0f)).y >= cam.project(new Vector3(0f, g[3], 0f)).y;
        float[] aT = mqWorldToUiPct(cx, g[3] + padY); // 外框顶外候选
        float[] aB = mqWorldToUiPct(cx, g[1] - padY); // 外框底外候选
        // 候选条带：顶外条带低端 yT / 底外条带低端 yB（条带高 bh，视觉上下同向）
        float yT = upPos ? aT[1] : aT[1] - bh;
        float yB = upPos ? aB[1] - bh : aB[1];
        boolean okT = yT >= yLo && yT + bh <= yHi;
        boolean okB = yB >= yLo && yB + bh <= yHi;
        boolean useTop;
        if (okT && okB) {
            useTop = Math.abs(aT[1] - 50f) <= Math.abs(aB[1] - 50f);
        } else if (okT) {
            useTop = true;
        } else if (okB) {
            useTop = false;
        } else {
            useTop = Math.abs(aT[1] - 50f) <= Math.abs(aB[1] - 50f);
        }
        float ax = useTop ? aT[0] : aB[0];
        float y = useTop ? yT : yB;
        // 横向：居中并对齐到安全区内（不压左侧菜单列 / 右侧工具列）
        float startX = ax - totalPct / 2f;
        if (startX < xLo) startX = xLo;
        if (startX + totalPct > xHi) startX = xHi - totalPct;
        if (startX < xLo) startX = xLo; // 极窄场景保底
        // 纵向：夹紧到安全区
        if (y < yLo) y = yLo;
        if (y + bh > yHi) y = yHi - bh;
        if (y < yLo) y = yLo;
        float bwOK = bOK / xDen * 100f;             // 「确认放置」钮宽（百分比）
        float bwCancel = bCancel / xDen * 100f;     // 「取消」钮宽（百分比）
        float gapPct = gap / xDen * 100f;           // 钮间距（百分比）
        gui.mqOK.setp(startX, startX + bwOK, y, y + bh);
        gui.mqCancel.setp(startX + bwOK + gapPct, startX + bwOK + gapPct + bwCancel, y, y + bh);
    }

    // 选框拉框开始点是否落在 UI 工具按钮密集区（右侧/顶部/底部），避免误拉框
    private boolean mqPressOnUi(float p1, float p2) {
        Vector3 tu = new Vector3();
        uicam.unproject(tu.set(p1, p2, 0));
        float px, py;
        if (!landscape) {
            px = tu.x / ssx * 100f;
            py = tu.y / ssy * 100f;
        } else {
            px = tu.x / ssy * 100f;
            py = tu.y / ssx * 100f;
        }
        if (px > 84f) return true;    // 右侧工具列
        if (py < 10f) return true;    // 顶部形状/层级选择横条
        if (py > 88f) return true;    // 底部模式条/撤销重做
        return false;
    }

    // 网格磁吸开关：0=自由移动 1=锁定网格。对象/图块选框共用同一开关；锁定时对象层对齐整瓦片
    private void toggleMagnetLock() {
        magnet += 1;
        if (magnet >= 2) magnet = 0;
        magnetName = (magnet == 0) ? z.free : z.lock;
        if (magnet == 0) {
            status("自由：不锁定网格，对象可像素级摆放", 1);
        } else {
            status("锁定网格：对象对齐到整瓦片，拖动到边缘可滚动地图", 1);
        }
    }

    private boolean isMqTool() {
        return activeobjtoolmode == 1 && mode != null && mode.equals("object");
    }

    // 磁吸：对象工具锁格时对齐到最近的整瓦片（四舍五入，负坐标同样准确）
    private void mqSnapToGrid(obj oo) {
        oo.setX( Math.round( oo.getX() / Tsw ) * (float) Tsw );
        oo.setY( Math.round( oo.getY() / Tsh ) * (float) Tsh );
    }

    // 移动中同步物理体（若存在）
    private void mqSyncBody(obj oo) {
        try {
            if (oo.getBody() != null) {
                oo.getBody().setTransform(oo.getX(), -oo.getY() + Tsh, oo.getBody().getAngle());
            }
        } catch (Exception e) {
        }
    }

    // 从「已框选」进入拖动预览：仅在首次拖动前备份原坐标快照
    private void mqStartMove() {
        if (selobjs == null || selobjs.isEmpty()) return;
        // 被房主禁编：禁止拖动移动对象（本地改动无法同步，会造成双方地图分叉）
        if (liveEditLocked()) { liveBanHint(); return; }
        mqNeedAsk = false;
        mqAskShown = false;
        if (mqBase.isEmpty()) { // 快照始终保持原始位置，取消时统一回退
            for (obj oo : selobjs) {
                if (oo != null) mqBase.put(oo, mqSnapshotObj(oo));
            }
        }
        if (!mqAnchorSet) { // 拖动锚点取当前手指世界点，边缘自动跟随也依赖它
            Vector3 an = new Vector3();
            cam.unproject(an.set(Gdx.input.getX(), Gdx.input.getY(), 0));
            mqAnchorX = an.x;
            mqAnchorY = an.y;
            mqAnchorSet = true;
        }
        mqState = 3;
        status("按住选区拖动整组，拖到目标位置松手后将询问放置", 3);
    }

    // 选区(对象/图块选框)拖动中：手指贴近屏幕边缘时自动平移相机并让选区跟随滚动，
    // 使整组能拖到地图任意位置而不局限于当前可见屏幕（拖动松手后的确认弹窗仍照常触发）
    private void mqAutoPanFollow() {
        try {
            if (mqAskOpen || tmqAskOpen) return;   // 确认框弹出期间禁止自动平移
            if (kartu == null || !kartu.equals("world")) return;
            boolean mqDrag = isMqTool() && mqState == 3 && mqAnchorSet && !mqBase.isEmpty();
            boolean tmqDrag = isTileMqTool() && tmqState == 3 && tmqAnchorSet;
            if (!mqDrag && !tmqDrag) return;
            if (!Gdx.input.isTouched()) return;
            float tx = Gdx.input.getX();
            float ty = Gdx.input.getY();
            int scrW = Gdx.graphics.getWidth();
            int scrH = Gdx.graphics.getHeight();
            if (scrW <= 0 || scrH <= 0) return;
            // 边缘触发带：放宽到屏幕 16%（保底 48px），滚动速度随深入边缘递增，保证长距离拖移顺畅
            int edgeX = Math.max(48, (int) (scrW * 0.16f));
            int edgeY = Math.max(48, (int) (scrH * 0.16f));
            float dpx = 0f, dpy = 0f;
            float depthX = 0f, depthY = 0f;
            if (tx < edgeX) {
                dpx = -1f;
                depthX = (edgeX - tx) / (float) edgeX;
            } else if (tx > scrW - edgeX) {
                dpx = 1f;
                depthX = (tx - (scrW - edgeX)) / (float) edgeX;
            }
            if (ty < edgeY) {
                dpy = 1f; // Gdx y=0 在顶部；向顶部拖 → 视野上移
                depthY = (edgeY - ty) / (float) edgeY;
            } else if (ty > scrH - edgeY) {
                dpy = -1f;
                depthY = (ty - (scrH - edgeY)) / (float) edgeY;
            }
            if (dpx == 0f && dpy == 0f) return;
            float depth = Math.max(depthX, depthY);
            float mv = (0.5f + 0.6f * depth) * 1500f * delta * cam.zoom; // 世界单位/帧
            cam.position.x += dpx * mv;
            cam.position.y += dpy * mv;
            // 与 pan 平移相同的边界限制：对象层可到地图外大范围，图块层夹在地图尺寸附近
            int ext = 0;
            if (layers.size() > 0 && layers.get(selLayer).getType() == layer.Type.OBJECT) ext = 10000;
            float onset = 0f;
            if (orientation != null && orientation.equalsIgnoreCase("isometric")) onset = Tsw * Tw / 2f;
            if (orientation == null || !orientation.equalsIgnoreCase("isometric")) {
                if (cam.position.x < 0 - onset - ext) cam.position.x = 0 - onset - ext;
                if (cam.position.x > Tsw * Tw - onset + ext) cam.position.x = Tsw * Tw - onset + ext;
                if (cam.position.y < -Tsh * Th - ext) cam.position.y = -Tsh * Th - ext;
                if (cam.position.y > ext) cam.position.y = ext;
            }
            cam.update();
            // 用新相机重新反投影手指位置，让整组与相机同步移动（保持相对屏幕位置继续前行）
            Vector3 tq = new Vector3();
            cam.unproject(tq.set(tx, ty, 0));
            if (mqDrag) {
                mqUpdateOffset(tq.x - mqAnchorX, tq.y - mqAnchorY);
            } else if (tmqDrag) {
                tmqUpdateOffsetTo(tmqCellX(tq.x), tmqCellY(tq.y));
            }
        } catch (Exception e) {}
    }

    // 按世界位移(右上为正)应用到每个选中宾语（对象 Y 与屏幕方向相反）
    private void mqUpdateOffset(float dxw, float dyw) {
        if (mqBase.isEmpty()) return;
        // 联机：整组一起节流（每 ~100ms 把本组所有对象的最新位置一起发出）。
        // 旧实现用共享节流逐个判断，导致每个节流周期只有“第一个”对象被发出，整组在远端严重不同步。
        boolean doSync = false;
        long now = System.currentTimeMillis();
        if (now - lastObjSyncMs >= 100) { lastObjSyncMs = now; doSync = true; }
        for (obj oo : selobjs) {
            obj base = mqBase.get(oo);
            if (oo == null || base == null) continue;
            oo.setX(base.getX() + dxw);
            oo.setY(base.getY() - dyw);
            mqSyncBody(oo);
            if (doSync) sendObjOp( "update", mqLayerIndexOf( oo ), oo );
        }
        if (dxw != 0f || dyw != 0f) mqNeedAsk = true;
    }

    // 放弃：整组回滚到原始坐标并重建物理
    private void mqRollbackOnly() {
        if (mqBase.isEmpty()) return;
        for (obj oo : selobjs) {
            obj base = mqBase.get(oo);
            if (oo == null || base == null) continue;
            oo.setX(base.getX());
            oo.setY(base.getY());
            sendObjOp("update", mqLayerIndexOf( oo ), oo); // 取消/回滚：通知远端恢复原位
        }
        mqBase.clear();
        mqAnchorSet = false;
        updateObjectCollision();
    }

    // 对象选框「继续调整」：把当前停留位置固化为新的拖动基准（丢弃旧快照），再次拖动不跳回原位；
    // 同时补发一次最终位置，保证远端与本地一致。
    private void mqKeepCurrentAsBase() {
        try {
            if (selobjs == null || selobjs.isEmpty()) return;
            if (liveEditLocked()) { liveBanHint(); return; }
            mqBase.clear();
            for (obj oo : selobjs) {
                if (oo == null) continue;
                mqBase.put(oo, mqSnapshotObj(oo));            // 以“当前位置”为新基准，避免下次拖动跳回原位
                mqSyncBody(oo);
                sendObjOp("update", mqLayerIndexOf(oo), oo);   // 补发最终位置，确保远端一致
            }
            mqAnchorSet = false;
            tmqDbg("对象继续调整 已重设基准 n=" + selobjs.size());
        } catch (Exception e) {}
    }

    // 完全取消：恢复原位并清空选择与状态
    private void mqCancelAll() {
        mqNeedAsk = false;
        mqAskShown = false;
        if (!mqBase.isEmpty()) mqRollbackOnly(); // 已拖过才回原位
        mqDown = false;
        mqState = 0;
        mqAnchorSet = false;
        mqBase.clear();
        if (selobjs != null) selobjs.clear();
        requestupdatemarker = true;
        updateMarkers();
        status("已取消", 1);
    }

    // 落定：按真实对象层写撤销历史、磁吸、重建物理、清空状态
    private void mqCommit() {
        if (selobjs == null || selobjs.isEmpty()) return;
        // 被房主禁编：放弃本次移动并回滚，避免本地已移动而远端未同步
        if (liveEditLocked()) { liveBanHint(); mqCancelAll(); return; }
        mqNeedAsk = false;
        mqAskShown = false;
        int moved = 0;
        for (obj oo : selobjs) {
            if (oo == null) continue;
            obj base = mqBase.get(oo);
            if (base == null) continue;
            pushObjHistory(base, mqLayerIndexOf(oo)); // 快照入撤销栈（跨层用真实层号）
            if (magnet == 1) mqSnapToGrid(oo);
            mqSyncBody(oo);
            sendObjOp("update", mqLayerIndexOf(oo), oo);
            moved++;
        }
        mqBase.clear();
        mqAnchorSet = false;
        updateObjectCollision();
        requestupdatemarker = true;
        updateMarkers();
        selobjs.clear();
        mqDown = false;
        mqState = 0;
        status("已移动 " + moved + " 个宾语", 3);
    }

    // 对象选框是否已相对原始位置发生位移（用于判断是否需要弹「确认放置」框）
    private boolean mqHasMoved() {
        try {
            if (mqBase == null || mqBase.isEmpty()) return false;
            for (java.util.Map.Entry<obj, obj> e : mqBase.entrySet()) {
                obj o = e.getKey();
                obj b = e.getValue();
                if (o == null || b == null) continue;
                if (Math.abs(o.getX() - b.getX()) > 0.01f || Math.abs(o.getY() - b.getY()) > 0.01f) return true;
            }
        } catch (Exception e) {}
        return false;
    }

    // 对象选框拖动松手后：弹出一次模态「确认放置」框（仅真实拖出位移才弹）
    private void mqPollAskPlace() {
        try {
            if (mqAskOpen) return;
            if (!isMqTool()) { mqNeedAsk = false; mqAskShown = false; return; }
            if (mqState != 2 && mqState != 3) { mqAskShown = false; return; }
            if (Gdx.input.isTouched()) return;                // 手指尚未松开
            if (!mqNeedAsk) return;                            // 尚未实际拖动（仅框选不打扰）
            if (mqAskShown) return;                            // 本次拖动后已弹过（直到再次拖动才允许）
            if (mqBase.isEmpty()) return;
            if (!mqHasMoved()) { mqNeedAsk = false; return; }  // 已拖回原位
            mqAskShown = true;
            Gdx.app.log( "ASKPLACE", "mqPollAskPlace: drag end, opening dialog" );
            showPlaceAskDialog( false );
        } catch (Exception e) {
            Gdx.app.log( "ASKPLACE", "mqPollAskPlace ERR: " + e, e );
        }
    }

    // 图块选框拖动松手后：弹出一次模态「确认放置」框（仅真实拖出位移才弹）
    private void tmqPollAskPlace() {
        try {
            if (tmqAskOpen) return;
            if (!isTileMqTool()) { tmqNeedAsk = false; tmqAskShown = false; return; }
            if (tmqState != 2 && tmqState != 3) { tmqAskShown = false; return; }
            if (Gdx.input.isTouched()) return;                // 手指尚未松开
            if (!tmqNeedAsk) return;                            // 尚未实际拖动
            if (tmqAskShown) return;                            // 本次拖动后已弹过
            if (!tmqMoved()) { tmqNeedAsk = false; return; }    // 已拖回原位
            tmqAskShown = true;
            Gdx.app.log( "ASKPLACE", "tmqPollAskPlace: drag end, opening dialog" );
            showPlaceAskDialog( true );
        } catch (Exception e) {
            Gdx.app.log( "ASKPLACE", "tmqPollAskPlace ERR: " + e, e );
        }
    }

    // 显示模态「确认放置」框：弹出期间输入交给 Scene2D Stage，地图手势被完全屏蔽，无法误触地图
    private void showPlaceAskDialog(final boolean tileMq) {
        try {
            Gdx.app.log( "ASKPLACE", "showPlaceAskDialog tile=" + tileMq );
            if (livePanelVisible) hideLivePanel();   // 若有联机快捷面板先关闭，避免输入处理器互相覆盖
            if (tileMq) {
                if (tmqAskOpen) return;
                tmqAskOpen = true;
                tmqAskPrev = Gdx.input.getInputProcessor();
                Gdx.input.setInputProcessor( stage );
                tmqAskDlg = new com.badlogic.gdx.scenes.scene2d.ui.Dialog( "放置确认", skin, "dialog" ) {
                    @Override
                    public void result(Object object) {
                        handlePlaceAskResult( true, object );
                    }
                };
                final com.badlogic.gdx.scenes.scene2d.ui.Dialog tmqAskRef = tmqAskDlg;
                tmqAskRef.addListener( new com.badlogic.gdx.scenes.scene2d.InputListener() {
                    @Override
                    public boolean keyDown(com.badlogic.gdx.scenes.scene2d.InputEvent event, int keycode) {
                        if (keycode == com.badlogic.gdx.Input.Keys.BACK || keycode == com.badlogic.gdx.Input.Keys.ESCAPE) {
                            handlePlaceAskResult( true, "cancel" );
                            tmqAskRef.hide();
                            return true;
                        }
                        return false;
                    }
                } );
                tmqAskDlg.text( "已移动图块选区，请确认是否放置？" );
                // 按需求：移除「继续调整」按钮，仅保留 确认放置 / 取消
                tmqAskDlg.button( "确认放置", "ok" );
                tmqAskDlg.button( "取消", "cancel" );
                tmqAskDlg.show( stage );
            } else {
                if (mqAskOpen) return;
                mqAskOpen = true;
                mqAskPrev = Gdx.input.getInputProcessor();
                Gdx.input.setInputProcessor( stage );
                mqAskDlg = new com.badlogic.gdx.scenes.scene2d.ui.Dialog( "放置确认", skin, "dialog" ) {
                    @Override
                    public void result(Object object) {
                        handlePlaceAskResult( false, object );
                    }
                };
                final com.badlogic.gdx.scenes.scene2d.ui.Dialog mqAskRef = mqAskDlg;
                mqAskRef.addListener( new com.badlogic.gdx.scenes.scene2d.InputListener() {
                    @Override
                    public boolean keyDown(com.badlogic.gdx.scenes.scene2d.InputEvent event, int keycode) {
                        if (keycode == com.badlogic.gdx.Input.Keys.BACK || keycode == com.badlogic.gdx.Input.Keys.ESCAPE) {
                            handlePlaceAskResult( false, "cancel" );
                            mqAskRef.hide();
                            return true;
                        }
                        return false;
                    }
                } );
                mqAskDlg.text( "已移动选区对象，请确认是否放置？" );
                // 按需求：移除「继续调整」按钮，仅保留 确认放置 / 取消
                mqAskDlg.button( "确认放置", "ok" );
                mqAskDlg.button( "取消", "cancel" );
                mqAskDlg.show( stage );
            }
            Gdx.app.log( "ASKPLACE", "dialog shown tile=" + tileMq );
        } catch (Exception e) {
            Gdx.app.log( "ASKPLACE", "showPlaceAskDialog ERR: " + e, e );
        }
    }

    // 确认框按钮回调：ok=落定；cancel=回原位并清空；adjust/返回键=保留当前移动待继续微调
    private void handlePlaceAskResult(final boolean tileMq, Object object) {
        try {
            Gdx.app.log( "ASKPLACE", "result tile=" + tileMq + " object=" + object );
            if (tileMq) {
                tmqAskOpen = false;
                tmqAskDlg = null;
                if (tmqAskPrev != null) { Gdx.input.setInputProcessor( tmqAskPrev ); tmqAskPrev = null; }
                tmqDbg("对话框结果=" + object + " state=" + tmqState + " ox=" + tmqOX + " oy=" + tmqOY);
                tmqNeedAsk = false;
                tmqAskShown = false;
                if (object == null || "adjust".equals( object )) {
                    tmqKeepCurrentAsBase();
                    status( "已保留当前位置，可再次按住选区拖动微调", 2 );
                } else if ("ok".equals( object )) {
                    tmqCommit();
                } else if ("cancel".equals( object )) {
                    tmqCancelAll();
                }
            } else {
                mqAskOpen = false;
                mqAskDlg = null;
                if (mqAskPrev != null) { Gdx.input.setInputProcessor( mqAskPrev ); mqAskPrev = null; }
                tmqDbg("对象对话框结果=" + object + " state=" + mqState + " sel=" + (selobjs == null ? 0 : selobjs.size()));
                mqNeedAsk = false;
                mqAskShown = false;
                if (object == null || "adjust".equals( object )) {
                    mqKeepCurrentAsBase();
                    status( "已保留当前移动，可再次按住选区拖动微调", 2 );
                } else if ("ok".equals( object )) {
                    mqCommit();
                } else if ("cancel".equals( object )) {
                    mqCancelAll();
                }
            }
        } catch (Exception e) {
            Gdx.app.log( "ASKPLACE", "handlePlaceAskResult ERR: " + e, e );
        }
    }

    // 关闭可能处于打开状态的放置确认框，并视为「保留当前移动」退出（gotoStage / 横竖屏切换等调用）
    private void dismissPlaceAskAsAdjust(boolean tileMq) {
        try {
            if (tileMq) {
                if (!tmqAskOpen) return;
                tmqAskOpen = false;
                tmqAskShown = false;
                tmqNeedAsk = false;
                com.badlogic.gdx.scenes.scene2d.ui.Dialog d = tmqAskDlg;
                tmqAskDlg = null;
                if (d != null) { try { d.hide(); } catch (Exception ignore) {} }
                if (tmqAskPrev != null) { Gdx.input.setInputProcessor( tmqAskPrev ); tmqAskPrev = null; }
                tmqKeepCurrentAsBase();
            } else {
                if (!mqAskOpen) return;
                mqAskOpen = false;
                mqAskShown = false;
                mqNeedAsk = false;
                com.badlogic.gdx.scenes.scene2d.ui.Dialog d = mqAskDlg;
                mqAskDlg = null;
                if (d != null) { try { d.hide(); } catch (Exception ignore) {} }
                if (mqAskPrev != null) { Gdx.input.setInputProcessor( mqAskPrev ); mqAskPrev = null; }
            }
        } catch (Exception e) {}
    }

    // 图块选框「继续调整」：把当前停留位置固化为新的拖动基准（丢弃旧快照），再次拖动不跳回原位
    private void tmqKeepCurrentAsBase() {
        try {
            if (!tmqMoved()) return;
            if (tmqSrc.isEmpty() || tmqLayers.isEmpty()) return;
            if (layers == null || layers.isEmpty()) return;
            int minX = Math.min(tmqX1, tmqX2) + tmqOX;
            int maxX = Math.max(tmqX1, tmqX2) + tmqOX;
            int minY = Math.min(tmqY1, tmqY2) + tmqOY;
            int maxY = Math.max(tmqY1, tmqY2) + tmqOY;
            if (!tmqInMap(minX, minY) || !tmqInMap(maxX, maxY)) return;
            tmqDbg("继续调整 基点D=[" + minX + "," + minY + ".." + maxX + "," + maxY + "] ox=" + tmqOX + " oy=" + tmqOY + " 当前非空格=" + tmqCountNonEmpty(minX, minY, maxX, maxY));
            tmqSrc.clear();
            // 联机：“继续调整”把本段移动固化为新拖动基准前，先把这段差异（原始值→当前值）同步给同房间成员。
            // 否则本段移动只存在于本地、远端毫不知情，对方后续在同一区域的编辑会基于旧视图覆盖它 → 造成图块被删除/丢失。
            syncTileDirtyToRemote();
            tmqDirty.clear();
            // 关键：把选区矩形同步到新位置。否则 tmqSrc 以“新位置”为键，而 tmqX1..Y2 仍指向旧位置，
            // 二者错位会令后续 tmqApplyPreview 读到空值，并把本应保留的已移动图块当“源区”清空 → 移动部分被删除。
            tmqX1 = minX;
            tmqX2 = maxX;
            tmqY1 = minY;
            tmqY2 = maxY;
            tmqOX = 0;
            tmqOY = 0;
            tmqAnchorSet = false;
            for (Integer li : tmqLayers) {
                int lay = li;
                layer l = layers.get( lay );
                if (l == null) continue;
                java.util.Map<Integer, long[]> map = new java.util.HashMap<Integer, long[]>();
                for (int yy = minY; yy <= maxY; yy++) {
                    for (int xx = minX; xx <= maxX; xx++) {
                        map.put( tmqCell( xx, yy ), tmqRead( lay, tmqCell( xx, yy ) ) );
                    }
                }
                tmqSrc.put( lay, map );
            }
            tmqState = 2;   // 当前位置已成为新的拖动基准
        } catch (Exception e) {}
    }

    // 圈住对象后自动平滑放大：把整组移到屏幕中心附近并放大到合适比例（只放大、不缩小），方便查看与再次拖动
    private void mqZoomToSelection() {
        if (!isMqTool()) return;
        if (mqState != 2) return;
        float[] g = mqGroupBounds();
        if (g == null) return;
        float w = g[2] - g[0];
        float h = g[3] - g[1];
        if (w <= 0f || h <= 0f) return;
        float vw = landscape ? ssy : ssx; // 可视区域宽（世界单位）
        float vh = landscape ? ssx : ssy; // 可视区域高
        // 让选区约占可用可视区域 62% 宽 / 58% 高，兼顾看清对象与留出四周操作空间
        float fx = w / (vw * 0.62f);
        float fy = h / (vh * 0.58f);
        float target = Math.max(fx, fy);
        float minZoom = Tsw / 320f; // 与双指缩放下限一致
        if (target < minZoom) target = minZoom;
        // 当前已足够近、或需要反向缩小（对象本身就铺满屏幕）时不动镜头
        if (target >= cam.zoom * 0.85f) return;
        float cx = (g[0] + g[2]) / 2f;
        float cy = (g[1] + g[3]) / 2f;
        // 目标相机中心夹紧到地图边界内（对象层可画到地图外大范围，与 mqAutoPanFollow 一致）
        float ext = 10000f;
        float onset = 0f;
        if (orientation != null && orientation.equalsIgnoreCase("isometric")) onset = Tsw * Tw / 2f;
        float halfW = vw * target / 2f;
        float halfH = vh * target / 2f;
        if (orientation == null || !orientation.equalsIgnoreCase("isometric")) {
            if (cx < -onset - ext + halfW) cx = -onset - ext + halfW;
            if (cx > Tsw * Tw - onset + ext - halfW) cx = Tsw * Tw - onset + ext - halfW;
            if (cy < -Tsh * Th - ext + halfH) cy = -Tsh * Th - ext + halfH;
            if (cy > ext - halfH) cy = ext - halfH;
        }
        panTo(cx, cy, target, 0.4f);
    }

    // 选框拉框跟随与收尾：render 每帧轮询调用。起手（mqState=1）后直接读触点坐标实时更新框，
    // 手指离开时完成圈选（含自动放大与就近浮钮）。
    private void mqPollDrag() {
        if (loadingfile || startupGuardTimer > 0) return;
        if (!isMqTool()) return;
        if (mqState != 1) return;
        if (kartu == null || !kartu.equals("world")) return;
        if (layers == null || layers.size() == 0) return;
        layer ly = layers.get(selLayer);
        if (ly == null || ly.getType() != layer.Type.OBJECT) return;
        if (Gdx.input.isTouched()) {
            Vector3 tq = new Vector3();
            cam.unproject(tq.set(Gdx.input.getX(), Gdx.input.getY(), 0));
            mqX2 = mqSnapAxis(tq.x, Tsw);
            mqY2 = mqSnapAxis(tq.y, Tsh);
            return;
        }
        // 触点已离开 → 完成拉框判定
        mqDown = false;
        float rw = Math.abs(mqX2 - mqX1);
        float rh = Math.abs(mqY2 - mqY1);
        if (rw <= Tsw * 0.5f || rh <= Tsh * 0.5f) {
            mqState = 0; // 基本原地起手未拖开 → 不圈选
            status("按住起点后拖动，松手圈住要选的对象", 2);
            return;
        }
        java.util.List<obj> hit = hitTestObjectsInRect(mqX1, mqY1, mqX2, mqY2);
        if (hit.isEmpty()) {
            mqState = 0;
            status("框内没有宾语", 1);
            return;
        }
        selobjs.clear();
        selobjs.addAll(hit);
        requestupdatemarker = true;
        updateMarkers();
        mqState = 2;
        // 用户需求：对象层选框每次选中后不进行缩放，保持当前视野
        status("已框选 " + hit.size() + " 个宾语：按住选区拖动到目标位置，松手后确认放置", 3);
    }

    // drawObjects 中叠加选区/拖动组淡蓝填充（Filled 阶段内调用）
    private void drawMqFilled() {
        if (!isMqTool()) return;
        if (mqState == 1) {
            float sx = Math.min(mqX1, mqX2), sy = Math.min(mqY1, mqY2);
            float sw = Math.abs(mqX2 - mqX1), sh = Math.abs(mqY2 - mqY1);
            if (sw <= Tsw * 0.12f && sh <= Tsh * 0.12f) { // 长按起手瞬间：仅显示起手锚点
                sr.setColor(0.95f, 0.9f, 0.2f, 0.75f);
                sr.rect(mqX1 - Tsw * 0.1f, mqY1 - Tsh * 0.1f, Tsw * 0.2f, Tsh * 0.2f);
            } else {
                sr.setColor(0.3f, 0.6f, 1f, 0.25f);
                sr.rect(sx, sy, sw, sh);
            }
        } else if (mqState == 2 || mqState == 3) {
            float[] g = mqGroupBounds();
            if (g != null) {
                sr.setColor(0.35f, 0.6f, 1f, 0.12f);
                sr.rect(g[0], g[1], g[2] - g[0], g[3] - g[1]);
            }
        }
    }

    // drawObjects 中叠加选区/拖动组蓝色描边（Line 阶段内调用）
    private void drawMqOutline() {
        if (!isMqTool()) return;
        if (mqState == 1) {
            float sx = Math.min(mqX1, mqX2), sy = Math.min(mqY1, mqY2);
            float sw = Math.abs(mqX2 - mqX1), sh = Math.abs(mqY2 - mqY1);
            if (sw <= Tsw * 0.12f && sh <= Tsh * 0.12f) {
                sr.setColor(1f, 0.95f, 0.3f, 0.95f);
                sr.rect(mqX1 - Tsw * 0.1f, mqY1 - Tsh * 0.1f, Tsw * 0.2f, Tsh * 0.2f);
            } else {
                sr.setColor(0.1f, 0.55f, 1f, 1f);
                sr.rect(sx, sy, sw, sh);
            }
        } else if (mqState == 2 || mqState == 3) {
            float[] g = mqGroupBounds();
            if (g != null) {
                sr.setColor(0.1f, 0.5f, 1f, 0.95f);
                sr.rect(g[0], g[1], g[2] - g[0], g[3] - g[1]);
            }
        }
    }

    // ==================== 「图块选框」批量移动辅助（镜像对象层选框：整格移动，连带地块/装饰等全部未锁定图块层） ====================

    // 是否处于图块选框工具激活态（仅正交地图 + 当前层为图块层时可用）
    private boolean isTileMqTool() {
        if (kartu == null || mode == null || orientation == null) return false;
        if (!tileMqOn) return false;
        if (!kartu.equals("world")) return false;
        if (!mode.equals("tile")) return false;
        if (!orientation.equalsIgnoreCase("orthogonal")) return false;
        if (layers == null || layers.isEmpty()) return false;
        if (selLayer < 0 || selLayer >= layers.size()) return false;
        layer l = layers.get(selLayer);
        return l != null && l.getType() == layer.Type.TILE;
    }

    // 世界坐标 → 格坐标（正交）
    private int tmqCellX(float wx) {
        if (Tsw <= 0) return 0;
        return (int) Math.floor(wx / Tsw);
    }

    private int tmqCellY(float wy) {
        if (Tsh <= 0) return 0;
        return (int) Math.floor((Tsh - wy) / Tsh);
    }

    private int tmqCell(int cx, int cy) {
        return cy * Tw + cx;
    }

    private boolean tmqInMap(int x, int y) {
        return x >= 0 && x < Tw && y >= 0 && y < Th;
    }

    // 图块选框：按压点是否落在 UI 密集区，避免误拉框/误拖动
    private boolean tmqPressOnUi(float p1, float p2) {
        Vector3 tu = new Vector3();
        uicam.unproject(tu.set(p1, p2, 0));
        float px, py;
        if (!landscape) {
            px = tu.x / ssx * 100f;
            py = tu.y / ssy * 100f;
        } else {
            px = tu.x / ssy * 100f;
            py = tu.y / ssx * 100f;
        }
        if (px > 84f) return true;  // 右侧工具列
        if (py < 10f) return true;  // 顶部形状/层级选择横条
        if (py > 88f) return true;  // 底部模式条/撤销重做
        return false;
    }

    // 收集参与移动的图块层（除对象层外的全部图块层，即地块层+装饰层等；未锁定且数据结构完整）
    private void tmqCollectLayers() {
        tmqLayers.clear();
        if (layers == null || layers.isEmpty()) return;
        if (Tw <= 0 || Th <= 0) return;
        for (int i = 0; i < layers.size(); i++) {
            layer ly = layers.get(i);
            if (ly == null || ly.getType() != layer.Type.TILE) continue;
            if (ly.isLocked()) continue;
            if (ly.getStr() == null || ly.getTset() == null || ly.getTile() == null) continue;
            if (ly.getStr().size() != Tw * Th || ly.getTset().size() != Tw * Th || ly.getTile().size() != Tw * Th) continue;
            tmqLayers.add(i);
        }
    }

    private long[] tmqRead(int lay, int cell) {
        layer l = layers.get(lay);
        return new long[]{l.getStr().get(cell), l.getTset().get(cell), l.getTile().get(cell)};
    }

    // 直接写格子并刷新显示缓存（预览期间不产生撤销历史，由提交统一入栈）
    private void tmqWrite(int lay, int cell, long gid, long tset, long tile) {
        layer l = layers.get(lay);
        if (l == null) return;
        if (l.getStr() == null || l.getTset() == null || l.getTile() == null) return;
        if (cell < 0 || cell >= Tw * Th) return;
        if (cell >= l.getStr().size() || cell >= l.getTset().size() || cell >= l.getTile().size()) return;
        l.getStr().set(cell, gid);
        l.getTset().set(cell, (int) tset);
        l.getTile().set(cell, (int) tile);
        updateCache(cell);
    }

    private java.util.Map<Integer, long[]> tmqLayerMap(
            java.util.Map<Integer, java.util.Map<Integer, long[]>> m, int lay) {
        java.util.Map<Integer, long[]> im = m.get(lay);
        if (im == null) {
            im = new java.util.HashMap<Integer, long[]>();
            m.put(lay, im);
        }
        return im;
    }

    // 恢复预览期间所有被改格子的原始值
    private void tmqRestoreDirty() {
        if (tmqDirty == null || tmqDirty.isEmpty()) return;
        for (java.util.Map.Entry<Integer, java.util.Map<Integer, long[]>> e : tmqDirty.entrySet()) {
            int lay = e.getKey();
            if (lay < 0 || lay >= layers.size()) continue;
            for (java.util.Map.Entry<Integer, long[]> c : e.getValue().entrySet()) {
                int cell = c.getKey();
                if (cell < 0 || cell >= Tw * Th) continue;
                long[] o = c.getValue();
                tmqWrite(lay, cell, o[0], o[1], o[2]);
            }
        }
        tmqDirty.clear();
    }

    private void tmqMarkDirty(int lay, int cell, long[] orig) {
        java.util.Map<Integer, long[]> im = tmqLayerMap(tmqDirty, lay);
        if (!im.containsKey(cell)) im.put(cell, orig);
    }

    // 按当前偏移(tmqOX/tmqOY)重算预览：先还原脏格→把源快照贴到目标区→把源区里非目标格子清空
    private void tmqApplyPreview() {
        if (tmqSrc == null || tmqSrc.isEmpty()) return;
        if (tmqLayers.isEmpty()) return;
        tmqRestoreDirty();
        int minX = Math.min(tmqX1, tmqX2), maxX = Math.max(tmqX1, tmqX2);
        int minY = Math.min(tmqY1, tmqY2), maxY = Math.max(tmqY1, tmqY2);
        int ox = tmqOX, oy = tmqOY;
        // 目标绝对格集合（用于判断源区哪些格子需要被清空）
        java.util.Set<Integer> dest = new java.util.HashSet<Integer>();
        for (int yy = minY; yy <= maxY; yy++) {
            for (int xx = minX; xx <= maxX; xx++) {
                int nx = xx + ox, ny = yy + oy;
                if (!tmqInMap(nx, ny)) continue;
                dest.add(tmqCell(nx, ny));
            }
        }
        for (Integer li : tmqLayers) {
            int lay = li;
            layer l = layers.get(lay);
            if (l == null) continue;
            java.util.Map<Integer, long[]> src = tmqSrc.get(lay);
            if (src == null) continue;
            // 1) 目标区写入源内容
            for (int yy = minY; yy <= maxY; yy++) {
                for (int xx = minX; xx <= maxX; xx++) {
                    int nx = xx + ox, ny = yy + oy;
                    if (!tmqInMap(nx, ny)) continue;
                    int dstCell = tmqCell(nx, ny);
                    long[] v = src.get(tmqCell(xx, yy));
                    if (v == null) continue;
                    long[] cur = tmqRead(lay, dstCell);
                    if (cur[0] == v[0] && cur[1] == v[1] && cur[2] == v[2]) continue;
                    tmqMarkDirty(lay, dstCell, cur);
                    tmqWrite(lay, dstCell, v[0], v[1], v[2]);
                }
            }
            // 2) 源区中不属于目标区域的格子清空（拖动重叠时也保持正确语义）
            for (int yy = minY; yy <= maxY; yy++) {
                for (int xx = minX; xx <= maxX; xx++) {
                    int srcCell = tmqCell(xx, yy);
                    if (dest.contains(srcCell)) continue;
                    long[] cur = tmqRead(lay, srcCell);
                    if (cur[0] == 0 && cur[1] == -1 && cur[2] == -1) continue;
                    tmqMarkDirty(lay, srcCell, cur);
                    tmqWrite(lay, srcCell, 0, -1, -1);
                }
            }
        }
        markEditActivity(); // 选中图块拖动预览会改写本地数据但尚未发送给远端：标记为编辑活动，避免自动同步检测误判
        cacheTiles(); // 预览已刷新到数据：立即重建受影响瓦片缓存，保证跟手显示
    }

    // 选区外框世界坐标 [minX,minY,maxX,maxY]：target=false 为源框，true 为目标框（含当前偏移）
    private float[] tmqRectWorld(boolean target) {
        int minX = Math.min(tmqX1, tmqX2), maxX = Math.max(tmqX1, tmqX2);
        int minY = Math.min(tmqY1, tmqY2), maxY = Math.max(tmqY1, tmqY2);
        if (target) {
            minX += tmqOX; maxX += tmqOX;
            minY += tmqOY; maxY += tmqOY;
        }
        float wx0 = minX * Tsw;
        float wy0 = Tsh - (maxY + 1) * Tsh;
        float wx1 = (maxX + 1) * Tsw;
        float wy1 = Tsh - minY * Tsh;
        return new float[]{wx0, wy0, wx1, wy1};
    }

    // 长按地图起手拉框（格坐标起点）
    private void tmqStartDraw(float p1, float p2) {
        if (!isTileMqTool()) return;
        // 被房主禁编：禁止图块选框移动
        if (liveEditLocked()) { liveBanHint(); return; }
        tmqCollectLayers();
        if (tmqLayers.isEmpty()) {
            status("没有可移动的图块层（图块层均被锁定）", 1);
            return;
        }
        Vector3 tq = new Vector3();
        cam.unproject(tq.set(p1, p2, 0));
        int cx = tmqCellX(tq.x);
        int cy = tmqCellY(tq.y);
        if (!tmqInMap(cx, cy)) return;
        tmqX1 = tmqX2 = cx;
        tmqY1 = tmqY2 = cy;
        tmqOX = 0;
        tmqOY = 0;
        tmqState = 1;
        Gdx.input.vibrate(25);
        status("已起手：拖动圈住要移动的地块，松开进入选区", 2);
    }

    // render 每帧轮询：拉框跟随（长按后 pan 会被吞掉，只能轮询触点）与手指离开完成圈选
    private void tmqPollDraw() {
        if (loadingfile || startupGuardTimer > 0) return;
        if (!isTileMqTool()) return;
        if (tmqState != 1) return;
        if (tmqLayers.isEmpty()) return;
        if (Gdx.input.isTouched()) {
            Vector3 tq = new Vector3();
            cam.unproject(tq.set(Gdx.input.getX(), Gdx.input.getY(), 0));
            tmqX2 = tmqCellX(tq.x);
            tmqY2 = tmqCellY(tq.y);
            return;
        }
        // 触点离开 → 完成圈选
        int minX = Math.min(tmqX1, tmqX2), maxX = Math.max(tmqX1, tmqX2);
        int minY = Math.min(tmqY1, tmqY2), maxY = Math.max(tmqY1, tmqY2);
        if (!tmqInMap(minX, minY) || !tmqInMap(maxX, maxY)) {
            tmqState = 0;
            status("框选超出地图范围，已取消", 1);
            return;
        }
        if (minX == maxX && minY == maxY) {
            tmqState = 0;
            status("按住起点后拖动，框选要移动的地块", 2);
            return;
        }
        tmqX1 = minX; tmqY1 = minY; tmqX2 = maxX; tmqY2 = maxY;
        tmqOX = 0; tmqOY = 0;
        tmqState = 2;
        int w = maxX - minX + 1, h = maxY - minY + 1;
        status("已框选 " + w + "x" + h + " 格（含全部图块层）：拖动到目标位置，松手后确认放置", 3);
    }

    // 选区内容是否已相对源位置发生位移
    private boolean tmqMoved() {
        return tmqOX != 0 || tmqOY != 0;
    }

    // 开始拖动：快照源区内容（仅首次），并记录手指锚点（格坐标）
    private void tmqStartMove() {
        if (tmqState < 2) return;
        if (liveEditLocked()) { liveBanHint(); return; }
        tmqDbg("开始拖动 state=" + tmqState + " ox=" + tmqOX + " oy=" + tmqOY + " sel=[" + tmqX1 + "," + tmqY1 + ".." + tmqX2 + "," + tmqY2 + "] dirty=" + (tmqDirty == null ? 0 : tmqDirty.size()) + " src=" + (tmqSrc == null ? 0 : tmqSrc.size()));
        tmqNeedAsk = false;
        tmqAskShown = false;
        // 若已有预览位移后再抓取（state3）：先把内容还原回源位，从源区按新锚点重新拖动，避免叠加旧偏移
        if (tmqState == 3 && (tmqOX != 0 || tmqOY != 0)
                && tmqDirty != null && !tmqDirty.isEmpty()) {
            tmqRestoreDirty();
            cacheTiles();
        }
        tmqOX = 0;
        tmqOY = 0;
        if (tmqSrc.isEmpty()) {
            tmqCollectLayers();
            if (tmqLayers.isEmpty()) {
                tmqCancelAll();
                return;
            }
            int minX = Math.min(tmqX1, tmqX2), maxX = Math.max(tmqX1, tmqX2);
            int minY = Math.min(tmqY1, tmqY2), maxY = Math.max(tmqY1, tmqY2);
            for (Integer li : tmqLayers) {
                int lay = li;
                layer l = layers.get(lay);
                if (l == null) continue;
                java.util.Map<Integer, long[]> map = new java.util.HashMap<Integer, long[]>();
                for (int yy = minY; yy <= maxY; yy++) {
                    for (int xx = minX; xx <= maxX; xx++) {
                        int cell = tmqCell(xx, yy);
                        map.put(cell, tmqRead(lay, cell));
                    }
                }
                tmqSrc.put(lay, map);
            }
        }
        Vector3 tq = new Vector3();
        cam.unproject(tq.set(Gdx.input.getX(), Gdx.input.getY(), 0));
        tmqAnchorX = tmqCellX(tq.x);
        tmqAnchorY = tmqCellY(tq.y);
        tmqAnchorSet = true;
        tmqOX = 0;
        tmqOY = 0;
        tmqState = 3;
        status("按住拖动整块图块（含装饰层），松手后将询问放置", 3);
    }

    // 按当前手指格子更新偏移（整格移动，夹紧在地图内）
    private void tmqUpdateOffsetTo(int cellX, int cellY) {
        if (!tmqAnchorSet) return;
        int minX = Math.min(tmqX1, tmqX2), maxX = Math.max(tmqX1, tmqX2);
        int minY = Math.min(tmqY1, tmqY2), maxY = Math.max(tmqY1, tmqY2);
        int ox = cellX - tmqAnchorX;
        int oy = cellY - tmqAnchorY;
        if (ox < -minX) ox = -minX;
        if (ox > Tw - 1 - maxX) ox = Tw - 1 - maxX;
        if (oy < -minY) oy = -minY;
        if (oy > Th - 1 - maxY) oy = Th - 1 - maxY;
        if (ox == tmqOX && oy == tmqOY) return;
        tmqOX = ox;
        tmqOY = oy;
        if (ox != 0 || oy != 0) tmqNeedAsk = true;
        tmqApplyPreview();
    }

    // render 每帧轮询：拖动预览跟随（state3 且手指按住）
    private void tmqPollMove() {
        if (loadingfile || startupGuardTimer > 0) return;
        if (mqAskOpen || tmqAskOpen) return;   // 确认框弹出期间禁止地图拖动
        if (!isTileMqTool()) return;
        if (tmqState != 3 || !tmqAnchorSet) return;
        if (!Gdx.input.isTouched()) return;
        Vector3 tq = new Vector3();
        cam.unproject(tq.set(Gdx.input.getX(), Gdx.input.getY(), 0));
        tmqUpdateOffsetTo(tmqCellX(tq.x), tmqCellY(tq.y));
    }

    // 取消：把预览期间改动全部还原并清空状态
    private void tmqCancelAll() {
        tmqNeedAsk = false;
        tmqAskShown = false;
        boolean had = (tmqState > 0);
        boolean moved = (tmqState == 3 && tmqDirty != null && !tmqDirty.isEmpty());
        if (moved) {
            // 并发时远端可能已改了同格：把回退结果也同步过去，保证两端收敛（本地取消优先）
            syncTileRevertToRemote();
            tmqRestoreDirty();
            cacheTiles(); // 预览改动已还原，立即重建缓存避免残留旧画面
        }
        tmqDirty.clear();
        tmqSrc.clear();
        tmqLayers.clear();
        tmqAnchorSet = false;
        tmqOX = 0;
        tmqOY = 0;
        tmqState = 0;
        if (had) status("已取消", 1);
    }

    // 取消前把“当前预览值 -> 原始值”的差异发给同房间成员，避免本地已回退而远端停留在预览值（两端分叉）
    private void syncTileRevertToRemote() {
        try {
            if (tmqDirty == null || tmqDirty.isEmpty()) return;
            if (!isClient || !(isCreateRoom || isJoinRoom)) return;
            for (java.util.Map.Entry<Integer, java.util.Map<Integer, long[]>> e : tmqDirty.entrySet()) {
                int lay = e.getKey();
                if (lay < 0 || lay >= layers.size()) continue;
                layer l = layers.get( lay );
                if (l == null || l.getStr() == null || l.getTset() == null || l.getTile() == null) continue;
                for (java.util.Map.Entry<Integer, long[]> c : e.getValue().entrySet()) {
                    int cell = c.getKey();
                    if (cell < 0 || cell >= Tw * Th) continue;
                    if (cell >= l.getStr().size() || cell >= l.getTset().size() || cell >= l.getTile().size()) continue;
                    long curGid = l.getStr().get( cell );
                    int curTset = l.getTset().get( cell );
                    int curTile = l.getTile().get( cell );
                    long[] o = c.getValue();
                    if (curGid == o[0] && curTset == o[1] && curTile == o[2]) continue;
                    uploaddata( new layerhistory( true, lay, cell, curGid, o[0], curTset, (int) o[1], curTile, (int) o[2] ) );
                }
            }
        } catch (Exception ignore) {}
    }

    // 把当前 tmqDirty（相对本段基准的差异）逐格同步给同房间成员（“继续调整”固化为新基准前调用）
    private void syncTileDirtyToRemote() {
        try {
            if (tmqDirty == null || tmqDirty.isEmpty()) return;
            if (!isClient || !(isCreateRoom || isJoinRoom)) return;
            for (java.util.Map.Entry<Integer, java.util.Map<Integer, long[]>> e : tmqDirty.entrySet()) {
                int lay = e.getKey();
                if (lay < 0 || lay >= layers.size()) continue;
                layer l = layers.get( lay );
                if (l == null || l.getStr() == null || l.getTset() == null || l.getTile() == null) continue;
                for (java.util.Map.Entry<Integer, long[]> c : e.getValue().entrySet()) {
                    int cell = c.getKey();
                    if (cell < 0 || cell >= Tw * Th) continue;
                    if (cell >= l.getStr().size() || cell >= l.getTset().size() || cell >= l.getTile().size()) continue;
                    long[] o = c.getValue();
                    long curGid = l.getStr().get( cell );
                    int curTset = l.getTset().get( cell );
                    int curTile = l.getTile().get( cell );
                    if (curGid == o[0] && curTset == o[1] && curTile == o[2]) continue;
                    uploaddata( new layerhistory( true, lay, cell, o[0], curGid, (int) o[1], curTset, (int) o[2], curTile ) );
                }
            }
        } catch (Exception ignore) {}
    }

    // ===== 【临时诊断】图块选框关键步骤落盘日志（定位“继续调整导致删除”），不影响逻辑 =====
    private void tmqDbg(String s) {
        try {
            String tag = (isClient && (isCreateRoom || isJoinRoom)) ? "MP" : "SP";
            String line = System.currentTimeMillis() + " [" + tag + "] " + s + "\n";
            com.badlogic.gdx.files.FileHandle fh = Gdx.files.absolute( basepath + "NotTiled/tmq_debug.log" );
            String old = fh.exists() ? fh.readString() : "";
            old += line;
            int n = 0;
            for (int i = 0; i < old.length(); i++) if (old.charAt(i) == '\n') n++;
            while (n > 300) { int idx = old.indexOf('\n'); if (idx < 0) break; old = old.substring(idx + 1); n--; }
            fh.writeString( old, false );
        } catch (Exception ignore) {}
    }

    // 统计指定选区(lay 集合内)非空图块数（诊断用）
    private int tmqCountNonEmpty(int minX, int minY, int maxX, int maxY) {
        int ne = 0;
        try {
            for (Integer li : tmqLayers) {
                int lay = li;
                layer l = layers.get( lay );
                if (l == null || l.getStr() == null) continue;
                for (int yy = minY; yy <= maxY; yy++)
                    for (int xx = minX; xx <= maxX; xx++) {
                        int c = tmqCell( xx, yy );
                        if (c >= 0 && c < l.getStr().size() && l.getStr().get( c ) > 0) ne++;
                    }
            }
        } catch (Exception ignore) {}
        return ne;
    }

    // 退出图块选框工具（切其它画笔/图层时调用）
    private void tmqTurnOff() {
        tmqCancelAll();
        tileMqOn = false;
        roll = false;   // 避免残留“画笔拖画”标记
    }

    // 落定：把脏格的原始值→当前值作为整段撤销历史入栈（首条非 follower，其余 follower）
    private void tmqCommit() {
        if (tmqState != 2 && tmqState != 3) return;
        // 被房主禁编：放弃本次图块移动并还原
        if (liveEditLocked()) { liveBanHint(); tmqCancelAll(); return; }
        tmqNeedAsk = false;
        tmqAskShown = false;
        if (tmqSrc.isEmpty()) {
            tmqCancelAll();
            return;
        }
        int changed = 0;
        boolean first = true;
        if (tmqDirty != null && !tmqDirty.isEmpty()) {
            for (java.util.Map.Entry<Integer, java.util.Map<Integer, long[]>> e : tmqDirty.entrySet()) {
                int lay = e.getKey();
                if (lay < 0 || lay >= layers.size()) continue;
                layer l = layers.get(lay);
                if (l == null) continue;
                for (java.util.Map.Entry<Integer, long[]> c : e.getValue().entrySet()) {
                    int cell = c.getKey();
                    if (cell < 0 || cell >= Tw * Th) continue;
                    long[] o = c.getValue();
                    long curGid = l.getStr().get(cell);
                    int curTset = l.getTset().get(cell);
                    int curTile = l.getTile().get(cell);
                    if (curGid == o[0] && curTset == o[1] && curTile == o[2]) continue;
                    layerhistory lh = new layerhistory(!first, lay, cell, o[0], curGid, (int) o[1], curTset, (int) o[2], curTile);
                    undolayer.add(lh);
                    uploaddata(lh); // 图块选框整块移动：逐格同步给同房间成员，避免远端看不到
                    first = false;
                    changed++;
                }
            }
        }
        if (changed > 0) {
            redolayer.clear();
            cacheTiles(); // 落定后立即重建缓存，确保显示与数据一致
        }
        tmqDirty.clear();
        tmqSrc.clear();
        tmqLayers.clear();
        tmqAnchorSet = false;
        tmqOX = 0;
        tmqOY = 0;
        tmqState = 0;
        if (changed > 0) {
            status("已移动 " + changed + " 格图块（含装饰层），可撤销", 3);
        } else {
            status("未移动任何地块", 1);
        }
    }

    // 浮钮「确认放置/取消」就近吸附到选区旁（与对象层选框同源几何）
    private void tmqUpdateFloatingButtons() {
        if (!isTileMqTool()) return;
        if (tmqState != 2 && tmqState != 3) return;
        float[] g = tmqRectWorld(tmqState == 3);
        float xDen = ssx, yDen = ssy;
        if (landscape) {
            xDen = ssy;
            yDen = ssx;
        }
        float bw = 120f / xDen * 100f;
        float gap = 72f / xDen * 100f;
        float bh = 58f / yDen * 100f;
        float total = bw * 2f + gap;
        float xLo = 2f, xHi = 80f;
        float yLo = 12f, yHi = 86f;
        float cx = (g[0] + g[2]) / 2f;
        float padY = 32f * cam.zoom;
        boolean upPos = cam.project(new Vector3(0f, g[3] + 10f, 0f)).y >= cam.project(new Vector3(0f, g[3], 0f)).y;
        float[] aT = mqWorldToUiPct(cx, g[3] + padY);
        float[] aB = mqWorldToUiPct(cx, g[1] - padY);
        float yT = upPos ? aT[1] : aT[1] - bh;
        float yB = upPos ? aB[1] - bh : aB[1];
        boolean okT = yT >= yLo && yT + bh <= yHi;
        boolean okB = yB >= yLo && yB + bh <= yHi;
        boolean useTop;
        if (okT && okB) {
            useTop = Math.abs(aT[1] - 50f) <= Math.abs(aB[1] - 50f);
        } else if (okT) {
            useTop = true;
        } else if (okB) {
            useTop = false;
        } else {
            useTop = Math.abs(aT[1] - 50f) <= Math.abs(aB[1] - 50f);
        }
        float ax = useTop ? aT[0] : aB[0];
        float y = useTop ? yT : yB;
        float startX = ax - total / 2f;
        if (startX < xLo) startX = xLo;
        if (startX + total > xHi) startX = xHi - total;
        if (startX < xLo) startX = xLo;
        if (y < yLo) y = yLo;
        if (y + bh > yHi) y = yHi - bh;
        if (y < yLo) y = yLo;
        gui.mqOK.setp(startX, startX + bw, y, y + bh);
        gui.mqCancel.setp(startX + bw + gap, startX + bw + gap + bw, y, y + bh);
    }

    // 渲染层叠加：拉框/选区/目标区蓝色描边与淡蓝填充（在地块渲染后、对象渲染前绘制）
    private void drawTileMq() {
        if (!isTileMqTool()) return;
        if (tmqState < 1) return;
        Gdx.gl.glEnable(GL20.GL_BLEND);
        Gdx.gl.glBlendFunc(GL20.GL_SRC_ALPHA, GL20.GL_ONE_MINUS_SRC_ALPHA);
        sr.setProjectionMatrix(cam.combined);
        // 淡蓝填充
        sr.begin(ShapeRenderer.ShapeType.Filled);
        if (tmqState == 1) {
            float[] a = tmqRectWorld(false);
            float w = a[2] - a[0], h = a[3] - a[1];
            if (w <= Tsw * 0.1f && h <= Tsh * 0.1f) {
                sr.setColor(0.95f, 0.9f, 0.2f, 0.7f);
                sr.rect(a[0] - Tsw * 0.1f, a[1] - Tsh * 0.1f, Tsw * 0.2f, Tsh * 0.2f);
            } else {
                sr.setColor(0.3f, 0.6f, 1f, 0.22f);
                sr.rect(a[0], a[1], w, h);
            }
        } else {
            float[] dst = tmqRectWorld(true);
            sr.setColor(0.35f, 0.6f, 1f, 0.15f);
            sr.rect(dst[0], dst[1], dst[2] - dst[0], dst[3] - dst[1]);
            if (tmqMoved()) {
                float[] src = tmqRectWorld(false);
                sr.setColor(0.5f, 0.5f, 0.5f, 0.08f);
                sr.rect(src[0], src[1], src[2] - src[0], src[3] - src[1]);
            }
        }
        sr.end();
        // 亮蓝描边
        sr.begin(ShapeRenderer.ShapeType.Line);
        if (tmqState == 1) {
            float[] a = tmqRectWorld(false);
            float w = a[2] - a[0], h = a[3] - a[1];
            if (w <= Tsw * 0.1f && h <= Tsh * 0.1f) {
                sr.setColor(1f, 0.95f, 0.3f, 0.95f);
                sr.rect(a[0] - Tsw * 0.1f, a[1] - Tsh * 0.1f, Tsw * 0.2f, Tsh * 0.2f);
            } else {
                sr.setColor(0.1f, 0.55f, 1f, 1f);
                sr.rect(a[0], a[1], w, h);
            }
        } else {
            float[] dst = tmqRectWorld(true);
            sr.setColor(0.1f, 0.5f, 1f, 0.95f);
            sr.rect(dst[0], dst[1], dst[2] - dst[0], dst[3] - dst[1]);
            if (tmqMoved()) {
                float[] src = tmqRectWorld(false);
                sr.setColor(0.6f, 0.6f, 0.6f, 0.55f);
                sr.rect(src[0], src[1], src[2] - src[0], src[3] - src[1]);
            }
        }
        sr.end();
        Gdx.gl.glDisable(GL20.GL_BLEND);
    }

    private boolean tapNewPoly(Integer num, int ae, int ab) {
        obj nyok = newobject;
        if (magnet == 1) {
            switch (nyok.getShape()) {
                case "polygon":
                case "polyline":
                    int a = ae - (int) nyok.getX();
                    int b = -ab - (int) nyok.getY() + Tsh;
                    if (a < 0) a -= Tsw;
                    if (b < 0) b -= Tsh;
                    int x = (a / Tsw) * Tsw;
                    int y = (b / Tsh) * Tsh;

                    nyok.addPoint(x, y);
                    sendObjOp("update", selLayer, nyok);
                    break;

            }
        } else {
            nyok.addPoint((int) ae - nyok.getX(), -(int) ab + Tsh - nyok.getY());
            sendObjOp("update", selLayer, nyok);

        }
        return false;
    }

    private void recenterpick() {
        try {
            if (tilesets.size() == 0) return;
            float ttsw = tilesets.get(seltset).getTilewidth();
            float ttsh = tilesets.get(seltset).getTileheight();
            float ttkw = tilesets.get(seltset).getWidth();
            float ttkh = tilesets.get(seltset).getHeight();

            if (pickAuto) {
                ttkw = 6;
                ttkh = tilesets.get(seltset).getTerrains().size();
            }


            panTileTo((int) ttsw * ttkw / 2, (int) -(ttsh * ttkh / 2) + (ttsh), .5f);
        }catch(Exception e){}
    }

