    public static double roundToHalf(double d) {
        return Math.round(d * 2) / 2.0;
    }

    // 当前活动层是否为 RW 单位对象层（UnitObjects）
    private boolean isUnitObjectsLayer() {
        try {
            if (layers == null || layers.isEmpty()) return false;
            layer l = layers.get(selLayer);
            if (l == null || l.getType() != layer.Type.OBJECT) return false;
            String nm = l.getName();
            return nm != null && nm.equalsIgnoreCase("UnitObjects");
        } catch (Exception e) {
            return false;
        }
    }

    // UnitObjects 层新建宾语自动带上 unit / team 两个默认属性（已有同名属性则跳过，不覆盖）
    private void ensureUnitObjectDefaults(obj o) {
        if (!isUnitObjectsLayer() || o == null) return;
        java.util.List<property> ps = o.getProperties();
        if (ps == null) {
            ps = new java.util.ArrayList<property>();
            o.setProperties(ps);
        }
        boolean hasUnit = false, hasTeam = false;
        for (property p : ps) {
            if (p == null || p.getName() == null) continue;
            if (p.getName().equalsIgnoreCase("unit")) hasUnit = true;
            else if (p.getName().equalsIgnoreCase("team")) hasTeam = true;
        }
        if (!hasUnit) ps.add(new property("unit", "String", ""));
        if (!hasTeam) ps.add(new property("team", "String", "0"));
    }

