    public void updateTileData(int lay, int num, long str, int tsetID) {
        // 防御：非法图层/格子/图集直接忽略，防止越界访问 tilesets/图层数组
        if (lay < 0 || lay >= layers.size()) return;
        if (num < 0 || num >= Tw * Th) return;
        if (str != 0 && (tsetID < 0 || tsetID >= tilesets.size())) return;
        int newtile=-1;

        if (str!=0) {
            tileset ts = tilesets.get(tsetID);
            if (ts != null && ts.getTiles() != null && ts.getTiles().size() > 0) {
                for (int j = 0; j < ts.getTiles().size(); j++) {
                    tile tt = ts.getTiles().get(j);
                    if (tt.getTileID() + ts.getFirstgid() == str) {
                        newtile = j;
                        break;
                    }
                }
            }
        }

        updateTileData(lay,num,str,tsetID,newtile);
    }
    public void updateTileData(int lay, int num, long str, int tsetID, int tileID){
        // 被房主禁编：本地不应用任何平铺写入，避免与其它端地图分叉（此前仅拦截网络发送，导致本地已改而他人不可见）
        if (liveEditLocked()) { liveBanHint(); return; }
        // 防御：所有平铺写入(画笔/选区/填充/自动补边/远程同步)都汇到这里，
        // 在源头拦住非法图层/格子/数据长度，即可避免联动历史、网络上传与缓存刷新时的越界闪退
        if (lay < 0 || lay >= layers.size()) return;
        layer l = layers.get( lay );
        if (l == null) return;
        if (l.getStr() == null || l.getTset() == null || l.getTile() == null) return;
        if (num < 0 || num >= Tw * Th) return;
        if (num >= l.getStr().size() || num >= l.getTset().size() || num >= l.getTile().size()) return;
        if (str != 0 && (tsetID < 0 || tsetID >= tilesets.size())) return;
        if (str == 0) tsetID = -1;
        //retrieve layer for cleaner code.

        ////////////////RECORD HISTORY FOR UNDO REDO//////////////
        //get current info
        Long oldStr = l.getStr().get( num );
        int oldTset = l.getTset().get( num );
        int oldTile = l.getTile().get( num );

        ////////////////update cached tile data//////////////////
        if (str==0) tsetID=-1;

        l.getStr().set( num, str );
        l.getTset().set( num, tsetID );
        l.getTile().set(num, tileID);



        ////////////////////RECORD HISTORY//////////////////////////
        layerhistory lh2 = new layerhistory( follower, lay, num, oldStr, str, oldTset, tsetID, oldTile, tileID );

        if (oldStr != str) {
            undolayer.add( lh2 );
            uploaddata( lh2 );
            redolayer.clear();
            follower = true;
            try { recentLocalCells.put( drawCellKey(lay, num), System.currentTimeMillis() ); } catch (Exception ignore) {}
        }

        /////////////////////update graphic cache///////////////////
        updateCache( num );

    }

