    private boolean newTerrainify(int num, tile nx, int[] directions, boolean fill) {
        if (!nx.isTerrainForEditor()) return false;
        if (!nx.isCenter()) return true;
        java.util.List<Integer> lint = new ArrayList<>();
        int[] aa = null, bb=null, cc=null;

        if (nx != null) {
            if (nx.isTerrainForEditor()) {
                aa = nx.getTerrain();
            }
        }
        if (aa == null) aa = new int[]{-1, -1, -1, -1};

        for (int i : directions) { //check start here
            int gogo = num;
            switch (i) {
                case 0:
                    if (num <= Tw || num % Tw == 0) continue;
                    gogo = num - Tw - 1;
                    break;
                case 1:
                    if (num <= Tw) continue;
                    gogo = num - Tw;
                    break;
                case 2:
                    if (num <= Tw || num % Tw == Tw - 1) continue;
                    gogo = num - Tw + 1;
                    break;
                case 3:
                    if (num <= 1 || num % Tw == 0) continue;
                    gogo = num - 1;
                    break;
                case 4:
                    if (num >= Tw * Th || num % Tw == Tw - 1) continue;
                    gogo = num + 1;
                    break;
                case 5:
                    if (num >= Tw * Th - Tw || num % Tw == 0) continue;
                    gogo = num + Tw - 1;
                    break;
                case 6:
                    if (num >= Tw * Th - Tw) continue;
                    gogo = num + Tw;
                    break;
                case 7:
                    if (num >= Tw * Th - Tw || num % Tw == Tw - 1) continue;
                    gogo = num + Tw + 1;
                    break;
                case 8:
                    gogo = num;
                    break;
            }

            bb = safeNeighborTerrain( gogo, new int[]{-1, -1, -1, -1} );
            cc = terrainInt(i, aa, bb);

            ///
            lint.clear();
            for (int u = 0; u < tilesets.get(curtset).getTiles().size(); u++) {
                tile x = tilesets.get(curtset).getTiles().get(u);
                if (x.getTerrainString().equalsIgnoreCase(cc[0] + "," + cc[1] + "," + cc[2] + "," + cc[3])) {
                    lint.add(u);
                }
            }
            //if it is found.
            if (lint.size() > 0) {
                int tileindex = lint.get((int) (Math.random() * lint.size()));
                tile y = tilesets.get(curtset).getTiles().get(tileindex);
                updateTileData(selLayer, gogo, (long) y.getTileID() + tilesets.get(curtset).getFirstgid(), curtset, tileindex);
            }else{
                // do nothing if it is not found because of inadequate terrain

                List<Integer> ll = new ArrayList<>();
                for (int d=0;d<4;d++){
                    if (!ll.contains(cc[d])) ll.add(d);
                }
                //if there is a foreign tile
                if (ll.size()>2){
                }

            }
            ///

        }

        return false;

        //

    }

    // 安全读取邻格地形：按邻格自身所属 tileset 与内部索引读取，
    // 防止跨 tileset（自动平铺刷到非本图集/未配置的地块上）导致索引越界闪退。
    private int[] safeNeighborTerrain(int cell, int[] fallback) {
        try {
            if (cell < 0 || cell >= Tw * Th) return fallback;
            if (selLayer < 0 || selLayer >= layers.size()) return fallback;
            layer gLayer = layers.get( selLayer );
            if (gLayer == null) return fallback;
            java.util.List<Integer> gtileL = gLayer.getTile();
            java.util.List<Integer> gtsetL = gLayer.getTset();
            if (gtileL == null || gtsetL == null) return fallback;
            int gtil = gtileL.get( cell );
            if (gtil == -1) return fallback;
            int gtset = gtsetL.get( cell );
            if (gtset < 0 || gtset >= tilesets.size()) return fallback;
            tileset gts = tilesets.get( gtset );
            if (gts == null) return fallback;
            java.util.List<tile> gtiles = gts.getTiles();
            if (gtiles == null || gtil < 0 || gtil >= gtiles.size()) return fallback;
            tile trleft = gtiles.get( gtil );
            if (trleft == null) return fallback;
            int[] terr = trleft.getTerrain();
            return (terr == null) ? fallback : terr;
        } catch (Exception e) {
            return fallback;
        }
    }

    // 自动补边落笔前检查目标格：只允许写入空白格(-1)或当前图集(curtset)的格。
    // 其它图集已有内容的格不覆盖，避免跨 tileset 自动平铺误刷破坏邻图集数据。
    private boolean canTerrainWrite(int cell) {
        try {
            if (cell < 0 || cell >= Tw * Th) return false;
            if (selLayer < 0 || selLayer >= layers.size()) return false;
            layer g = layers.get( selLayer );
            if (g == null || g.getTset() == null) return false;
            if (cell >= g.getTset().size()) return false;
            int gt = g.getTset().get( cell );
            if (gt == -1) return true;
            return (curtset >= 0 && curtset < tilesets.size() && gt == curtset);
        } catch (Exception e) { return false; }
    }

    private boolean Terrainify(int numx, tile nx, int[] directionsx, boolean fillx){
        int num = numx;
        tile n = nx;
        int[] directions = directionsx;
        boolean fill = fillx;
        // 防御：越界/异常入参直接忽略，不再向上抛导致整帧崩溃
        if (num < 0 || num >= Tw * Th) return false;
        if (selLayer < 0 || selLayer >= layers.size()) return false;
        if (layers.get( selLayer ) == null) return false;
        if (curtset < 0 || curtset >= tilesets.size()) return false;
        if (n == null) return true;
        if (directions == null || directions.length == 0) return false;

        boolean requestReterrain=true;
        int[] aa = null;
        Long from=null;
        int tzet = 0;
        layerhistory lh2=null;
        //if (n==null) return true;

        int retryGuard = 0;
        while (requestReterrain) {
            requestReterrain = false;
            // 防畸形地形数据造成无休止重试（卡死/ANR）
            if (++retryGuard > 128) break;

            if (n != null) {
                if (n.isTerrainForEditor()) {
                    aa = n.getTerrain();
                }
            }
            if (aa == null) aa = new int[]{-1, -1, -1, -1};


            for (int i : directions) { //check start here

                //gogo is for detecting index of surrounding tile
                int gogo = num;
                switch (i) {
                    case 0:
                        if (num <= Tw || num % Tw == 0) continue;
                        gogo = num - Tw - 1;
                        break;
                    case 1:
                        if (num <= Tw) continue;
                        gogo = num - Tw;
                        break;
                    case 2:
                        if (num <= Tw || num % Tw == Tw - 1) continue;
                        gogo = num - Tw + 1;
                        break;
                    case 3:
                        if (num <= 1 || num % Tw == 0) continue;
                        gogo = num - 1;
                        break;
                    case 4:
                        if (num >= Tw * Th || num % Tw == Tw - 1) continue;
                        gogo = num + 1;
                        break;
                    case 5:
                        if (num >= Tw * Th - Tw || num % Tw == 0) continue;
                        gogo = num + Tw - 1;
                        break;
                    case 6:
                        if (num >= Tw * Th - Tw) continue;
                        gogo = num + Tw;
                        break;
                    case 7:
                        if (num >= Tw * Th - Tw || num % Tw == Tw - 1) continue;
                        gogo = num + Tw + 1;
                        break;
                    case 8:
                        gogo = num;
                        break;
                }
                //why is this here?

                int[] bb = safeNeighborTerrain( gogo, new int[]{-1, -1, -1, -1} );

                //so basically aa is for the mid, bb is for surrouding

                int[] cc = null;

                if (bb != null) {
                    cc = terrainInt( i, aa, bb );
                    //log(cc[0]+","+cc[1]+","+cc[2]+","+cc[3]);
                    java.util.List<Integer> lint = new ArrayList<Integer>();
                    tile x;
                    for (int u = 0; u < tilesets.get( curtset ).getTiles().size(); u++) {
                        x = tilesets.get( curtset ).getTiles().get( u );
                        if (x.getTerrainString().equalsIgnoreCase( cc[0] + "," + cc[1] + "," + cc[2] + "," + cc[3] )) {
                            //tile found with the selected terrain
                            lint.add( u );
                        }
                    }
                    //if it is found.
                    if (lint.size() > 0) {
                        // 邻格是其它图集已有内容：不越集覆盖，跳过该方向
                        if (!canTerrainWrite( gogo )) continue;
                        int tileindex = lint.get( (int) (Math.random() * lint.size()) );
                        tile y = tilesets.get( curtset ).getTiles().get( tileindex );

                        if ((cc[0] + "," + cc[1] + "," + cc[2] + "," + cc[3]).equalsIgnoreCase( "-1,-1,-1,-1" )) {
                            updateTileData(selLayer,gogo,0,-1,-1);
                        }else{
                            updateTileData(selLayer,gogo,(long) y.getTileID() + tilesets.get( curtset ).getFirstgid(),curtset,tileindex);
                        }

                    } else {
                        //no AI for bad terrain...
                        if (bb[0] == -1 && bb[1] == -1 && bb[2] == -1 && bb[3] == -1) return true;
                        int against = bb[0];
                        if (bb[0] == aa[0]) against = bb[1];
                        if (bb[1] == aa[0]) against = bb[2];
                        if (bb[2] == aa[0]) against = bb[3];

                        findBestTile( aa[0], against );
                        if (ATPath==null) continue;
                        if (ATPath.getCount() <= 1) continue;
                        int ATid = ATPath.get( 1 ).name;

                        for (int u = 0; u < tilesets.get( curtset ).getTiles().size(); u++) {
                            if (bb[0]==ATid && bb[1]==ATid && bb[2]==ATid && bb[3]==ATid) {
                                //it means it will become an endless loop, so do not add.
                            }else{
                                tile tu = tilesets.get(curtset).getTiles().get(u);
                                if (tu.getTerrainString().equalsIgnoreCase( ATid + "," + ATid + "," + ATid + "," + ATid ))
                                lint.add(u);
                            }
                        }

                        if (lint.size() > 0) {
                            // 邻格是其它图集已有内容：不越集覆盖，跳过该方向
                            if (!canTerrainWrite( gogo )) continue;
                            int tileindex= lint.get( (int) (Math.random() * lint.size()) );
                            tile y = tilesets.get( curtset ).getTiles().get( tileindex );

                            if (y.getTerrainString().equalsIgnoreCase( "-1.-1.-1.-1" )) {
                                //optimised
                                updateTileData(selLayer,gogo,0,-1,-1);
                            }else{
                                updateTileData(selLayer,gogo,(long) y.getTileID() + tilesets.get( curtset ).getFirstgid(),curtset,tileindex);
                            }
                            if (!fill) requestReterrain = true;

                            switch (i) {
                                case 0:
                                    if (num <= Tw || num % Tw == 0) continue;
                                    gogo = num - Tw - 1;
                                    break;
                                case 1:
                                    if (num <= Tw) continue;
                                    gogo = num - Tw;
                                    break;
                                case 2:
                                    if (num <= Tw || num % Tw == Tw - 1) continue;
                                    gogo = num - Tw + 1;
                                    break;
                                case 3:
                                    if (num <= 1 || num % Tw == 0) continue;
                                    gogo = num - 1;
                                    break;
                                case 4:
                                    if (num >= Tw * Th || num % Tw == Tw - 1) continue;
                                    gogo = num + 1;
                                    break;
                                case 5:
                                    if (num >= Tw * Th - Tw || num % Tw == 0) continue;
                                    gogo = num + Tw - 1;
                                    break;
                                case 6:
                                    if (num >= Tw * Th - Tw) continue;
                                    gogo = num + Tw;
                                    break;
                                case 7:
                                    if (num >= Tw * Th - Tw || num % Tw == Tw - 1) continue;
                                    gogo = num + Tw + 1;
                                    break;
                            }
                            // 防畸形地形级联扩散：待处理队列超过上限即不再追加，避免全图风暴拖垮内存/网络
                            if (!fill && numanuma.size() < 4096) numanuma.add( new tung( gogo, y, i ) );

                        }


                    }


                }
            } //for each direction
        }//check ends here
        return false;
    }
