    // 后台网络线程回调中切回 GL 线程执行 UI 操作
    private void runOnUi(final Runnable r){
        try { if (r != null) Gdx.app.postRunnable( r ); } catch (Exception e) {}
    }

    public void logNet(final String s){
        if (!onRenderThread()) { Gdx.app.postRunnable(new Runnable(){ public void run(){ logNet( s ); } }); return; }
        try {
            String t = s;
            if (t == null) t = "";
            if (t.length() > 200) t = t.substring(0, 200);
            if (netLogBuf == null) netLogBuf = "";
            netLogBuf += t + "\n";
            int lines = 0;
            for (int i = 0; i < netLogBuf.length(); i++) {
                if (netLogBuf.charAt(i) == '\n') lines++;
            }
            while (lines > 60) {
                int idx = netLogBuf.indexOf('\n');
                if (idx < 0) break;
                netLogBuf = netLogBuf.substring(idx + 1);
                lines--;
            }
            if (lNetLog != null) {
                lNetLog.setText( netLogBuf );
                if (spLog != null) {
                    spLog.layout();
                    spLog.setScrollPercentY( 100f );
                }
            }
            status(t,5);
        }catch(Exception e){}
    }

    // 仅写入联机日志、不弹顶部状态提示：用于启动自动连接等“静默”信息，
    // 避免每次进入软件都弹出“已注册为/已连接/自动连接”等提示。
    public void logNetQuiet(final String s){
        if (!onRenderThread()) { Gdx.app.postRunnable(new Runnable(){ public void run(){ logNetQuiet( s ); } }); return; }
        try {
            String t = s;
            if (t == null) t = "";
            if (t.length() > 200) t = t.substring(0, 200);
            if (netLogBuf == null) netLogBuf = "";
            netLogBuf += t + "\n";
            int lines = 0;
            for (int i = 0; i < netLogBuf.length(); i++) {
                if (netLogBuf.charAt(i) == '\n') lines++;
            }
            while (lines > 60) {
                int idx = netLogBuf.indexOf('\n');
                if (idx < 0) break;
                netLogBuf = netLogBuf.substring(idx + 1);
                lines--;
            }
            if (lNetLog != null) {
                lNetLog.setText( netLogBuf );
                if (spLog != null) {
                    spLog.layout();
                    spLog.setScrollPercentY( 100f );
                }
            }
        }catch(Exception e){}
    }

    /** 当前服务器显示名（对外不暴露真实 IP/端口）。 */
    private String curServerName(){
        try {
            if (activeServerIndex >= 0 && activeServerIndex < serverEntries.size()) {
                ServerEntry e = serverEntries.get(activeServerIndex);
                if (e != null && e.name != null && !e.name.trim().isEmpty()) return e.name.trim();
            }
        } catch (Exception ignore) {}
        return BUILTIN_SERVER1_NAME;
    }

    // 协作状态总览：连接/房间/角色 + 按钮文案
    private void updateCollabStatus() {
        try {
            if (lcollabstatus == null) return;
            String s;
            if (!isClient) {
                s = z.status + ": " + z.readytoconnect;
                tbJoin.setText( z.join );
            } else {
                s = z.status + ": " + z.connectedto + " " + curServerName();
                tbJoin.setText( z.disconnectclient );
                if (isCreateRoom && activeRoom != null && !activeRoom.isEmpty()) {
                    s += "   " + z.rolehost + " " + activeRoom;
                } else if (isJoinRoom && activeRoom != null && !activeRoom.isEmpty()) {
                    s += "   " + z.rolemember + " " + activeRoom;
                }
                if (hostingLocal) {
                    s += "  [WiFi直连主机] " + (collabServerIp == null ? "" : collabServerIp)
                            + (activeRoom != null && !activeRoom.isEmpty() ? "  " + z.room + ": " + activeRoom : "");
                }
            }
            lcollabstatus.setText( s );
            tbCreateRoom.setText( isCreateRoom ? z.destroyroom : z.createroom );
            tbJoinRoom.setText( isJoinRoom ? z.leaveroom : z.joinroom );
        } catch (Exception e) {}
    }

    // ===== 联机快捷面板（地图编辑界面入口，非协作页） =====
    private void openLivePanel(){
        try {
            if (!isClient || !(isCreateRoom || isJoinRoom)) return;
            livePanelVisible = true;
            // 记住进入面板前的地图输入处理器，关闭时原样归还（不能只依赖 kartu 判断，BACK 等路径下界面标识可能已漂移）
            if (prevLiveInput == null) prevLiveInput = Gdx.input.getInputProcessor();
            Gdx.input.setInputProcessor( stage );
            rebuildLiveDialog();
            liveDialog.pack();
            liveDialog.setPosition( Math.max( 4, (stage.getWidth() - liveDialog.getWidth()) / 2 ),
                    Math.max( 4, (stage.getHeight() - liveDialog.getHeight()) / 2 ) );
            if (liveDialog.getStage() == null) {
                liveDialog.show( stage );   // 曾被 gotoStage 清出时重新挂载
            } else {
                liveDialog.setVisible( true );
            }
            liveDialog.toFront();
            // 让返回键/ESC 事件从面板自身开始冒泡，确保能拦截并统一走 hideLivePanel 关闭
            stage.setKeyboardFocus( liveDialog );
            // 面板真正可见后再刷新一次成员/聊天：rebuildLiveDialog() 末尾的刷新在面板尚不可见时
            //（首次刚构造 / 重开前被 setVisible(false)）会被 refreshLivePanel 的可见性判断跳过，
            // 导致成员列表时有时无。这里在可见后补齐一次，保证每次打开都能看到当前成员。
            refreshLivePanel();
        } catch (Exception e) {}
    }

    private void hideLivePanel(){
        try {
            livePanelVisible = false;
            if (liveDialog != null) liveDialog.setVisible( false );
            // 关闭后归还进入面板前的地图输入处理器（按钮/返回键/异常兑底任意路径都恢复，避免地图操作失灵）
            if (prevLiveInput != null) {
                Gdx.input.setInputProcessor( prevLiveInput );
                prevLiveInput = null;
            } else if (kartu != null && (kartu.equalsIgnoreCase( "world" ) || kartu.equalsIgnoreCase( "editor" )
                    || kartu.equalsIgnoreCase( "tile" ))) {
                Gdx.input.setInputProcessor( im );
            }
        } catch (Exception e) {}
    }

    // 重建面板全部内容（打开或名单变化时调用；成员/聊天在面板已打开时用 refresh 局部刷新）
    private void rebuildLiveDialog(){
        try {
            if (liveDialog == null) {
                liveDialog = new Dialog( z.livechat, skin, "dialog" );
                liveDialog.setModal( true );
                liveDialog.pad( 8 );
                // 拦截 Android 返回键/ESC：只关闭聊天面板并归还地图输入，不触发退出确认框，也不残留输入处理器
                liveDialog.addListener( new InputListener(){
                    public boolean keyDown(InputEvent event, int keycode){
                        if (livePanelVisible && (keycode == com.badlogic.gdx.Input.Keys.BACK
                                || keycode == com.badlogic.gdx.Input.Keys.ESCAPE)) {
                            hideLivePanel();
                            return true;
                        }
                        return false;
                    }
                } );
            }
            Table content = liveDialog.getContentTable();
            content.clearChildren();
            // 房间 + 人数
            lLiveHead = new Label( "", skin );
            lLiveHead.setWrap( true );
            content.add( lLiveHead ).width( btnx ).padBottom( 4 ).row();
            // 一键「立即同步」：地图不同步时快速重新推送 / 发起投票
            TextButton bLiveSync = new TextButton( "立即同步", skin );
            bLiveSync.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ syncNow(); }
            } );
            content.add( bLiveSync ).width( btnx ).height( btny ).padBottom( 4 ).row();
            // 常驻房投票：发起 + 表决 + 状态（仅常驻房可见，refreshVoteUi 控制）
            voteBtnRow = new Table();
            bVotePush = new TextButton( z.votepush, skin );
            bVotePush.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ startVote( "PUSH", "" ); }
            } );
            bVoteAgree = new TextButton( z.voteagree, skin );
            bVoteAgree.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ sendVoteCast( true ); }
            } );
            bVoteDisagree = new TextButton( z.votedisagree, skin );
            bVoteDisagree.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ sendVoteCast( false ); }
            } );
            voteBtnRow.add( bVotePush ).width( btnx ).height( btny ).row();
            Table vCast = new Table();
            vCast.add( bVoteAgree ).width( btnx * 0.5f - 4 ).height( btny ).padRight( 6 );
            vCast.add( bVoteDisagree ).width( btnx * 0.5f - 4 ).height( btny );
            voteBtnRow.add( vCast ).row();
            content.add( voteBtnRow ).width( btnx ).padBottom( 4 ).row();
            lVoteStatus = new Label( "", skin );
            lVoteStatus.setWrap( true );
            lVoteStatus.setFontScale( uiFontScale() );
            content.add( lVoteStatus ).width( btnx ).padBottom( 4 ).row();
            // 房间密码：房主或常驻房管理员设置/取消（refreshVoteUi 控制显隐）
            passBtnRow = new Table();
            passBtnRow.defaults().padBottom( 2 );
            Label lPassTitle = new Label( z.roompasssetting, skin );
            lPassTitle.setFontScale( uiFontScale() );
            lPassTitle.setAlignment( com.badlogic.gdx.utils.Align.left );
            passBtnRow.add( lPassTitle ).colspan( 2 ).width( btnx ).left().row();
            Label lPassHint = new Label( z.roompasshint, skin );
            lPassHint.setWrap( true );
            lPassHint.setFontScale( uiFontScale() * 0.9f );
            lPassHint.setAlignment( com.badlogic.gdx.utils.Align.left );
            passBtnRow.add( lPassHint ).colspan( 2 ).width( btnx ).left().padBottom( 3 ).row();
            tfSetPass = new TextField( "", skin );
            tfSetPass.setMessageText( z.roomcode );
            passBtnRow.add( tfSetPass ).colspan( 2 ).width( btnx ).height( btny ).row();
            bSetPass = new TextButton( z.setroompass, skin );
            bSetPass.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ sendSetRoomPass( tfSetPass.getText() ); }
            } );
            bCancelPass = new TextButton( z.cancelroompass, skin );
            bCancelPass.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ sendSetRoomPass( "" ); }
            } );
            Table passBtns = new Table();
            passBtns.add( bSetPass ).width( btnx * 0.5f - 4 ).height( btny ).padRight( 6 );
            passBtns.add( bCancelPass ).width( btnx * 0.5f - 4 ).height( btny );
            passBtnRow.add( passBtns ).colspan( 2 ).row();
            content.add( passBtnRow ).width( btnx ).padBottom( 4 ).row();
            // 成员
            Label lMemT = new Label( z.roommembers, skin );
            lMemT.setFontScale( uiFontScale() );
            content.add( lMemT ).left().padBottom( 2 ).row();
            liveMembersTable = new Table();
            liveMembersTable.top();
            ScrollPane spMem = new ScrollPane( liveMembersTable );
            spMem.setFadeScrollBars( false );
            content.add( spMem ).width( btnx ).height( btny * 2.6f ).padBottom( 4 ).row();
            // 聊天
            Label lChatT = new Label( z.chat, skin );
            lChatT.setFontScale( uiFontScale() );
            content.add( lChatT ).left().padBottom( 2 ).row();
            lLiveChatLbl = new Label( liveChatBuf.toString(), skin );
            lLiveChatLbl.setWrap( true );
            lLiveChatLbl.setFontScale( uiFontScale() );
            spLiveChat = new ScrollPane( lLiveChatLbl );
            spLiveChat.setFadeScrollBars( false );
            spLiveChat.setScrollingDisabled( true, false );   // 仅纵向滚动，避免窄屏横向拖动
            content.add( spLiveChat ).width( btnx ).height( btny * 3.2f ).padBottom( 4 ).row();
            // 输入 + 发送（回车即发送，输入框自适应宽度防窄屏溢出）
            tfLiveMsg = new TextField( "", skin );
            tfLiveMsg.addListener( new InputListener(){
                public boolean keyDown(InputEvent event, int keycode){
                    if (keycode == com.badlogic.gdx.Input.Keys.ENTER){
                        sendChat( tfLiveMsg );
                        return true;
                    }
                    return false;
                }
            } );
            TextButton bSend = new TextButton( z.sendmessage, skin );
            bSend.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ sendChat( tfLiveMsg ); }
            });
            Table inRow = new Table();
            inRow.add( tfLiveMsg ).growX().minWidth( 0 ).height( btny );
            inRow.add( bSend ).width( btnx * 0.3f ).height( btny ).padLeft( 6 );
            content.add( inRow ).width( btnx ).row();
            // 关闭
            TextButton bClose = new TextButton( z.back, skin );
            bClose.addListener( new ChangeListener(){
                public void changed(ChangeEvent event, Actor actor){ hideLivePanel(); }
            });
            content.add( bClose ).width( btnx ).height( btny ).padTop( 4 );
            refreshLivePanel();
        } catch (Exception e) {}
    }

    // 刷新面板：人数标题 + 成员行（含房主禁编/常驻房投票按钮）
    private void refreshLivePanel(){
        try {
            if (liveDialog == null || !liveDialog.isVisible()) return;
            if (lLiveHead != null) {
                String roomT = (activeRoom == null || activeRoom.isEmpty()) ? "-" : activeRoom;
                lLiveHead.setText( z.livechat + " · " + z.roomplayers + " " + liveMembers.size()
                        + (isPersistentRoom ? "  (" + z.persistentroom + ")" : "")
                        + (liveBanned ? "  (" + z.livebanned + ")" : "") + " · " + roomT );
            }
            if (liveMembersTable != null) {
                liveMembersTable.clearChildren();
                boolean host = isCreateRoom;
                if (liveMembers.isEmpty()) {
                    liveMembersTable.add( new Label( z.nomembers, skin ) ).colspan( 2 ).left().row();
                }
                for (String[] m : liveMembers) {
                    if (m == null) continue;
                    String id = m[0] == null ? "" : m[0];
                    String nick = m[1] == null ? "" : m[1];
                    boolean isHost = "host".equalsIgnoreCase( m[2] );
                    boolean isAdmin = "admin".equalsIgnoreCase( m[2] );
                    boolean banned = "1".equalsIgnoreCase( m[3] );
                    if (nick.isEmpty()) nick = id;
                    String roleTag = isHost ? ("(" + z.host + ")") : (isAdmin ? ("(" + z.adminrole + ")") : "");
                    String disp = nick + roleTag + (banned ? "(" + z.livebanned + ")" : "");
                    Label lb = new Label( disp, skin );
                    lb.setEllipsis( true );
                    liveMembersTable.add( lb ).width( btnx * 0.56f ).left();
                    boolean self = id.equalsIgnoreCase( myID );
                    if (host && !isHost && !self) {
                        // 房主房间：房主直接禁编/解除
                        final String fid = id;
                        final boolean fban = banned;
                        TextButton bT = new TextButton( banned ? z.unbanbtn : z.banbtn, skin );
                        bT.addListener( new ChangeListener(){
                            public void changed(ChangeEvent event, Actor actor){ sendMemberBan( fid, fban ); }
                        });
                        liveMembersTable.add( bT ).width( btnx * 0.44f ).height( btny ).row();
                    } else if (isPersistentRoom && !isHost && !self) {
                        // 常驻房：对成员发起禁编/解除投票（过半数通过）
                        final String fid = id;
                        final boolean fbanned = banned;
                        TextButton bT = new TextButton( banned ? z.voteunban : z.voteban, skin );
                        bT.addListener( new ChangeListener(){
                            public void changed(ChangeEvent event, Actor actor){ startVote( fbanned ? "UNBAN" : "BAN", fid ); }
                        });
                        liveMembersTable.add( bT ).width( btnx * 0.44f ).height( btny ).row();
                    } else if (isPersistentRoom && self && banned) {
                        // 常驻房：自己被禁编时，允许本人发起「解除禁编」投票（他人退出后也能自救）
                        TextButton bT = new TextButton( z.voteunban, skin );
                        bT.addListener( new ChangeListener(){
                            public void changed(ChangeEvent event, Actor actor){ startVote( "UNBAN", myID ); }
                        });
                        liveMembersTable.add( bT ).width( btnx * 0.44f ).height( btny ).row();
                    } else {
                        liveMembersTable.add( new Label( "", skin ) ).width( btnx * 0.44f ).row();
                    }
                }
            }
            if (lLiveChatLbl != null) {
                lLiveChatLbl.setText( liveChatBuf.toString() );
                scrollLiveChatToBottom();
            }
            refreshVoteUi();
        } catch (Exception e) {}
    }

    // 面板聊天缓冲追加（收/发共用；上限 120 行）
    private void appendLiveChat(String s){
        try {
            if (s == null) return;
            liveChatBuf.append( s ).append( '\n' );
            int lines = 0;
            for (int i = 0; i < liveChatBuf.length(); i++) if (liveChatBuf.charAt( i ) == '\n') lines++;
            while (lines > 120) {
                int idx = liveChatBuf.indexOf( "\n" );
                if (idx < 0) break;
                liveChatBuf.delete( 0, idx + 1 );
                lines--;
            }
            if (lLiveChatLbl != null && liveDialog != null && liveDialog.isVisible()) {
                lLiveChatLbl.setText( liveChatBuf.toString() );
                scrollLiveChatToBottom();
            }
        } catch (Exception e) {}
    }

    // 聊天区自动滚动到底部（新消息追加后调用，保证总能看清最新一条）
    private void scrollLiveChatToBottom(){
        try {
            if (spLiveChat == null) return;
            spLiveChat.layout();
            spLiveChat.setScrollPercentY( 1f );
            spLiveChat.updateVisualScroll();
        } catch (Exception ignore) {}
    }

    // 房主发送禁编/解禁命令
    private void sendMemberBan(String memberId, boolean unban){
        try {
            if (memberId == null || memberId.isEmpty()) return;
            command c = new command();
            c.command = unban ? "memberUnban" : "memberBan";
            c.room = (activeRoom == null) ? "" : activeRoom;
            c.data = memberId;
            c.from = myID;
            client.sendTCP( c );
        } catch (Exception e) {}
    }

    // 房间密码：房主（普通房）或常驻房管理员（第一个进入者）可设置；空字符串 = 取消密码恢复公开
    private void sendSetRoomPass(String pass){
        try {
            if (!isClient) return;
            boolean allowed = isCreateRoom || (isPersistentRoom && liveAdmin);
            if (!allowed) { logNet( "[C] 仅房主或房间管理员可设置密码。" ); return; }
            if (activeRoom == null || activeRoom.isEmpty()) return;
            String np = (pass == null) ? "" : pass.trim();
            command c = new command();
            c.command = "setRoomPass";
            c.from = myID;
            c.room = activeRoom;
            c.data = np;
            client.sendTCP( c );
            if (np.isEmpty()) logNet( "[C] 已请求取消房间密码，房间恢复公开。" );
            else logNet( "[C] 已请求设置房间密码。" );
        } catch (Exception e) {}
    }

    // 处理服务器下发的成员名单 roomMembers
    private void applyRoomMembers(String data){
        try {
            liveMembers.clear();
            boolean admin = false;
            if (data != null) {
                for (String ln : data.split( "\n" )) {
                    if (ln == null) continue;
                    String t = ln.trim();
                    if (t.isEmpty()) continue;
                    String[] f = t.split( "\t", -1 );
                    if (f.length < 4) continue;
                    liveMembers.add( new String[]{ f[0], f[1], f[2], f[3] } );
                    if (myID != null && !myID.isEmpty() && f[0] != null && f[0].equalsIgnoreCase( myID )
                            && f[2] != null && f[2].equalsIgnoreCase( "admin" )) admin = true;
                }
            }
            liveAdmin = admin;
            refreshLivePanel();
        } catch (Exception e) {}
    }

    // ==================== 常驻房投票（客户端） ====================
    // 收到服务器广播的投票开始
    private void onVoteStart(String from, String room, String data){
        try {
            String[] f = (data == null ? "" : data).split( command.ROOM_SEP, -1 );
            voteType = (f.length > 0 && f[0] != null) ? f[0].trim().toUpperCase() : "";
            voteTarget = (f.length > 1 && f[1] != null) ? f[1].trim() : "";
            voteThreshold = (f.length > 2) ? parseIntSafe( f[2], 1 ) : 1;
            int remainSec = (f.length > 3) ? parseIntSafe( f[3], 60 ) : 60;
            voteInitiator = (from == null) ? "" : from;
            voteYes = 1;   // 发起人默认同意
            voteNo = 0;
            voteMine = voteInitiator.equalsIgnoreCase( myID );
            voteDeadline = System.currentTimeMillis() + remainSec * 1000L;
            voteActive = true;
            String tgt = "PUSH".equals( voteType ) ? "" : ( " → " + voteTargetNick( voteTarget ) );
            logNet( "[投票] " + voteTargetNick( voteInitiator ) + " 发起 " + voteTypeName( voteType ) + tgt
                    + "，需 " + voteThreshold + " 票同意（" + remainSec + "s）。" );
            refreshVoteUi();
            refreshLivePanel();
        } catch (Exception e) {}
    }

    // 收到服务器广播的投票票数变化
    private void onVoteUpdate(String data){
        try {
            String[] f = (data == null ? "" : data).split( command.ROOM_SEP, -1 );
            if (f.length >= 3) {
                voteYes = parseIntSafe( f[0], voteYes );
                voteNo = parseIntSafe( f[1], voteNo );
                voteThreshold = parseIntSafe( f[2], voteThreshold );
            }
            refreshVoteUi();
        } catch (Exception e) {}
    }

    // 收到服务器广播的投票结束
    private void onVoteEnd(String from, String room, String data){
        try {
            String[] f = (data == null ? "" : data).split( command.ROOM_SEP, -1 );
            String type = (f.length > 0 && f[0] != null) ? f[0].trim().toUpperCase() : "";
            String target = (f.length > 1 && f[1] != null) ? f[1].trim() : "";
            String result = (f.length > 2 && f[2] != null) ? f[2].trim().toLowerCase() : "";
            boolean passed = "passed".equals( result );
            boolean mine = (from != null && from.equalsIgnoreCase( myID ));
            if ("PUSH".equals( type )) {
                if (passed && mine) {
                    logNet( "[投票] 推送更新投票通过，正在推送整图..." );
                    doPushActual();
                } else if (passed) {
                    logNet( "[投票] 推送更新投票通过，等待发起人推送。" );
                } else {
                    logNet( "[投票] 推送更新投票未通过（" + voteResultName( result ) + "）。" );
                }
            } else if (passed) {
                String nick = voteTargetNick( target );
                String msg = "BAN".equals( type ) ? (nick + " 已被投票禁编。") : (nick + " 已解除禁编。");
                logNet( "[投票] " + msg );
                msgbox( msg );
            } else {
                logNet( "[投票] " + voteTypeName( type ) + " 投票未通过（" + voteResultName( result ) + "）。" );
            }
            resetVoteState();
            refreshLivePanel();
        } catch (Exception e) {}
    }

    // 发起一次投票（仅常驻房）
    private void startVote(String type, String target){
        try {
            if (!isClient || !(isCreateRoom || isJoinRoom)) { logNet( "[C] 请先加入房间。" ); return; }
            if (!isPersistentRoom) { logNet( "[C] 仅常驻房间支持投票。" ); return; }
            if (voteActive) { logNet( "[投票] 当前已有投票进行中。" ); return; }
            if ("PUSH".equalsIgnoreCase( type ) && (curfile == null || curfile.trim().isEmpty())) {
                logNet( "[C] 请先在编辑器中打开一张地图，再发起推送投票。" );
                return;
            }
            command c = new command();
            c.command = "voteStart";
            c.from = myID;
            c.room = (activeRoom == null ? "" : activeRoom);
            c.data = type + command.ROOM_SEP + (target == null ? "" : target);
            client.sendTCP( c );
            logNet( "[投票] 已发起 " + voteTypeName( type ) + "，等待其他成员表决..." );
        } catch (Exception e) {}
    }

    // 对进行中的投票表决（agree=true 同意）
    private void sendVoteCast(boolean agree){
        try {
            if (!voteActive) return;
            command c = new command();
            c.command = "voteCast";
            c.from = myID;
            c.room = (activeRoom == null ? "" : activeRoom);
            c.data = agree ? "1" : "0";
            client.sendTCP( c );
            voteMine = true;
            refreshVoteUi();
        } catch (Exception e) {}
    }

    // 清空本地投票状态
    private void resetVoteState(){
        voteActive = false;
        voteType = "";
        voteTarget = "";
        voteInitiator = "";
        voteThreshold = 0;
        voteYes = 0;
        voteNo = 0;
        voteDeadline = 0L;
        voteMine = false;
        liveAdmin = false;
        refreshVoteUi();
    }

    // 刷新面板投票状态与按钮可见性
    private void refreshVoteUi(){
        try {
            if (voteBtnRow != null) voteBtnRow.setVisible( isPersistentRoom );
            if (passBtnRow != null) passBtnRow.setVisible( (isPersistentRoom && liveAdmin) || isCreateRoom );
            if (bVotePush != null) bVotePush.setDisabled( voteActive );
            boolean showCast = isPersistentRoom && voteActive && !voteMine;
            if (bVoteAgree != null) bVoteAgree.setVisible( showCast );
            if (bVoteDisagree != null) bVoteDisagree.setVisible( showCast );
            if (lVoteStatus != null) {
                if (!isPersistentRoom) {
                    lVoteStatus.setText( "" );
                } else if (!voteActive) {
                    lVoteStatus.setText( z.votenoinprogress );
                } else {
                    long left = Math.max( 0L, (voteDeadline - System.currentTimeMillis() + 999L) / 1000L );
                    String tgt = "PUSH".equals( voteType ) ? "" : ( " → " + voteTargetNick( voteTarget ) );
                    lVoteStatus.setText( z.votestatus + ": " + voteTypeName( voteType ) + tgt
                            + "  " + voteYes + "/" + voteThreshold + " (" + left + "s)" );
                }
            }
        } catch (Exception e) {}
    }

    // 投票类型/结果的中文名称
    private String voteTypeName(String type){
        if ("PUSH".equalsIgnoreCase( type )) return z.votepush;
        if ("BAN".equalsIgnoreCase( type )) return z.voteban;
        if ("UNBAN".equalsIgnoreCase( type )) return z.voteunban;
        return type == null ? "" : type;
    }

    private String voteResultName(String result){
        if ("timeout".equalsIgnoreCase( result )) return z.votetimeout;
        if ("failed".equalsIgnoreCase( result )) return z.votefailed;
        return result == null ? "" : result;
    }

    // 由成员ID取展示昵称（优先面板名单，其次原ID）
    private String voteTargetNick(String id){
        try {
            if (id != null && !id.isEmpty()) {
                for (String[] m : liveMembers) {
                    if (m != null && m[0] != null && m[0].equalsIgnoreCase( id )) {
                        return (m[1] != null && !m[1].isEmpty()) ? m[1] : id;
                    }
                }
            }
        } catch (Exception e) {}
        return id == null ? "" : id;
    }

    private static int parseIntSafe(String s, int def){
        try { return Integer.parseInt( s.trim() ); } catch (Exception e) { return def; }
    }

    // 房间列表选中详情 / 空提示
    private void updateRoomDetail() {
        try {
            if (roomListData == null || roomListLw == null || lRoomEmpty == null || lRoomDetail == null) return;
            boolean empty = roomListData.isEmpty();
            lRoomEmpty.setVisible( empty );
            lRoomEmpty.setText( empty ? z.norooms : "" );
            if (empty) { lRoomDetail.setText(""); return; }
            int idx = roomListLw.getSelectedIndex();
            if (idx >= 0 && idx < roomListData.size()) {
                String[] f = roomListData.get(idx);
                boolean srv = (f.length >= 7) && "1".equals(f[6]);
                String lockT = srv
                        ? (z.persistentroom + ("1".equals(f[4]) ? " · " + z.lockedroom : " · " + z.openroom))
                        : ("1".equals(f[4]) ? z.lockedroom : z.openroom);
                String ownerT = srv ? "服务器" : f[1];
                String mapN = (f[5] == null || f[5].isEmpty()) ? "-" : f[5];
                String verT = (f.length >= 8 && f[7] != null && !f[7].isEmpty()) ? f[7] : "-";
                // 只显示来源服务器名称，不暴露 IP/端口
                String srcT = (f.length >= 11 && f[8] != null && !f[8].isEmpty()) ? f[8] : "";
                lRoomDetail.setText( (srcT.isEmpty() ? "" : ("[" + srcT + "]  ")) + z.room + ": " + f[0]
                        + "  " + z.roomowner + ": " + ownerT
                        + "  " + z.roomplayers + ": " + f[2] + "/" + f[3]
                        + "  " + z.roommap + ": " + mapN
                        + "  版本: " + verT
                        + "  (" + lockT + ")" );
            } else {
                lRoomDetail.setText("");
            }
        } catch (Exception e) {}
    }

    public static String getLocalIpAddress() {
        try {
            for (Enumeration<NetworkInterface> en = NetworkInterface.getNetworkInterfaces(); en.hasMoreElements();) {
                NetworkInterface intf = en.nextElement();
                for (Enumeration<InetAddress> enumIpAddr = intf.getInetAddresses(); enumIpAddr.hasMoreElements();) {
                    InetAddress inetAddress = enumIpAddr.nextElement();
                    if (!inetAddress.isLoopbackAddress() && inetAddress instanceof Inet4Address) {
                        return inetAddress.getHostAddress();
                    }
                }
            }
        } catch (SocketException ex) {
            ex.printStackTrace();
        }
        return null;
    }


    private void broadcast(String text){
        try {
            TextChat sr = new TextChat();
            sr.text=text;
            server.sendToAllTCP(sr);

        }catch(Exception e){}
    }

    // 房间内聊天发送：仅同房成员可见（服务器按房间转发且不回显发送者，这里本地回显自己的消息）
    private void sendChat(final TextField input){
        try {
            if (input == null) return;
            String msg = input.getText();
            if (msg == null) msg = "";
            msg = msg.trim();
            if (msg.isEmpty()) return;
            input.setText("");
            if (!isClient || !(isCreateRoom || isJoinRoom)){
                logNet( "[C] 请先加入或创建房间，再发送聊天。" );
                return;
            }
            String name = (uniqueID != null && uniqueID.getText() != null && !uniqueID.getText().trim().isEmpty())
                    ? uniqueID.getText().trim() : myID;
            if (name == null || name.isEmpty()) name = "我";
            TextChat t = new TextChat();
            // 昵称放入 sender 字段，正文放 text：服务器据此识别 / 开头的命令，并保留昵称转发
            t.sender = name;
            t.text = msg;
            client.sendTCP( t );
            logNet( "[聊天] " + name + ": " + msg );   // 本地回显自己的消息
            appendLiveChat( "[聊天] " + name + ": " + msg );  // 同步到快捷面板聊天区
        } catch (Exception e) {}
    }

    private void talktoserver(String text){
        try {
            TextChat request = new TextChat();
            request.text = text;
            client.sendTCP(request);
        }catch(Exception e){}
    }

    // 整图分片 / 大包发送专用节流：等待 TCP 写缓冲落到 1KB 以下（保留原路径语义，等待窗口较长）
    private void slowdown(){
        int guard = 0;
        while (client.getTcpWriteBufferSize()>1024){
            // 最多等约 10 秒；连接断开时立即退出，避免 UI 线程死等导致 ANR/无响应
            if (++guard > 500) break;
            try { if (!client.isConnected()) break; } catch (Exception e) { break; }
            try {
                Thread.sleep( 20 ); //20
            }catch(Exception e){ break; }
        }
    }

    // 对象操作发送背压：写缓冲超过 512KB 才短暂等待（最多 500ms），
    // 避免 objOp 连发瞬间撑爆 TCP 写缓冲；正常情况立即返回，不阻塞 UI。
    private void waitTcpBreath(){
        try {
            if (client == null || !client.isConnected()) return;
            int guard = 0;
            while (client.getTcpWriteBufferSize() > 512 * 1024){
                if (++guard > 25) break;               // 最多等 500ms
                try { if (!client.isConnected()) break; } catch (Exception e) { break; }
                try { Thread.sleep( 20 ); } catch (Exception e) { break; }
            }
        } catch (Exception ignore) {}
    }

    // ==================== 平铺绘制发送端合并（降流量） ====================
    // 目标：把编辑产生的高频小包合并成少量大包，显著降低客户端出站与服务器转发流量。
    // 做法：uploaddata 不再立即发包，而是按 layer|cell 合并入待发送表（同格只保留最后一条），
    //      在每帧 render() 开头批量打包发送（一条 draw 命令把多条 layerhistory 编码进 data）。
    // 兼容：接收端同时支持旧的单条 cmd.lh 与新批量 data 编码；服务器与内嵌主机都只整体转发
    //      command，无需改动；旧客户端收到批量包时因 cmd.lh 为空而自然忽略（不崩溃）。
    private final java.util.LinkedHashMap<Long, layerhistory> pendingDraw = new java.util.LinkedHashMap<Long, layerhistory>();
    static final int DRAW_BATCH_MAX = 256;   // 单包最多合并条数（控单包体积，远低于 KryoNet 缓冲）

    private static long drawCellKey(int layer, int location) {
        return ((long) layer << 32) | (location & 0xffffffffL);
    }

    // 复制一条平铺变更的字段（入队对象随后可能被 undo/redo 就地改写，复制可避免串包）
    private static layerhistory copyLayerHistory(layerhistory s) {
        layerhistory d = new layerhistory();
        d.follower = s.follower;
        d.layer = s.layer;
        d.location = s.location;
        d.from = s.from;
        d.to = s.to;
        d.oldtset = s.oldtset;
        d.newtset = s.newtset;
        d.oldtile = s.oldtile;
        d.newtile = s.newtile;
        d.undo = s.undo;
        return d;
    }

    // 编码一批平铺变更为紧凑字符串：每条 "layer,loc,from,to,oldtset,newtset,oldtile,newtile,undo"，条间用 ';'
    private static String encodeDrawBatch(java.util.List<layerhistory> list) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            layerhistory h = list.get(i);
            if (i > 0) sb.append(';');
            sb.append(h.layer).append(',')
              .append(h.location).append(',')
              .append(h.from).append(',')
              .append(h.to).append(',')
              .append(h.oldtset).append(',')
              .append(h.newtset).append(',')
              .append(h.oldtile).append(',')
              .append(h.newtile).append(',')
              .append(h.undo ? 1 : 0);
        }
        return sb.toString();
    }

    // 解码批量编码中的一条；字段不足或格式非法时返回 null（由调用方丢弃）
    private static layerhistory decodeDrawEntry(String s) {
        String[] f = s.split(",");
        if (f.length < 9) return null;
        try {
            layerhistory h = new layerhistory();
            h.layer = Integer.parseInt(f[0].trim());
            h.location = Integer.parseInt(f[1].trim());
            h.from = Long.parseLong(f[2].trim());
            h.to = Long.parseLong(f[3].trim());
            h.oldtset = Integer.parseInt(f[4].trim());
            h.newtset = Integer.parseInt(f[5].trim());
            h.oldtile = Integer.parseInt(f[6].trim());
            h.newtile = Integer.parseInt(f[7].trim());
            h.undo = "1".equals(f[8].trim());
            return h;
        } catch (Exception e) { return null; }
    }

    // 平铺变更入队：仅同房编辑会话、未被禁编时累积，实际发送在 flushPendingDraw()（每帧）
    private void uploaddata(layerhistory lh){
        try {
            if (isClient && (isCreateRoom || isJoinRoom) && !liveBanned && lh != null) {
                synchronized (pendingDraw) {
                    pendingDraw.put( drawCellKey(lh.getLayer(), lh.getLocation()), copyLayerHistory(lh) );
                }
                markEditActivity();
            }
        }catch(Exception e){
            e.printStackTrace();
        }
    }

    // 每帧调用（GL/渲染线程）：把累积的平铺变更按批打包发送，单包不超过 DRAW_BATCH_MAX 条
    private void flushPendingDraw(){
        java.util.List<layerhistory> batch;
        synchronized (pendingDraw) {
            if (pendingDraw.isEmpty()) return;
            if (!isClient || !(isCreateRoom || isJoinRoom) || client == null || !client.isConnected()) {
                pendingDraw.clear();   // 不在房间/已断开：丢弃积压，避免无意义发送
                return;
            }
            batch = new java.util.ArrayList<layerhistory>( pendingDraw.values() );
            pendingDraw.clear();
        }
        for (int off = 0; off < batch.size(); off += DRAW_BATCH_MAX) {
            int end = Math.min(off + DRAW_BATCH_MAX, batch.size());
            java.util.List<layerhistory> chunk = batch.subList(off, end);
            command cc = new command();
            cc.command = "draw";
            cc.from = myID;
            cc.room = activeRoom;
            cc.data = encodeDrawBatch(chunk);
            waitTcpBreath();
            try { client.sendTCP(cc); } catch (Exception ignore) {}
        }
    }

    // ==================== 同格并发绘制保护 ====================
    // 记录本地刚绘制的格子(layer|loc -> 时间ms)。两人几乎同时画同一格时，若各自保留本地值会造成
    // 永久分叉（A 得 a、B 得 b）。这里在冲突窗口内用 myID 的稳定顺序决定归属，使两端收敛到同一值。
    private final java.util.Map<Long,Long> recentLocalCells = new java.util.concurrent.ConcurrentHashMap<Long,Long>();
    private volatile String applyRemoteTileFrom = null;
    static final long SAME_CELL_GUARD_MS = 400L;

    // 应用一条远端平铺变更到本地（GL 线程调用）；校验不合法数据直接丢弃。
    private void applyRemoteTile(layerhistory h){
        if (h == null) return;
        markEditActivity();
        if (Tw <= 0 || Th <= 0) return;
        int hl = h.getLayer();
        // 本地图块选框预览/待确认进行中：本操作覆盖的格子暂不接受远端改动，
        // 由本地提交或取消统一决定，避免两边相互覆盖造成图块永久丢失。
        try {
            if (tmqDirty != null && !tmqDirty.isEmpty()) {
                java.util.Map<Integer, long[]> im = tmqDirty.get( hl );
                if (im != null && im.containsKey( h.getLocation() )) return;
            }
        } catch (Exception ignore) {}
        // 同格并发保护：若该格在冲突窗口内被本地绘制过，用稳定的 myID 顺序决定归属，
        // 保证两端最终收敛（而非各自保留本地值造成永久分叉）。
        try {
            long ck = drawCellKey( hl, h.getLocation() );
            Long lts = recentLocalCells.get( ck );
            if (lts != null) {
                long age = System.currentTimeMillis() - lts;
                if (age > SAME_CELL_GUARD_MS) {
                    recentLocalCells.remove( ck );
                } else if (applyRemoteTileFrom != null && myID != null
                        && myID.compareTo( applyRemoteTileFrom ) < 0) {
                    return;   // 本端 myID 更小者优先，忽略该远端覆盖
                }
            }
        } catch (Exception ignore) {}
        if (hl < 0 || hl >= layers.size()) return;
        layer hl0 = layers.get( hl );
        if (hl0 == null || hl0.getType() != layer.Type.TILE) return;
        if (hl0.getStr() == null || hl0.getTset() == null || hl0.getTile() == null) return;
        int hloc = h.getLocation();
        if (hloc < 0 || hloc >= Tw * Th) return;
        if (hloc >= hl0.getStr().size() || hloc >= hl0.getTset().size() || hloc >= hl0.getTile().size()) return;
        if (h.undo) {
            long frm = h.from;
            long toe = h.to;
            int frmts = h.oldtset;
            int toets = h.newtset;
            int frmtl = h.oldtile;
            int toetl = h.newtile;
            h.from = toe;
            h.to = frm;
            h.oldtset = toets;
            h.newtset = frmts;
            h.undo = false;
            h.oldtile = toetl;
            h.newtile = frmtl;
        }
        undolayer.add(h);
        redolayer.clear();
        hl0.getStr().set( hloc, h.to );
        hl0.getTset().set( hloc, h.newtset );
        hl0.getTile().set( hloc, h.newtile );
        updateCache( hloc );
    }

    // ---------- 对象层实时同步 ----------

    // 把源对象的编辑器字段就地拷贝到目标对象（保留目标实例身份：
    // 选中集合 selobjs / 选框拖动基准 mqBase / 其它引用在远端更新后依然有效）
    private void objCopyEditorFields(obj dst, obj src) {
        if (dst == null || src == null) return;
        dst.setGid( src.getGid() );
        dst.setProperties( src.getProperties() );
        dst.setPoints( src.getPoints() );
        dst.setWrap( src.isWrap() );
        dst.setW( src.getW() );
        dst.setH( src.getH() );
        dst.setX( src.getX() );
        dst.setY( src.getY() );
        dst.setId( src.getId() );
        dst.setName( src.getName() );
        dst.setRotation( src.getRotation() );
        dst.setShape( src.getShape() );
        dst.setType( src.getType() );
        dst.setText( src.getText() );
    }

    // 仅复制编辑器字段的干净对象快照 -> JSON 字符串（避免 Box2D 运行时字段）
    private String objToJson(obj o) {
        try {
            if (o == null) return "";
            obj oc = new obj();
            oc.setGid( o.getGid() );
            oc.setProperties( o.getProperties() );
            oc.setPoints( o.getPoints() );
            oc.setWrap( o.isWrap() );
            oc.setW( o.getW() );
            oc.setH( o.getH() );
            oc.setX( o.getX() );
            oc.setY( o.getY() );
            oc.setId( o.getId() );
            oc.setName( o.getName() );
            oc.setRotation( o.getRotation() );
            oc.setShape( o.getShape() );
            oc.setType( o.getType() );
            oc.setText( o.getText() );
            Json json = new Json();
            return json.toJson( oc );
        } catch (Exception e) { return ""; }
    }

    // JSON -> obj（无 body，仅编辑器字段）
    private obj objFromJson(String s) {
        try {
            if (s == null || s.isEmpty()) return null;
            Json json = new Json();
            return json.fromJson( obj.class, s );
        } catch (Exception e) { return null; }
    }

    // 对象操作发送网关：op=add/update/delete；仅同房对象层会话发送
    private void sendObjOp(String op, int layerIdx, obj o) {
        try {
            if (!isClient || !(isCreateRoom || isJoinRoom)) return;
            if (liveBanned) return;   // 被房主禁编：本地不再发送对象操作（服务器同样拦截）
            if (o == null || activeRoom == null || activeRoom.isEmpty()) return;
            String js = objToJson( o );
            if (js.isEmpty()) return;
            markEditActivity();
            int lyr = -1;
            String lname = "";
            if (layers != null && layerIdx >= 0 && layerIdx < layers.size()) {
                lyr = layerIdx;
                lname = layers.get(layerIdx).getName() == null ? "" : layers.get(layerIdx).getName();
            }
            command cc = new command();
            cc.command = "objOp";
            cc.from = myID;
            cc.room = activeRoom;
            cc.objOp = op == null ? "update" : op;
            cc.layer = lyr;
            cc.objName = lname;
            cc.objJson = js;
            waitTcpBreath();   // 发送前背压：写缓冲过满时短暂等待，避免瞬时流量撑爆
            client.sendTCP( cc );
        } catch (Exception e) {}
    }

    // ==================== objOp 接收端批量排空（防高频操作卡顿/ANR） ====================

    // 监听线程入队：非本房间 / 自己回显的过滤统一放到 GL 线程 flush 时执行，这里只负责入队防重入。
    private void enqueueObjOp(command cmd) {
        try {
            if (cmd == null || cmd.room == null || cmd.from == null) return;
            boolean needSchedule = false;
            synchronized (objOpPending) {
                if (objOpPending.size() >= OBJOP_QUEUE_MAX) {
                    // 队列满时丢最旧一条 update（只丢 update，add/delete 不丢以免丢状态变更）
                    boolean droppedUpdate = false;
                    for (int i = 0; i < objOpPending.size(); i++) {
                        command c0 = objOpPending.get( i );
                        if (c0 != null && "update".equals( c0.objOp == null ? "update" : c0.objOp )) {
                            objOpPending.remove( i );
                            droppedUpdate = true;
                            break;
                        }
                    }
                    // 极端洪峰（全是 add/delete，无 update 可丢）：强制丢最旧一条，避免队列无上限增长
                    if (!droppedUpdate && !objOpPending.isEmpty()) objOpPending.remove( 0 );
                }
                objOpPending.add( cmd );
                needSchedule = true;
            }
            if (needSchedule) scheduleObjFlush();
        } catch (Exception ignore) {}
    }

    // 若尚未安排排空任务，则提交一个到 GL 线程（去抖：同帧/短时间内的多次提交合并为一次批量）
    private void scheduleObjFlush() {
        try {
            synchronized (objOpPending) {
                if (objFlushQueued) return;
                objFlushQueued = true;
            }
            runOnUi(new Runnable(){ public void run(){
                flushObjOps();
            } });
        } catch (Exception ignore) {}
    }

    // GL 线程批量排空：一次最多取 OBJOP_BATCH_MAX 条；同源同层同一对象的连续 update 只留最后一条。
    // 对象级去抖用 objJson 里的 id（libgdx Json 反射），比 objName(层名) 更精确，避免误并不同对象。
    private void flushObjOps() {
        try {
            synchronized (objOpPending) { objFlushQueued = false; }
            java.util.List<command> batch = new java.util.ArrayList<command>();
            synchronized (objOpPending) {
                int n = Math.min( OBJOP_BATCH_MAX, objOpPending.size() );
                for (int i = 0; i < n; i++) batch.add( objOpPending.get( i ) );
                for (int i = 0; i < n; i++) objOpPending.remove( 0 );
                // 一次没取完则继续安排下一批
                if (!objOpPending.isEmpty()) scheduleObjFlush();
            }
            if (batch.isEmpty()) return;

            // 房间与自身过滤：只处理当前房间、且不是自己回显的 objOp
            java.util.List<command> mine = new java.util.ArrayList<command>();
            for (command cmd : batch) {
                if (cmd == null || cmd.room == null || cmd.from == null) continue;
                if (!cmd.room.equalsIgnoreCase( activeRoom ) || cmd.from.equalsIgnoreCase( myID )) continue;
                mine.add( cmd );
            }
            if (mine.isEmpty()) return;

            // 去抖：同 from+layer+对象id 的连续 update 只保留最后一条（add/delete 全保留且按序）
            java.util.List<command> dedup = new java.util.ArrayList<command>();
            command last = null;   // 最近一个 update
            String lastKey = null;
            for (command cmd : mine) {
                if (cmd == null) continue;
                String op = cmd.objOp == null ? "update" : cmd.objOp;
                String key = objOpKey( cmd );
                if ("update".equals( op ) && key != null) {
                    if (key.equals( lastKey ) && last != null) {
                        // 同一对象的连续 update：用新值替换旧值
                        dedup.set( dedup.size() - 1, cmd );
                        last = cmd;
                    } else {
                        dedup.add( cmd );
                        last = cmd;
                        lastKey = key;
                    }
                } else {
                    dedup.add( cmd );
                    last = null;      // add/delete 打断连续 update 链
                    lastKey = null;
                }
            }
            // 应用
            for (command cmd : dedup) {
                if (cmd == null) continue;
                applyObjOp( cmd );
            }
        } catch (Exception e) {
            logNet( "[C] objOp 批量应用异常: " + e );
        }
    }

    // objOp 去抖键：from + layer + objJson 里的对象 id；id 缺失时退化为 from+layer+objJson 全文（不合并）
    private String objOpKey(command cmd) {
        try {
            if (cmd == null || cmd.objJson == null) return null;
            obj no = objFromJson( cmd.objJson );
            if (no == null) return null;
            String id = (no.getId() >= 0) ? ("#" + no.getId()) : ("x" + cmd.objJson);
            return cmd.from + "|" + cmd.layer + "|" + id;
        } catch (Exception e) { return null; }
    }

    // 接收端应用 objOp：add/update 按 id 找同层对象替换否则追加；delete 按 id 移除。
    // 仅处理 OBJECT 层；找不到目标层只提示不崩溃。必须在 GL 线程调用。
    private void applyObjOp(command cmd) {
        try {
            if (cmd == null || layers == null || layers.isEmpty()) return;
            markEditActivity();
            int lyr = cmd.layer;
            layer ly = null;
            if (lyr >= 0 && lyr < layers.size() && layers.get(lyr) != null && layers.get(lyr).getType() == layer.Type.OBJECT) {
                ly = layers.get(lyr);
            } else if (cmd.objName != null && !cmd.objName.isEmpty()) {
                for (layer l : layers) {
                    if (l != null && l.getType() == layer.Type.OBJECT && cmd.objName.equals(l.getName())) { ly = l; break; }
                }
            }
            if (ly == null) {
                logNet( "[C] objOp: 未找到目标对象层，请先整图推送对齐" );
                // 结构可能已分叉，也可能只是前置 layerOp 尚未落地：尽快触发一次自动自检确认，
                // 不直接置常驻提醒，避免大规模改动在途时的瞬时错位误报
                markEditActivity();
                lastAutoMapCheckMs = 0;
                return;
            }
            obj no = objFromJson( cmd.objJson );
            if (no == null) return;
            String op = cmd.objOp == null ? "update" : cmd.objOp;
            // 推进本地 id 分配计数：远端对象占用的 id 不应再被本地新建复用，避免并发撞 id
            if (no.getId() >= curid) curid = no.getId() + 1;
            java.util.List<obj> obs = ly.getObjects();
            if (obs == null) return;
            if ( "delete".equals( op ) ) {
                obj found = null;
                for (obj o : obs) { if (o != null && o.getId() == no.getId()) { found = o; break; } }
                if (found != null) {
                    try { if (found.getBody() != null) world.destroyBody( found.getBody() ); } catch (Exception e) {}
                    obs.remove( found );
                    // 对方删除正在被本地选中的对象：同步清除选中/拖动引用，避免悬空 body 引发崩溃
                    if (selobjs != null) selobjs.remove( found );
                    if (mqBase != null) mqBase.remove( found );
                    logNet( "[C] 对方删除了对象 #" + no.getId() );
                }
                return;
            }
            obj existing = null;
            for (obj o : obs) { if (o != null && o.getId() == no.getId()) { existing = o; break; } }
            // 接收端没有同 id 对象：通常是发送方"一键赋值"给"空白宾语"分配了新 id。
            // 此时按同层同坐标、且仍为"无类型无属性"的原始对象承接赋值，避免错误新增重复副本。
            if (existing == null && "update".equals(op) && no.getId() >= 0) {
                // 仅当候选唯一时才承接：存在多个同坐标空白对象时放弃承接，避免改错对象
                obj only = null; int cand = 0;
                for (obj o : obs) {
                    if (o == null) continue;
                    boolean blankType = (o.getType() == null) || o.getType().trim().isEmpty();
                    boolean blankProp = (o.getProperties() == null) || o.getProperties().isEmpty();
                    if (blankType && blankProp
                            && Math.abs(o.getX() - no.getX()) < 1f
                            && Math.abs(o.getY() - no.getY()) < 1f) { only = o; cand++; if (cand > 1) break; }
                }
                if (cand == 1) existing = only;
            }
            // 联机并发保护：正在被本地选框拖动/待确认的对象，暂不接受远端 update，
            // 由本地操作在提交/取消时统一发最终结果，避免两边互相覆盖导致对象丢失/跑位。
            if (existing != null && mqBase != null && !mqBase.isEmpty() && mqBase.containsKey( existing )) {
                return;
            }
            if (existing != null) {
                // 就地更新（保留实例身份）：选中集合 selobjs / 拖动基准 mqBase / 其它引用不会因远端更新而失效
                try { if (existing.getBody() != null) world.destroyBody( existing.getBody() ); } catch (Exception e) {}
                existing.setBody( null );   // 清引用，避免 updateVerticesActive 再次销毁已释放的 body 而崩溃
                objCopyEditorFields( existing, no );
                try { existing.updateVerticesActive( world, Tsh ); } catch (Exception e) {}
            } else {
                if (no.getId() >= curid) curid = no.getId() + 1; // 推进本地分配计数，避免后续新建撞 id
                obs.add( no );
                try { no.updateVerticesActive( world, Tsh ); } catch (Exception e) {}
            }
            if ( "add".equals( op ) ) logNet( "[C] 对方新增了对象 #" + no.getId() );
        } catch (Exception e) {}
    }

    // ==================== 图层结构实时同步（layerOp） ====================

    // 创建空图层（本地新建与远端 add 共用，保证两端生成结果一致）
    private layer makeBlankLayer(String typeName, String name){
        layer nl = new layer();
        nl.setName( name == null ? "" : name );
        nl.setVisible( true );
        if ("OBJECT".equalsIgnoreCase(typeName)) {
            nl.setType( layer.Type.OBJECT );
        } else if ("IMAGE".equalsIgnoreCase(typeName)) {
            nl.setType( layer.Type.IMAGE );
        } else {
            nl.setType( layer.Type.TILE );
            java.util.List<Long> s = new ArrayList<Long>();
            java.util.List<Integer> ts = new ArrayList<Integer>();
            java.util.List<Integer> tl = new ArrayList<Integer>();
            for (int i = 0; i < Tw * Th; i++) { s.add((long) 0); ts.add(-1); tl.add(-1); }
            nl.setStr(s); nl.setTset(ts); nl.setTile(tl);
        }
        return nl;
    }

    // 本地深拷贝图层（Json 往返，与复制图层原逻辑一致）。失败返回 null。
    private layer cloneLayerLocal(int idx){
        try {
            if (idx < 0 || idx >= layers.size()) return null;
            Json json = new Json();
            String clip = json.toJson( layers.get(idx) );
            return json.fromJson( layer.class, clip );
        } catch (Exception e) { return null; }
    }

    // 图层“元数据”JSON（名称/显隐/透明度/锁定/偏移/自定义属性），用于 meta 同步
    private String layerMetaJson(int idx){
        try {
            if (idx < 0 || idx >= layers.size()) return "";
            layer l = layers.get(idx);
            layer meta = new layer();
            meta.setName( l.getName() );
            meta.setVisible( l.isVisible() );
            meta.setOpacity( l.getOpacity() );
            meta.setLocked( l.isLocked() );
            meta.setOffsetX( l.getOffsetX() );
            meta.setOffsetY( l.getOffsetY() );
            meta.setProperties( l.getProperties() );
            Json json = new Json();
            return json.toJson( meta );
        } catch (Exception e) { return ""; }
    }

    private int parseIntSafe(String s){
        try { return Integer.parseInt( s == null ? "" : s.trim() ); } catch (Exception e) { return -1; }
    }

    // 刷新图层管理列表，尽量保持当前选中项（远端结构变更后可能正在浏览该界面）
    private void refreshLayerListSafe(){
        try {
            if (llayerlist == null) return;
            int keep = llayerlist.getSelectedIndex();
            String[] srr = new String[layers.size()];
            for (int i = 0; i < layers.size(); i++) srr[i] = "[" + i + "] " + layers.get(i).getName();
            llayerlist.setItems(srr);
            if (keep >= 0 && keep < layers.size()) llayerlist.setSelectedIndex(keep);
        } catch (Exception ignore) {}
    }

    // ==================== 生成类工具批量差分同步 ====================
    // 自动平铺/随机地图/图像导入等工具直接批量改写图层 str/tset/tile 或新增对象，
    // 既不走 updateTileData 也不走 sendObjOp，联机时其它成员看不到结果。
    // 这里在操作前后做快照差分，把变化经既有 draw/objOp 通道补发，实现真正同步。
    private boolean bulkSyncActive = false;
    private final java.util.List<java.util.List<Long>> bulkStrSnap = new java.util.ArrayList<java.util.List<Long>>();
    private final java.util.List<java.util.List<Integer>> bulkTsetSnap = new java.util.ArrayList<java.util.List<Integer>>();
    private final java.util.List<java.util.List<Integer>> bulkTileSnap = new java.util.ArrayList<java.util.List<Integer>>();
    // 对象层快照：key=对象实例（身份映射，避免 id 复用/重复漏判），value=编辑器字段JSON快照（用于检测"就地修改"）
    private final java.util.List<java.util.Map<obj,String>> bulkObjSnap = new java.util.ArrayList<java.util.Map<obj,String>>();

    // 操作前快照：仅在同房编辑会话且未被禁编时真正记录
    private void beginBulkSync(){
        try {
            bulkStrSnap.clear(); bulkTsetSnap.clear(); bulkTileSnap.clear(); bulkObjSnap.clear();
            bulkSyncActive = false;
            if (!isClient || (!isCreateRoom && !isJoinRoom)) return;
            if (liveBanned) return;
            if (loadingfile || pushingUpdate) return;   // 载图/推送期间不做批量同步
            if (activeRoom == null || activeRoom.isEmpty()) return;
            if (layers == null) return;
            for (int i = 0; i < layers.size(); i++) {
                layer l = layers.get(i);
                if (l == null) { bulkStrSnap.add(null); bulkTsetSnap.add(null); bulkTileSnap.add(null); bulkObjSnap.add(null); continue; }
                if (l.getType() == layer.Type.TILE && l.getStr() != null && l.getTset() != null && l.getTile() != null) {
                    bulkStrSnap.add( new java.util.ArrayList<Long>( l.getStr() ) );
                    bulkTsetSnap.add( new java.util.ArrayList<Integer>( l.getTset() ) );
                    bulkTileSnap.add( new java.util.ArrayList<Integer>( l.getTile() ) );
                    bulkObjSnap.add( null );
                } else if (l.getType() == layer.Type.OBJECT && l.getObjects() != null) {
                    // 身份映射：key=对象实例（身份映射避免 id 复用/重复漏判），value=编辑器字段JSON快照（用于检测"就地修改"）
                    java.util.Map<obj,String> snap = new java.util.IdentityHashMap<obj,String>();
                    for (int j = 0; j < l.getObjects().size(); j++) {
                        obj o = l.getObjects().get(j);
                        if (o != null) snap.put( o, objToJson( o ) );
                    }
                    bulkStrSnap.add(null); bulkTsetSnap.add(null); bulkTileSnap.add(null); bulkObjSnap.add( snap );
                } else {
                    bulkStrSnap.add(null); bulkTsetSnap.add(null); bulkTileSnap.add(null); bulkObjSnap.add(null);
                }
            }
            bulkSyncActive = true;
        } catch (Exception e) {
            bulkSyncActive = false;
            logNet("[C] beginBulkSync 失败: " + e);
        }
    }

    // 操作后差分：变化的图块经 uploaddata 入队（每帧批量发送），新增对象经 sendObjOp 补发
    private void endBulkSync(){
        if (!bulkSyncActive) return;
        bulkSyncActive = false;
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom) || liveBanned) return;
            if (activeRoom == null || activeRoom.isEmpty()) return;
            if (layers == null) return;
            int n = Math.min( layers.size(), bulkStrSnap.size() );
            int sentCells = 0, sentObjs = 0;
            for (int i = 0; i < n; i++) {
                layer l = layers.get(i);
                if (l == null) continue;
                if (l.getType() == layer.Type.TILE && bulkStrSnap.get(i) != null
                        && l.getStr() != null && l.getTset() != null && l.getTile() != null) {
                    java.util.List<Long> s0 = bulkStrSnap.get(i);
                    java.util.List<Integer> t0 = bulkTsetSnap.get(i);
                    java.util.List<Integer> p0 = bulkTileSnap.get(i);
                    int m = Math.min( l.getStr().size(), Math.min( l.getTset().size(), Math.min( l.getTile().size(), s0.size() ) ) );
                    for (int k = 0; k < m; k++) {
                        long ns = l.getStr().get(k);
                        int nt = l.getTset().get(k);
                        int np = l.getTile().get(k);
                        long os = s0.get(k);
                        int ot = (t0 != null && k < t0.size()) ? t0.get(k) : -1;
                        int op = (p0 != null && k < p0.size()) ? p0.get(k) : -1;
                        if (ns != os || nt != ot || np != op) {
                            layerhistory lh = new layerhistory( false, i, k, os, ns, ot, nt, op, np );
                            uploaddata( lh );
                            sentCells++;
                        }
                    }
                } else if (l.getType() == layer.Type.OBJECT && bulkObjSnap.get(i) != null && l.getObjects() != null) {
                    java.util.Map<obj,String> snap0 = bulkObjSnap.get(i);
                    // 当前层对象身份集：用于判定"删除"（快照里有、当前已无）
                    java.util.Set<obj> nowSet = java.util.Collections.newSetFromMap( new java.util.IdentityHashMap<obj,Boolean>() );
                    for (int j = 0; j < l.getObjects().size(); j++) { obj o = l.getObjects().get(j); if (o != null) nowSet.add( o ); }
                    // 删除：仅存在于快照的对象（如宏的 clearobjects 清空对象层）
                    for (java.util.Map.Entry<obj,String> en : snap0.entrySet()) {
                        obj so = en.getKey();
                        if (so != null && !nowSet.contains( so )) { sendObjOp( "delete", i, so ); sentObjs++; }
                    }
                    // 新增 / 就地修改（属性/坐标/名称等编辑器字段变化）
                    for (int j = 0; j < l.getObjects().size(); j++) {
                        obj o = l.getObjects().get(j);
                        if (o == null) continue;
                        if (!snap0.containsKey( o )) {
                            sendObjOp( "add", i, o );
                            sentObjs++;
                        } else {
                            String now = objToJson( o );
                            String before = snap0.get( o );
                            if (now != null && !now.isEmpty() && !now.equals( before )) {
                                sendObjOp( "update", i, o );
                                sentObjs++;
                            }
                        }
                    }
                }
            }
            if (sentCells > 0 || sentObjs > 0) {
                logNet("[C] 生成类工具已差分同步：图块 " + sentCells + " 格，对象 " + sentObjs + " 个。");
                uiLog("[C] 已同步生成结果：图块 " + sentCells + " 格，对象 " + sentObjs + " 个。");
            }
        } catch (Exception e) {
            logNet("[C] endBulkSync 失败: " + e);
        } finally {
            bulkStrSnap.clear(); bulkTsetSnap.clear(); bulkTileSnap.clear(); bulkObjSnap.clear();
        }
    }

    // ==================== 图块集(tileset)结构变更通知 ====================
    // 图块集携带贴图文件(texture/pixmap)，无法经编辑通道传输，且他端可能没有对应图片文件，
    // 因此不做数据同步，只在结构变更时即时告知其他成员，并提示需手动「推送更新」以恢复一致。
    private void sendTsetChanged(String what){
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) return;
            if (liveBanned) return;
            if (loadingfile || pushingUpdate) return;   // 载图/整图推送期间不打扰其它成员
            if (activeRoom == null || activeRoom.isEmpty()) return;
            command cc = new command();
            cc.command = "tsetChanged";
            cc.from = myID;
            cc.room = activeRoom;
            cc.data = (what == null ? "" : what);
            waitTcpBreath();
            client.sendTCP( cc );
        } catch (Exception ignore) {}
    }

    // 收到他人图块集结构变更：非阻塞提醒并自动检测（GL 线程调用）
    private void applyRemoteTsetChanged(String what){
        try {
            String tip = pushHintText();
            String detail = (what == null || what.isEmpty()) ? "" : ("（" + what + "）");
            logNet("[C] 图块集结构变更" + detail + "，可能不同步。" + tip);
            uiLog("[C] ⚠ 图块集结构已变更" + detail + "，可能不同步。" + tip);
            // 非阻塞提醒：不打断编辑，改为 HUD 提示 + 待静默后自动复检确认。
            // 不再直接发起检测（会绕过静默门槛，在对方仍在编辑时造成误判）。
            status("⚠ 有成员修改了图块集结构" + detail + "，可能导致显示不一致。" + tip, 5f);
            markEditActivity();          // 记为最近改动：重置连续确认计数，并让检测等待静默窗口
            lastAutoMapCheckMs = 0;      // 让静默窗口结束后能尽快复检
        } catch (Exception ignore) {}
    }

    // 图层结构变更发送网关：仅同房编辑会话、未被禁编时发送
    private void sendLayerOp(String op, String a, String b, String c){
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) return;
            if (liveBanned) return;
            if (activeRoom == null || activeRoom.isEmpty()) return;
            markEditActivity();
            command cc = new command();
            cc.command = "layerOp";
            cc.from = myID;
            cc.room = activeRoom;
            cc.data = command.encodeLayerOp( op, a, b, c );
            waitTcpBreath();
            client.sendTCP( cc );
        } catch (Exception ignore) {}
    }

    // 接收端应用一次图层结构变更（与本地操作执行完全相同的确定性变换；GL 线程调用）
    private void applyRemoteLayerOp(String data){
        try {
            String[] f = command.parseLayerOp( data );
            if (f == null || f.length < 2) return;
            markEditActivity();
            String op = f[0] == null ? "" : f[0].trim();
            int idx = parseIntSafe( f[1] );
            if ("add".equals(op)) {
                String type = (f.length > 2) ? f[2].trim() : "TILE";
                String name = (f.length > 3) ? f[3] : "";
                if (idx < 0 || idx > layers.size()) idx = layers.size();
                layers.add( idx, makeBlankLayer(type, name) );
            } else if ("dup".equals(op)) {
                int ins = (f.length > 2) ? parseIntSafe( f[2] ) : layers.size();
                if (idx < 0 || idx >= layers.size()) return;
                if (ins < 0 || ins > layers.size()) ins = layers.size();
                layer c = cloneLayerLocal( idx );
                if (c == null) return;
                c.setName( (c.getName() == null ? "" : c.getName()) + " (copy)" );
                layers.add( ins, c );
            } else if ("remove".equals(op)) {
                if (layers.size() <= 1) return;
                if (idx < 0 || idx >= layers.size()) return;
                layers.remove( idx );
            } else if ("move".equals(op)) {
                int to = (f.length > 2) ? parseIntSafe( f[2] ) : idx;
                if (idx < 0 || idx >= layers.size()) return;
                if (to < 0 || to >= layers.size()) return;
                if (idx == to) return;
                layer t = layers.remove( idx );
                layers.add( to, t );
            } else if ("meta".equals(op)) {
                if (idx < 0 || idx >= layers.size()) return;
                String js = (f.length > 2) ? f[2] : "";
                if (js == null || js.isEmpty()) return;
                Json json = new Json();
                layer meta = json.fromJson( layer.class, js );
                if (meta == null) return;
                layer t = layers.get( idx );
                t.setName( meta.getName() );
                t.setVisible( meta.isVisible() );
                t.setOpacity( meta.getOpacity() );
                t.setLocked( meta.isLocked() );
                t.setOffsetX( meta.getOffsetX() );
                t.setOffsetY( meta.getOffsetY() );
                t.setProperties( meta.getProperties() );
            } else {
                return;
            }
            if (selLayer >= layers.size()) selLayer = layers.size() - 1;
            if (selLayer < 0) selLayer = 0;
            updateObjectCollision();
            resetCaches();
            refreshLayerListSafe();
        } catch (Exception e) {
            logNet( "[C] 图层结构同步应用失败: " + e );
        }
    }

    // ==================== 全房地图同步检测（mapCheck/mapHash） ====================

    // FNV-1a 64 位滚动哈希小工具（无额外分配，检测一次开销很低）
    private static long fnvUpd(long h, long v){ return (h ^ v) * 0x100000001b3L; }
    private static long fnvStr(long h, String s){
        // null 与 "" 视为等价：地图保存/加载往返会把缺失的名称/类型由 "" 变成 null（或反之），
        // 若区分二者，会导致“一进房就判不同步”的误报。
        if (s == null) s = "";
        for (int i = 0; i < s.length(); i++) h = fnvUpd(h, s.charAt(i));
        return fnvUpd(h, 0xffffL);
    }
    private static long qz(float v){ return (long) Math.round(v * 1000f); }   // 浮点量化到 0.001，避免细微误差误判
    private static long fnvProps(long h, java.util.List<property> ps){
        int pc = (ps == null) ? 0 : ps.size();
        h = fnvUpd(h, pc);
        if (ps == null || pc == 0) return h;
        // 属性表顺序无关：按 (name,type,value) 排序后再哈希，避免两端属性排列不同造成的误判
        java.util.List<property> sorted = new java.util.ArrayList<property>( ps );
        java.util.Collections.sort(sorted, new java.util.Comparator<property>(){
            public int compare(property a, property b){
                String an = (a == null || a.getName() == null) ? "" : a.getName();
                String bn = (b == null || b.getName() == null) ? "" : b.getName();
                int c = an.compareTo(bn);
                if (c != 0) return c;
                String at = (a == null || a.getType() == null) ? "" : a.getType();
                String bt = (b == null || b.getType() == null) ? "" : b.getType();
                c = at.compareTo(bt);
                if (c != 0) return c;
                String av = (a == null || a.getValue() == null) ? "" : a.getValue();
                String bv = (b == null || b.getValue() == null) ? "" : b.getValue();
                return av.compareTo(bv);
            }
        });
        for (property p : sorted) {
            if (p == null) { h = fnvUpd(h, 0x13L); continue; }
            h = fnvStr(h, p.getName()); h = fnvStr(h, p.getType()); h = fnvStr(h, p.getValue());
        }
        return h;
    }

    // 计算当前地图内容指纹（尺寸/朝向/图集(轻量)/各图层结构+内容/对象/属性）。两端一致则指纹一致。
    // 返回“总指纹#分项指纹”的明细串：总指纹用于是否同步的判定；分项用于定位“到底哪里不一致”。
    // 格式：<总16hex>#H<hdr16hex>,T<tsets16hex>,L<i>m<meta16hex>c<content16hex>...
    private String computeMapSignatureDetail(){
        // ---- 头部：尺寸/朝向/渲染顺序 ----
        long hh = 0xcbf29ce484222325L;
        hh = fnvUpd(hh, Tw); hh = fnvUpd(hh, Th); hh = fnvUpd(hh, Tsw); hh = fnvUpd(hh, Tsh);
        hh = fnvStr(hh, orientation); hh = fnvStr(hh, renderorder);
        // ---- 图集（轻量：只取影响 gid 解析与渲染的元数据） ----
        long th = 0xcbf29ce484222325L;
        int tsc = (tilesets == null) ? 0 : tilesets.size();
        th = fnvUpd(th, tsc);
        if (tilesets != null) for (tileset ts : tilesets) {
            if (ts == null) { th = fnvUpd(th, 0x7L); continue; }
            th = fnvUpd(th, ts.getFirstgid());
            th = fnvStr(th, ts.getName());
            th = fnvStr(th, ts.getSource());
            th = fnvUpd(th, ts.getTilecount());
            th = fnvUpd(th, ts.getTilewidth()); th = fnvUpd(th, ts.getTileheight());
            th = fnvUpd(th, ts.getMargin()); th = fnvUpd(th, ts.getSpacing());
            th = fnvUpd(th, ts.getColumns());
        }
        // ---- 逐图层：元数据(meta) 与 内容(content) 分开算，便于定位 ----
        int lc = (layers == null) ? 0 : layers.size();
        long[] lmeta = new long[lc];
        long[] lcont = new long[lc];
        for (int li = 0; li < lc; li++) {
            layer l = (layers == null) ? null : layers.get(li);
            long m = 0xcbf29ce484222325L;
            long c = 0xcbf29ce484222325L;
            if (l == null) { m = fnvUpd(m, 0x9L); }
            else {
                m = fnvUpd(m, (l.getType() == null) ? -1L : (long) l.getType().ordinal());
                m = fnvStr(m, l.getName());
                m = fnvUpd(m, l.isVisible() ? 1L : 0L);
                m = fnvUpd(m, qz(l.getOpacity()));
                m = fnvUpd(m, qz(l.getOffsetX())); m = fnvUpd(m, qz(l.getOffsetY()));
                m = fnvProps(m, l.getProperties());
                if (l.getType() == layer.Type.TILE) {
                    java.util.List<Long> ss = l.getStr();
                    java.util.List<Integer> tt = l.getTset();
                    java.util.List<Integer> tl = l.getTile();
                    c = fnvUpd(c, (ss == null) ? 0 : ss.size());
                    if (ss != null) for (Long v : ss) c = fnvUpd(c, (v == null) ? 0L : v);
                    c = fnvUpd(c, (tt == null) ? 0 : tt.size());
                    if (tt != null) for (Integer v : tt) c = fnvUpd(c, (v == null) ? 0L : v);
                    c = fnvUpd(c, (tl == null) ? 0 : tl.size());
                    if (tl != null) for (Integer v : tl) c = fnvUpd(c, (v == null) ? 0L : v);
                } else if (l.getType() == layer.Type.OBJECT) {
                    java.util.List<obj> os = l.getObjects();
                    c = fnvUpd(c, (os == null) ? 0 : os.size());
                    if (os != null) for (obj o : os) {
                        if (o == null) { c = fnvUpd(c, 0x11L); continue; }
                        c = fnvUpd(c, o.getId());
                        c = fnvUpd(c, o.getGid());                       // 瓦片对象 gid：缺失会导致仅此项不同却判为已同步
                        c = fnvUpd(c, (o.isWrap() ? 1L : 0L));           // wrap 标记
                        c = fnvUpd(c, qz(o.getX())); c = fnvUpd(c, qz(o.getY()));
                        // 点对象不持久化宽高：加载端会补成 Tsw×Tsh，两端统一按 0 计，避免往返后误判
                        String oshape = (o.getShape() == null) ? "" : o.getShape().trim();
                        boolean isPt = oshape.equalsIgnoreCase("point");
                        c = fnvUpd(c, isPt ? 0L : qz(o.getW()));
                        c = fnvUpd(c, isPt ? 0L : qz(o.getH()));
                        c = fnvUpd(c, qz(o.getRotation()));
                        c = fnvStr(c, o.getName()); c = fnvStr(c, o.getType());
                        c = fnvStr(c, oshape); c = fnvStr(c, o.getText());
                        java.util.List<com.badlogic.gdx.math.Vector2> pts = o.getPoints();
                        c = fnvUpd(c, (pts == null) ? 0 : pts.size());
                        if (pts != null) for (com.badlogic.gdx.math.Vector2 p2 : pts) {
                            if (p2 != null) { c = fnvUpd(c, qz(p2.x)); c = fnvUpd(c, qz(p2.y)); }
                        }
                        c = fnvProps(c, o.getProperties());
                    }
                } else if (l.getType() == layer.Type.IMAGE) {
                    c = fnvStr(c, l.getImage());
                    c = fnvUpd(c, l.getImagewidth()); c = fnvUpd(c, l.getImageheight());
                }
            }
            lmeta[li] = m; lcont[li] = c;
        }
        // ---- 总指纹：与分项同源，保证“总指纹不同 ⇔ 至少一个分项不同” ----
        long h = 0xcbf29ce484222325L;
        h = fnvUpd(h, hh); h = fnvUpd(h, th); h = fnvUpd(h, lc);
        for (int li = 0; li < lc; li++) { h = fnvUpd(h, lmeta[li]); h = fnvUpd(h, lcont[li]); }
        StringBuilder sb = new StringBuilder(64 + lc * 40);
        sb.append(java.lang.String.format("%016x", h)).append('#');
        sb.append('H').append(java.lang.String.format("%016x", hh));
        sb.append(",T").append(java.lang.String.format("%016x", th));
        for (int li = 0; li < lc; li++) {
            sb.append(",L").append(li).append('m').append(java.lang.String.format("%016x", lmeta[li]))
              .append('c').append(java.lang.String.format("%016x", lcont[li]));
        }
        return sb.toString();
    }

    // 仅取总指纹（兼容旧调用）
    private String computeMapSignature(){
        String d = computeMapSignatureDetail();
        int i = d.indexOf('#');
        return (i > 0) ? d.substring(0, i) : d;
    }

    // 比较两份“指纹明细串”，返回人类可读的差异项（如“地图头/图集元数据/图层#3 元数据/图层#3 内容”）
    private String diffMapSignatureDetail(String selfDetail, String otherDetail){
        try {
            if (selfDetail == null || otherDetail == null) return "";
            int si = selfDetail.indexOf('#'); int oi = otherDetail.indexOf('#');
            if (si <= 0 || oi <= 0) return "对方为旧版本(无分项)";
            String[] a = selfDetail.substring(si + 1).split(",");
            String[] b = otherDetail.substring(oi + 1).split(",");
            StringBuilder sb = new StringBuilder();
            int n = Math.max(a.length, b.length);
            for (int i = 0; i < n; i++) {
                String x = (i < a.length) ? a[i] : "";
                String y = (i < b.length) ? b[i] : "";
                if (x.equals(y)) continue;
                String label;
                if (x.startsWith("H") || y.startsWith("H")) label = "地图头(尺寸/朝向)";
                else if (x.startsWith("T") || y.startsWith("T")) label = "图集元数据";
                else if (x.startsWith("L") && y.startsWith("L")) {
                    int xm = x.indexOf('m'), xc = x.indexOf('c');
                    int ym = y.indexOf('m'), yc = y.indexOf('c');
                    String xi = (xm > 1) ? x.substring(1, xm) : "?";
                    String xmeta = (xm >= 0 && xc > xm) ? x.substring(xm + 1, xc) : "";
                    String xcont = (xc >= 0) ? x.substring(xc + 1) : "";
                    String ymeta = (ym >= 0 && yc > ym) ? y.substring(ym + 1, yc) : "";
                    String ycont = (yc >= 0) ? y.substring(yc + 1) : "";
                    boolean md = !xmeta.equals(ymeta);
                    boolean cd = !xcont.equals(ycont);
                    if (md && cd) label = "图层#" + xi + " 元数据+内容";
                    else if (md) label = "图层#" + xi + " 元数据(名称/显隐/透明度/偏移/属性)";
                    else label = "图层#" + xi + " 内容(瓦片/对象)";
                } else label = "分项#" + i;
                if (sb.length() > 0) sb.append('、');
                sb.append(label);
                if (sb.length() > 160) { sb.append("…"); break; }
            }
            return sb.toString();
        } catch (Exception e) { return ""; }
    }

    // 发起一次全房地图同步检测（manual=true 为手动按钮触发，结果总是弹窗；false 为自动自检，仅在不一致时提示）
    private void requestMapSyncCheck(boolean manual){
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) {
                if (manual) msgbox("请先加入或创建房间，再进行同步检测。");
                return;
            }
            if (mapCheckActive) { if (manual) logNet("[C] 同步检测进行中，请稍候..."); return; }
            mapCheckActive = true;
            mapCheckManual = manual;
            // 记录发起时是否静默：只有起止都静默的检测轮才作为“不同步”证据（手动检测不受此限制）
            mapCheckQuietStart = !isEditInFlight() && (System.currentTimeMillis() - lastEditActivityMs >= AUTO_MAP_CHECK_SETTLE_MS);
            mapCheckDeadline = System.currentTimeMillis() + 4000L;
            synchronized (mapCheckResults) { mapCheckResults.clear(); }
            mapCheckSelfHash = computeMapSignatureDetail();
            command cc = new command();
            cc.command = "mapCheck";
            cc.from = myID;
            cc.room = activeRoom;
            cc.data = mapCheckSelfHash;   // 附带本端指纹，便于对方也快速比对
            client.sendTCP( cc );
            if (manual) { logNet("[C] 正在检测全房地图同步状态..."); uiLog("[C] 正在检测全房地图同步状态..."); }
        } catch (Exception e) {
            mapCheckActive = false;
            if (manual) logNet("[C] 同步检测发起失败: " + e);
        }
    }

    // 收到他人 mapCheck：回报本端指纹（GL 线程计算）
    private void replyMapHash(){
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) return;
            final String h = computeMapSignatureDetail();
            command r = new command();
            r.command = "mapHash";
            r.from = myID;
            r.room = activeRoom;
            r.data = h;
            client.sendTCP( r );
        } catch (Exception ignore) {}
    }

    // 本轮检测收口：比对全房指纹，判定是否同步
    private void finishMapSyncCheck(){
        mapCheckActive = false;
        // 收口时重新计算本端指纹，纳入检测窗口内刚落地的远端操作，降低瞬时误报
        try { mapCheckSelfHash = computeMapSignatureDetail(); } catch (Exception ignore) {}
        // 本轮是否为“可信（静默）轮”：发起时静默 + 收口时仍静默。非可信轮只作参考，不作为“不同步”证据。
        boolean conclusive = mapCheckQuietStart
                && !isEditInFlight()
                && (System.currentTimeMillis() - lastEditActivityMs >= AUTO_MAP_CHECK_SETTLE_MS);
        int compared = 0, mismatch = 0;
        java.util.List<String> diffMembers = new java.util.ArrayList<String>();
        synchronized (mapCheckResults) {
            for (java.util.Map.Entry<String,String> e : mapCheckResults.entrySet()) {
                if (e.getValue() == null || e.getValue().isEmpty()) continue;
                compared++;
                if (!e.getValue().equals(mapCheckSelfHash)) { mismatch++; diffMembers.add(e.getKey()); }
            }
        }
        // 诊断：逐成员给出“哪一部分不一致”（地图头/图集/某图层 元数据或内容），只写日志不弹状态，便于两端日志对照定位真因
        if (mismatch > 0) {
            synchronized (mapCheckResults) {
                for (java.util.Map.Entry<String,String> e : mapCheckResults.entrySet()) {
                    if (e.getValue() == null || e.getValue().isEmpty()) continue;
                    if (e.getValue().equals(mapCheckSelfHash)) continue;
                    String d = diffMapSignatureDetail(mapCheckSelfHash, e.getValue());
                    logNetQuiet("[C] 同步检测明细：" + e.getKey() + " 与本地差异 -> " + (d.isEmpty() ? "未知" : d));
                }
            }
        }
        boolean manual = mapCheckManual;
        if (compared == 0) {
            // 无对端可比（单人房/对端未响应）：自动自检时清掉可能残留的提醒，避免单人时提示不消失
            desyncStrikes = 0;
            if (!manual) setSyncReminder(false, 0);
            logNet("[C] 同步检测：未收到其他成员的地图指纹，无法比对（对方可能为旧版本或未响应）。");
            if (manual) msgbox("未收到其他成员的地图指纹，无法比对。\n（对方可能是旧版本或网络未响应）");
            return;
        }
        if (mismatch == 0) {
            desyncStrikes = 0;
            setSyncReminder(false, 0);
            logNet("[C] 同步检测：地图已同步（已比对 " + compared + " 名成员）。");
            if (manual) { uiLog("[C] 地图同步正常，已比对 " + compared + " 名成员。"); msgbox("地图同步正常：已与 " + compared + " 名成员一致。"); }
            return;
        }
        // 检测到差异：整理提示文案
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < diffMembers.size() && i < 6; i++) { if (i > 0) sb.append("、"); sb.append(diffMembers.get(i)); }
        String who = sb.toString();
        String tip = pushHintText();
        if (manual) {
            // 手动检测：立即置提醒并弹一次结果
            desyncStrikes = 0;
            logNet("[C] 同步检测：检测到 " + mismatch + " 名成员地图不一致（" + who + "）。" + tip);
            uiLog("[C] ⚠ 地图不同步：" + who + "。" + tip);
            setSyncReminder(true, mismatch);
            String mdetail = "";
            synchronized (mapCheckResults) {
                for (java.util.Map.Entry<String,String> e : mapCheckResults.entrySet()) {
                    if (e.getValue() == null || e.getValue().isEmpty()) continue;
                    if (e.getValue().equals(mapCheckSelfHash)) continue;
                    mdetail = diffMapSignatureDetail(mapCheckSelfHash, e.getValue());
                    break;
                }
            }
            msgbox("检测到地图不同步！\n与 " + mismatch + " 名成员的地图不一致：\n" + who
                    + (mdetail.isEmpty() ? "" : "\n\n差异定位：" + mdetail) + "\n\n" + tip);
            return;
        }
        // 自动自检：非静默轮（起止期间仍有编辑/改动在途）视为不可信，直接丢弃、不计入连续确认。
        // 这样大量移动/绘画期间的瞬时指纹差异不会再累积成“不同步”提醒。
        if (!conclusive) {
            logNet("[C] 同步检测：本轮回检测窗口内仍有编辑在途，结果不可信，已忽略（待静默后复检）。");
            return;
        }
        logNet("[C] 同步检测：检测到 " + mismatch + " 名成员地图不一致（" + who + "）。" + tip);
        uiLog("[C] ⚠ 地图不同步：" + who + "。" + tip);
        desyncStrikes++;
        if (desyncStrikes >= DESYNC_CONFIRM_ROUNDS) {
            setSyncReminder(true, mismatch);
        } else {
            logNet("[C] 同步检测：疑似不一致（第 " + desyncStrikes + "/" + DESYNC_CONFIRM_ROUNDS + " 轮），静默复检确认中...");
        }
    }

    // 依据当前房间类型给出“如何重新同步”的提示
    private String pushHintText(){
        if (isPersistentRoom) return "请点「立即同步」发起「推送更新」投票，通过后会自动重新同步整图。";
        if (isCreateRoom) return "请点「立即同步」（或协作页「推送更新」）重新同步整图。";
        return "请房主点「立即同步」重新同步整图（成员无法发起整图推送）。";
    }

    // 标记最近有地图改动（本地发送或远端应用）。自动自检前需等待一段静默期，
    // 避免大规模改动仍在网络/批量队列中传输时的瞬时指纹差异被误判为“不同步”。
    // 同时清零连续确认计数：任何编辑都会使上一轮的“连续确认”失效，防止移动/绘画期间的瞬时差异累积成误报。
    private void markEditActivity(){
        lastEditActivityMs = System.currentTimeMillis();
        desyncStrikes = 0;
    }

    // 是否仍有编辑尚未落地（待发平铺队列、待应用/待排空对象队列）。自动自检的静默门槛与“可信轮”判定都依赖它。
    private boolean isEditInFlight(){
        try {
            boolean a;
            synchronized (pendingDraw) { a = !pendingDraw.isEmpty(); }
            boolean b;
            synchronized (objOpPending) { b = !objOpPending.isEmpty() || objFlushQueued; }
            return a || b;
        } catch (Exception ignore) {}
        return false;
    }

    // 设置/清除「地图不同步」提醒状态
    private void setSyncReminder(boolean active, int diffMembers){
        try {
            if (active) {
                syncReminderActive = true;
                syncReminderDiffMembers = diffMembers;
                lastSyncReminderMs = 0;   // 立即刷新一次
            } else {
                clearSyncReminder();
            }
        } catch (Exception ignore) {}
    }

    private void clearSyncReminder(){
        syncReminderActive = false;
        syncReminderDiffMembers = 0;
        lastSyncReminderMs = 0;
        desyncStrikes = 0;   // 提醒清除时一并复位连续确认计数
        synchronized (mapCheckResults) { mapCheckResults.clear(); }   // 切房/退出时清空上轮成员指纹，避免残留污染
    }

    // 不同步时按节流刷新 HUD 常驻提醒（非阻塞；恢复同步后自动消失）。刷新间隔放宽，减少反复弹提示的打扰。
    private void refreshSyncReminder(){
        try {
            if (!syncReminderActive) return;
            if (!isClient || (!isCreateRoom && !isJoinRoom)) { clearSyncReminder(); return; }
            long now = System.currentTimeMillis();
            if (now - lastSyncReminderMs < 2500L) return;
            lastSyncReminderMs = now;
            String roleHint;
            if (isCreateRoom) roleHint = "请点「立即同步」重新推送整图。";
            else if (isPersistentRoom) roleHint = "请点「立即同步」发起推送投票。";
            else roleHint = "请让房主点「立即同步」重新推送整图。";
            status("⚠ 地图不同步（与 " + syncReminderDiffMembers + " 名成员）: " + roleHint, 3f);
        } catch (Exception ignore) {}
    }

    // 「立即同步」一键入口：按角色执行（房主直接推送 / 常驻房发起投票 / 普通成员提示房主）
    private void syncNow(){
        try {
            if (!isClient || (!isCreateRoom && !isJoinRoom)) { msgbox("请先加入或创建房间，再进行同步。"); return; }
            if (isCreateRoom) {
                pushUpdate();               // 房主：直接整图推送
            } else if (isPersistentRoom) {
                startVote("PUSH", "");      // 常驻房：发起推送投票
            } else {
                msgbox(pushHintText());     // 普通成员：无法推送，提示房主
            }
        } catch (Exception e) { logNet("[C] 立即同步失败: " + e); }
    }

    // 服务器把收到的平铺数据转发给除发送者外的其它连接：不回显发送者，避免自身收包风暴
    private void pushdata(packet lh, Connection skipConn){
        try {
            if (server == null) return;
            for (Connection c : server.getConnections()) {
                if (c == null || c == skipConn) continue;
                try { c.sendTCP(lh); } catch (Exception ignore) {}
            }
        }catch(Exception e){
            e.printStackTrace();
        }
    }

    private void stopServer() {
        try {
            stopServerGuard();   // 结束僵尸清理守护线程
            server.stop();
            isServer = false;
            tbHost.setText(z.host);
            activeClients.clear();
            logNet("本机服务器已停止");
         }catch(Exception e){}
    }

        private void stopClient() {
            try {
                if (isCreateRoom) {
                    destroyRoom();
                }
                if (isJoinRoom) {
                    leaveRoom();
                }

                command cc = new command();
                cc.command="disconnect";
                cc.from=myID;
                try { client.sendTCP( cc ); } catch (Exception ignore) {}
                // 尽量把已排队的 leave/destroy/disconnect 包刷出后再关闭：交给短命守护线程延迟关闭，
                // 避免优雅离房流程丢包（服务器端 disconnected 回调亦会兜底清理）
                final Client oldClient = client;
                try {
                    Thread ct = new Thread(new Runnable(){ public void run(){
                        try { Thread.sleep(150L); } catch (Exception ignore) {}
                        try { oldClient.close(); } catch (Exception ignore) {}
                        try { oldClient.stop(); } catch (Exception ignore) {}
                    }});
                    ct.setDaemon(true);
                    ct.setName("CollabDisconnect");
                    ct.start();
                } catch (Exception e0) {
                    try { oldClient.close(); } catch (Exception ignore) {}
                    try { oldClient.stop(); } catch (Exception ignore) {}
                }

                isClient = false;
                isCreateRoom = false;
                isJoinRoom = false;
                isPersistentRoom = false;
                activeRoom = "";
                resetVoteState();
                clearSyncReminder();
                collabServerIp = "";
                updateCollabStatus();
                logNet("已断开与服务器的连接" );
                // 清理联机快捷面板状态
                liveBanned = false;
                liveMembers.clear();
                livePanelVisible = false;
                if (liveDialog != null) liveDialog.setVisible( false );



            } catch (Exception e) {
            }
        }


