    // 创建房间设置弹窗：集中配置「房间名称 / 房间密码(设置码) / 人数上限」，确认后建房。
    // 各字段默认取当前协作页上的值，确认时回写并调用 createRoom()，保持既有建房链路不变。
    private void showCreateRoomDialog() {
        if (!onRenderThread()) { Gdx.app.postRunnable(new Runnable(){ public void run(){ showCreateRoomDialog(); } }); return; }
        if (!isClient) { logNet("未连接到服务器，请先点击连接。"); return; }
        if (isJoinRoom) { logNet("不能创建房间：请先离开当前房间。"); return; }
        try {
            final com.badlogic.gdx.InputProcessor prevInput = Gdx.input.getInputProcessor();
            final TextField fName = new TextField(roomName == null ? "" : roomName.getText(), skin);
            final TextField fPass = new TextField(tfPassword == null ? "" : tfPassword.getText(), skin);
            fPass.setPasswordMode(true);
            fPass.setPasswordCharacter('*');
            final TextField fMax = new TextField(
                    (tfMaxPlayers == null || tfMaxPlayers.getText().trim().isEmpty()) ? "6" : tfMaxPlayers.getText().trim(), skin);
            fMax.setTextFieldFilter(new TextField.TextFieldFilter.DigitsOnlyFilter());

            Dialog d = new Dialog(z.createroomtitle, skin, "dialog") {
                @Override
                public void result(Object obj) {
                    try {
                        if (Boolean.TRUE.equals(obj)) {
                            String nm = fName.getText() == null ? "" : fName.getText().trim();
                            if (nm.isEmpty()) {
                                logNet("请输入房间名称。");
                            } else {
                                // 回写到协作页字段，供 createRoom() 读取（也便于加入房间时复用）
                                if (roomName != null) roomName.setText(nm);
                                if (tfPassword != null) tfPassword.setText(fPass.getText() == null ? "" : fPass.getText());
                                if (tfMaxPlayers != null) tfMaxPlayers.setText(fMax.getText() == null ? "" : fMax.getText().trim());
                                createRoom();
                            }
                        }
                    } catch (Exception ignore) {}
                    if (prevInput != null) Gdx.input.setInputProcessor(prevInput);
                }
            };
            Table c = d.getContentTable();
            float cw = stage.getWidth() * 0.5f;
            if (cw <= 0f) cw = 260f;
            float tipW = cw + 70f;

            c.add(new Label(z.room, skin)).left().padRight(6).padBottom(4);
            c.add(fName).width(cw).padBottom(4).row();

            c.add(new Label(z.roomcode, skin)).left().padRight(6).padBottom(4);
            c.add(fPass).width(cw).padBottom(4).row();

            Label tipPass = new Label(z.codetip, skin);
            tipPass.setWrap(true);
            tipPass.setFontScale(uiFontScale() * 0.9f);
            c.add(tipPass).colspan(2).width(tipW).left().padBottom(8).row();

            c.add(new Label(z.maxplayers, skin)).left().padRight(6).padBottom(4);
            c.add(fMax).width(cw).padBottom(4).row();

            Label tipMax = new Label(z.maxtip, skin);
            tipMax.setWrap(true);
            tipMax.setFontScale(uiFontScale() * 0.9f);
            c.add(tipMax).colspan(2).width(tipW).left().padBottom(4).row();

            d.button(z.createroom, true);
            d.button(z.cancel, false);
            d.setModal(true);
            d.show(stage);
            Gdx.input.setInputProcessor(stage);
        } catch (Exception ignore) {}
    }

    private void createRoom() {
        try {
            //server.stop();
            if (!isClient){
                logNet("未连接到服务器，请先点击连接。" );
                return;
            }
            if (isJoinRoom){
                logNet("不能创建房间：请先离开当前房间。");
                return;
            }
            String rn = roomName.getText();
            if (rn == null) rn = "";
            rn = rn.trim();
            if (rn.isEmpty()){
                logNet("请输入房间名称。");
                return;
            }
            command c = new command();
            c.from = myID;
            c.room = rn;
            c.command = "createRoom";
            String maxTxt = (tfMaxPlayers==null ? "" : tfMaxPlayers.getText());
            c.data = command.encodeRoomData( (tfPassword==null ? "" : tfPassword.getText()), maxTxt );
            client.sendTCP(c);

        }catch(Exception e){}
    }

    private void joinRoom() {
        try {
            //client.stop();

            if (!isClient){
                logNet("Not connected to server");
                return;
            }

            if (isCreateRoom){
                logNet("不能加入房间：请先解散/离开当前房间。");
                return;
            }

            String rn = roomName.getText();
            if (rn == null) rn = "";
            rn = rn.trim();
            if (rn.isEmpty()){
                logNet("请输入房间名称。");
                return;
            }

            logNet("正在请求加入: " + rn);
            command c = new command();
            c.from = myID;
            c.command = "joinRequest";
            c.room = rn;
            c.data = (tfPassword==null ? "" : tfPassword.getText());
            client.sendTCP(c);

        } catch (Exception e) {
        }
    }

    private void registerID(){
        command c = new command();
        c.command = "registerID";
        String nick = (uniqueID == null || uniqueID.getText() == null) ? "" : uniqueID.getText().trim();
        if (nick.isEmpty()) nick = "Tunit";
        // 复用已有随机后缀，尽量保持 myID 稳定（改名时只变昵称前缀，避免连带房间/记账状态漂移）
        String suffix = null;
        try {
            if (myID != null && !myID.isEmpty()) {
                int u = myID.lastIndexOf('_');
                if (u > 0 && u < myID.length() - 1) {
                    String tail = myID.substring(u + 1);
                    if (tail.matches("\\d{1,10}")) suffix = tail;
                }
            }
        } catch (Exception ignore) {}
        if (suffix == null) suffix = Integer.toString((int) (Math.random() * 10000000));
        c.data = nick + "_" + suffix;
        myID=c.data;
        client.sendTCP(c);
        // 上报客户端版本号（versionCode|versionName）：房间列表展示 + 同版本才能进房
        try {
            int vc = face.getVersionCode();
            String vn = (vers == null) ? "" : vers;
            command cv = new command();
            cv.command = "clientVersion";
            cv.from = myID;
            cv.data = vc + "|" + vn;
            client.sendTCP(cv);
        } catch (Exception ignore) {}
    }

