    private void runServer(int port){
        try {
            if (port <=0){
                logNet("请输入正确的端口号。");
                return;
            }
            server.start();
            server.bind(port);            // 纯 TCP：若绑定 UDP 端口，纯 TCP 客户端会注册失败（连上即断）
            startServerGuard();   // 启动僵尸连接清理 / 限速守护线程
            if (mygame !=null){
                //mygame.server = server;
            }


            logNet("本机服务器已在端口 " + Integer.toString( port ) + " 启动");
            logNet(z.listeningon+" "+getLocalIpAddress());
            isServer = true;
            tbHost.setText(z.stopserver);
            localIP = getLocalIpAddress();
            tfRemoteIP.setText(getLocalIpAddress());


        }catch(Exception e){
            stopServerGuard();
            logNet("[S] 服务器启动失败: " + e);
        }
    }

    // 校验是否为合法 IPv4（每段 0-255）：避免 "999.1.1.1" 之类被当成主机名去 DNS 解析而长时间卡死
    private boolean isValidIPv4(String ip) {
        if (ip == null) return false;
        String[] p = ip.split("\\.");
        if (p == null || p.length != 4) return false;
        for (String s : p) {
            if (s == null || s.isEmpty() || s.length() > 3) return false;
            int v;
            try { v = Integer.parseInt(s); } catch (Exception e) { return false; }
            if (v < 0 || v > 255) return false;
        }
        return true;
    }

    // 真正建立连接（阻塞）。必须在后台线程调用，绝不放到渲染线程。
    // 不做任何 UI 操作，成功/失败由调用方切回 GL 线程处理。
    private boolean connectClientBlocking(String ip, int portNum) {
        try {
            client.start();
            // 纯 TCP 连接（业务全走 TCP，UDP 仅用于 KryoNet 注册握手）。
            // 独立服务器 / 云服务器常只开放一个 TCP 端口，带 UDP 会因注册握手超时被踢，
            // 因此这里不指定 UDP 端口；局域网主机模式同样兼容（服务器 UDP 开着也不影响）。
            client.connect(5000, ip, portNum);
            return true;
        } catch (Exception e) {
            lastConnectError = cnNetError( e );
            // 连接失败后务必 stop() 复位客户端：否则 KryoNet 更新线程会持续残留，
            // 反复重试会不断堆积线程。
            try { client.stop(); } catch (Exception ignore) {}
            return false;
        }
    }

    // 连接服务器（不阻塞渲染线程）：校验 -> 后台 connect -> 回到 GL 线程更新 UI。
    // 修复：以前在渲染线程同步 connect(timeout=5000)，IP/端口错误或地址不可达时会把整屏冻住，
    // 现象就是"点连接服务器后画面发虚、什么都点不了，只能重启"。
    private void runClient(final String aipi, final int portNum){
        try {
            if (portNum <= 0){
                logNet("请输入正确的端口号。");
                return;
            }
            String ip = (aipi == null) ? "" : aipi.trim();
            // 校验必须是纯 IPv4：房主日志可能一次列出多个地址（逗号分隔），
            // 整段复制或误带空格/端口会导致 UnknownHostException（"无解析主机无地址"）。
            if (ip.isEmpty()){
                logNet("[C] 请先填写服务器IP（房主显示的纯数字地址）。");
                return;
            }
            if (!ip.matches("\\d{1,3}(\\.\\d{1,3}){3}")){
                logNet("[C] 地址 \"" + ip + "\" 不是有效的IPv4地址。请只填房主显示的单个纯数字地址(如192.168.43.1)，不要整段复制多个地址。");
                return;
            }
            if (!isValidIPv4(ip)){
                logNet("[C] 地址 \"" + ip + "\" 不是有效的IPv4地址（每段需在 0-255 之间）。");
                return;
            }
            if (isConnecting){
                logNet("[C] 正在连接中，请稍候...");
                return;
            }
            isConnecting = true;
            lastConnectError = "";
            collabServerIp = ip;
            // 记忆 IP/端口：重进软件无需再次输入
            try { prefs.putString("collabIP", ip).putInteger("collabPort", portNum).flush(); } catch (Exception ignore) {}
            updateCollabStatus();
            logNet("[C] 正在连接服务器 ...");

            final String fip = ip;
            final int fport = portNum;
            new Thread(new Runnable(){
                public void run(){
                    final boolean ok = connectClientBlocking( fip, fport );
                    final String why = (lastConnectError == null) ? "" : lastConnectError;
                    runOnUi(new Runnable(){
                        public void run(){
                            isConnecting = false;
                            if (ok){
                                isClient = true;
                                localIP = getLocalIpAddress();
                                updateCollabStatus();
                                registerID();
                                logNet("已连接到服务器");
                            } else {
                                isClient = false;
                                updateCollabStatus();
                                logNet("[C] " + z.failedtoconnect + "（" + why + "）");
                                logNet("[C] 请核对: ①填的是否为房主那台机器同网段的IP ②端口一致 ③路由器未开AP隔离/两台连同一WiFi");
                            }
                        }
                    });
                }
            }, "CollabConnect").start();
        }catch(Exception e){
            isConnecting = false;
        }
    }

    // 将网络异常翻译为中文提示
    private String cnNetError(Throwable e){
        try {
            if (e == null) return "未知错误";
            String msg = (e.getMessage() == null) ? "" : e.getMessage();
            String cls = e.getClass().getSimpleName();
            if (cls.contains("UnknownHostException") || msg.contains("UnknownHost"))
                return "无法解析服务器地址（主机不存在）";
            if (cls.contains("SocketTimeoutException")) return "连接服务器超时";
            if (cls.contains("ConnectException") || msg.contains("refused") || msg.contains("拒绝"))
                return "服务器拒绝连接（IP/端口不对或服务器未启动）";
            if (msg != null && !msg.isEmpty()) return msg;
            return cls.isEmpty() ? "未知错误" : cls;
        } catch (Exception ex) { return "未知错误"; }
    }

    // ====================================================================
    //  自动更新：检测 / 下载 / 安装
    // ====================================================================
    /** 判断更新服务器地址是否可用（非空且非占位）。 */
    private static boolean isUsableHost(String h) {
        if (h == null) return false;
        h = h.trim();
        return !h.isEmpty() && !h.equals("0.0.0.0");
    }

    /**
     * 更新候选服务器：唯一内置主服（阿里云）。
     * 内置条目不可用则返回空列表（跳过更新）。
     */
    private java.util.List<ServerEntry> updateCandidateEntries() {
        java.util.List<ServerEntry> list = new java.util.ArrayList<ServerEntry>();
        ServerEntry main = null;
        try {
            for (int i = 0; i < serverEntries.size(); i++) {
                ServerEntry e = serverEntries.get( i );
                if (e == null || !e.builtin) continue;
                main = e;
                break;
            }
        } catch (Exception ignore) {}
        if (main == null) main = new ServerEntry( BUILTIN_SERVER1_NAME, BUILTIN_SERVER1_HOST, BUILTIN_SERVER1_PORT, true );
        if (isUsableHost( main.host )) list.add( main );
        return list;
    }

    /** 生成红点纹理（一个红色实心圆）。 */
    private Texture makeUpdateDotTexture() {
        int size = 32;
        Pixmap pm = new Pixmap( size, size, Pixmap.Format.RGBA8888 );
        pm.setColor( 0, 0, 0, 0 );
        pm.fill();
        pm.setColor( 1f, 0.16f, 0.16f, 1f );
        pm.fillCircle( size / 2, size / 2, size / 2 - 2 );
        Texture t = new Texture( pm );
        pm.dispose();
        return t;
    }

    /** 菜单中把更新按钮与红点叠放（红点位于右上角）。 */
    private com.badlogic.gdx.scenes.scene2d.ui.Stack buildUpdateButtonStack() {
        com.badlogic.gdx.scenes.scene2d.ui.Stack st = new com.badlogic.gdx.scenes.scene2d.ui.Stack();
        // 防御：极端时序（初始化未完成）下按钮/红点尚未创建时，返回空 Stack 避免空指针
        if (bUpdate == null || updateDot == null) {
            return st;
        }
        st.add( bUpdate );
        com.badlogic.gdx.scenes.scene2d.ui.Table dotHolder = new com.badlogic.gdx.scenes.scene2d.ui.Table();
        float dotSize = Math.max( 14f, btnx * 0.20f );
        dotHolder.add( updateDot ).width( dotSize ).height( dotSize ).expand().top().right().padTop( 3 ).padRight( 3 );
        st.add( dotHolder );
        return st;
    }

    /** 依据 updateAvailable 刷新红点显示。 */
    private void refreshUpdateDot() {
        if (updateDot != null) {
            try { updateDot.setVisible( updateAvailable ); } catch (Exception ignore) {}
        }
    }

    /** 启动时后台静默检测：有更新仅点亮「检查更新」按钮上的红点，不自动弹窗；失败不打扰。 */
    private void checkUpdateSilently() {
        java.util.List<ServerEntry> cands = updateCandidateEntries();
        if (cands.isEmpty()) return;
        checkUpdateCandidates( cands, true, new Runnable(){ public void run(){
            // 静默检测：只刷新「检查更新」按钮上的红点，不自动弹窗（避免每次进入软件都被弹窗打扰）
            refreshUpdateDot();
        } } );
    }

    /**
     * 通过与联机同一个 TCP 端口(默认 40686)向服务器查询新版本（单端口模式，无需额外 HTTP 端口）。
     * 按候选优先级依次尝试（优先阿里云备服，失败自动回退主服），命中即用；
     * 后台线程连接 → 发 otaCheck → 收 otaInfo → 回 UI 线程解析。
     *
     * @param silent 静默模式（失败不弹窗，仅用于启动后台检测）
     * @param onDone 检测完成后（无论成功失败）回 UI 线程执行的回调，可为 null
     */
    private void checkUpdateCandidates(final java.util.List<ServerEntry> cands, final boolean silent, final Runnable onDone) {
        if (updateChecking) return;
        if (cands == null || cands.isEmpty()) {
            if (!silent) msgbox( "检查更新失败：未配置更新服务器。" );
            return;
        }
        updateChecking = true;
        new Thread( new Runnable(){ public void run(){
            String json = null;
            for (int i = 0; i < cands.size(); i++) {
                ServerEntry e = cands.get( i );
                if (e == null) continue;
                String h = (e.host == null) ? "" : e.host.trim();
                if (!isUsableHost( h )) continue;
                int p = (e.port > 0) ? e.port : 40686;
                String r = otaFetchInfo( h, p );
                if (r != null) { json = r; break; }   // 命中即用（阿里云优先，失败自动回退主服）
            }
            final String fJson = json;
            runOnUi( new Runnable(){ public void run(){
                updateChecking = false;
                if (fJson != null) {
                    applyVersionInfo( fJson );
                } else {
                    updateAvailable = false;
                    if (!silent) msgbox( "检查更新失败：无法连接更新服务器或服务器未提供更新。" );
                }
                refreshUpdateDot();
                if (onDone != null) onDone.run();
            } } );
        } }, "OtaCheck" ).start();
    }

    /** 解析服务器返回的 version.json，更新本地“是否有新版本”状态。 */
    private void applyVersionInfo(String text) {
        try {
            if (text == null) { updateAvailable = false; return; }
            // 去掉可能的 UTF-8 BOM
            if (text.length() > 0 && text.charAt( 0 ) == '\uFEFF') text = text.substring( 1 );
            JsonValue root = new com.badlogic.gdx.utils.JsonReader().parse( text );
            int remote = root.getInt( "versionCode", 0 );
            updateRemoteCode = remote;
            updateRemoteName = root.getString( "versionName", "" );
            updateRemoteNotes = root.getString( "notes", "" );
            String apk = root.getString( "apkFile", "app-release.apk" );
            if (apk != null && !apk.trim().isEmpty()) updateApkFile = apk.trim();
            updateApkSize = root.getLong( "size", 0 );
            updateSha256 = root.getString( "sha256", "" );
            if (updateSha256 == null) updateSha256 = "";
            updateSha256 = updateSha256.replaceAll( "\\s", "" ).toLowerCase();
            int local = 0;
            try { local = face.getVersionCode(); } catch (Exception ignore) {}
            updateAvailable = remote > local;
        } catch (Exception e) {
            updateAvailable = false;
        }
    }

    /** 点击「检查更新」或启动自动检测后的弹窗：展示当前版本并检测/下载；
     *  更新服务器优先「备服」(阿里云)，失败自动回退「主服」，不显示输入框。 */
    private void showUpdateDialog() {
        final Dialog dlg = new Dialog( "软件更新", skin, "dialog" ) {
            @Override
            protected void result(Object object) {
                if (kartu != null && kartu.equals( "world" )) Gdx.input.setInputProcessor( im );
            }
        };

        Table body = new Table();
        body.pad( 10 );

        int local = 0;
        try { local = face.getVersionCode(); } catch (Exception ignore) {}
        Label lCur = new Label( "当前版本：" + vers + "（" + local + "）", skin );
        lCur.setWrap( true );
        body.add( lCur ).width( btnx - 50 ).left().row();

        // 更新服务器：优先阿里云(备服)，失败自动回退主服；两者任一可用即可完成更新。
        final java.util.List<ServerEntry> updateCands = updateCandidateEntries();

        final Label lStatus = new Label( "", skin );
        lStatus.setWrap( true );
        lStatus.setText( updateAvailable
                ? ( "发现新版本：" + updateRemoteName + "\n" + ( updateRemoteNotes == null ? "" : updateRemoteNotes ) )
                : "点「检查更新」从服务器获取最新版本。" );
        body.add( lStatus ).width( btnx - 50 ).left().padTop( 8 ).row();

        dlg.getContentTable().add( body ).width( btnx - 20 );

        final Runnable doCheck = new Runnable(){ public void run(){
            if (updateCands.isEmpty()) { lStatus.setText( "未配置更新服务器，请联系管理员。" ); return; }
            lStatus.setText( "正在检查…" );
            checkUpdateCandidates( updateCands, false, new Runnable(){ public void run(){
                if (updateAvailable) {
                    lStatus.setText( "发现新版本：" + updateRemoteName + "\n" + ( updateRemoteNotes == null ? "" : updateRemoteNotes ) );
                } else {
                    lStatus.setText( "已是最新版本。" );
                }
            } } );
        } };

        final Runnable doUpdate = new Runnable(){ public void run(){
            if (updateCands.isEmpty()) { lStatus.setText( "未配置更新服务器，请联系管理员。" ); return; }
            if (!updateAvailable) { lStatus.setText( "当前没有可用更新，请先点「检查更新」。" ); return; }
            try { dlg.hide(); } catch (Exception ignore) {}
            downloadAndInstall( updateCands );
        } };

        TextButton bCheck = new TextButton( "检查更新", skin );
        bCheck.addListener( new ChangeListener(){ @Override public void changed(ChangeEvent e, Actor a){ doCheck.run(); } } );
        TextButton bGo = new TextButton( "立即更新", skin );
        bGo.addListener( new ChangeListener(){ @Override public void changed(ChangeEvent e, Actor a){ doUpdate.run(); } } );
        TextButton bClose = new TextButton( "关闭", skin );
        bClose.addListener( new ChangeListener(){ @Override public void changed(ChangeEvent e, Actor a){ dlg.hide(); } } );

        dlg.getButtonTable().add( bCheck ).width( btnx / 3 ).padRight( 4 );
        dlg.getButtonTable().add( bGo ).width( btnx / 3 ).padRight( 4 );
        dlg.getButtonTable().add( bClose ).width( btnx / 3 );
        dlg.show( stage );
        // 弹窗显示期间输入交给 stage，确保按钮可点；关闭后由弹窗兜底逻辑归还地图输入
        Gdx.input.setInputProcessor( stage );
    }

    /** OTA 访客连接使用的保留 ID：仅用于绕过僵尸清理，不会显示在房间/成员列表中。 */
    private static final String OTA_GUEST_ID = "__OTA_GUEST__";

    /** 构造一个用于 OTA 的临时 KryoNet 客户端（Kryo 注册顺序必须与服务端一致）。 */
    private com.esotericsoftware.kryonet.Client newOtaClient() {
        com.esotericsoftware.kryonet.Client c = new SafeClient( 1048576, 1048576 );
        c.getKryo().register( TextChat.class );
        c.getKryo().register( layerhistory.class );
        c.getKryo().register( PlayerState.class );
        c.getKryo().register( command.class );
        return c;
    }

    /**
     * 通过游戏 TCP 端口向服务器索取 version.json 原文（阻塞，务必在后台线程调用）。
     * 成功返回 JSON 文本（可能为空串=服务器无更新）；失败/超时返回 null。
     */
    private String otaFetchInfo(final String host, final int port) {
        com.esotericsoftware.kryonet.Client c = null;
        final java.util.List<command> inbox = java.util.Collections.synchronizedList( new java.util.ArrayList<command>() );
        try {
            c = newOtaClient();
            c.addListener( new com.esotericsoftware.kryonet.Listener(){
                public void received( com.esotericsoftware.kryonet.Connection conn, Object o ){
                    if (o instanceof command) {
                        synchronized (inbox) { inbox.add( (command) o ); inbox.notifyAll(); }
                    }
                }
            } );
            c.start();
            c.connect( 5000, host, port );
            command reg = new command(); reg.command = "registerID"; reg.data = OTA_GUEST_ID; c.sendTCP( reg );
            command chk = new command(); chk.command = "otaCheck"; c.sendTCP( chk );
            long deadline = System.currentTimeMillis() + 8000L;
            synchronized (inbox) {
                while (true) {
                    for (int i = 0; i < inbox.size(); i++) {
                        command x = inbox.get( i );
                        if ("otaInfo".equals( x.command )) { inbox.remove( i ); return (x.data == null) ? "" : x.data; }
                    }
                    long wait = deadline - System.currentTimeMillis();
                    if (wait <= 0) return null;
                    try { inbox.wait( wait ); } catch (InterruptedException ie) { return null; }
                }
            }
        } catch (Exception e) {
            return null;
        } finally {
            try { if (c != null) c.stop(); } catch (Exception ignore) {}
        }
    }

    /**
     * 单端口 OTA 下载：连接同一 TCP 端口 → 发 otaFetch → 收 otaChunk(base64) 分块写入本地文件
     * → otaDone 后拉起系统安装器。全程在后台线程，进度回 UI 线程。
     */
    private void downloadAndInstall(final java.util.List<ServerEntry> cands) {
        final String savePath;
        try { savePath = face.getUpdateFilePath( updateApkFile ); }
        catch (Exception e) { msgbox( "更新下载失败：无法获取保存路径" ); return; }

        if (savePath == null || savePath.trim().isEmpty()) {
            msgbox( "更新下载失败：当前平台不支持自动更新。" );
            return;
        }
        if (cands == null || cands.isEmpty()) { msgbox( "更新下载失败：未配置更新服务器。" ); return; }
        status( "正在校验本地安装包…", 5 );
        new Thread( new Runnable(){ public void run(){
            // 先检查本地目录（私有 update / 公共“下载/Tunit”）是否已有该安装包：
            // 有则直接安装，无需重新下载；若校验不通过则删除后重新下载。
            try {
                String existing = face.findLocalUpdateApk( updateApkFile, updateApkSize );
                if (existing != null && !existing.trim().isEmpty()) {
                    boolean ok = true;
                    if (updateSha256 != null && !updateSha256.isEmpty()) {
                        String actual = sha256File( existing );
                        ok = (actual != null && actual.equalsIgnoreCase( updateSha256 ));
                        if (!ok) { try { new java.io.File( existing ).delete(); } catch (Exception ignore) {} }
                    }
                    if (ok && (updateSha256 == null || updateSha256.isEmpty()) && updateApkSize <= 0) {
                        // 服务器既未提供 sha256 也未提供文件大小：无法确认本地包是否为最新，改为重新下载
                        ok = false;
                    }
                    if (ok) {
                        final String p = existing;
                        runOnUi( new Runnable(){ public void run(){ status( "检测到已下载的安装包，正在安装…", 4 ); face.installApk( p ); } } );
                        return;
                    }
                    status( "本地安装包校验未通过，重新下载…", 4 );
                }
            } catch (Exception ignore) {}
            status( "正在下载更新… 0%", 5 );
            final String[] errBox = new String[]{ null };
            for (int ci = 0; ci < cands.size(); ci++) {
                ServerEntry ent = cands.get( ci );
                if (ent == null) continue;
                String h = (ent.host == null) ? "" : ent.host.trim();
                if (!isUsableHost( h )) continue;
                int p = (ent.port > 0) ? ent.port : 40686;
                int r = downloadFromOne( h, p, savePath, errBox );
                if (r == 1) return;                 // 成功（已拉起安装）
                if (r == -2) {                      // 已开始接收后失败：不再回退，直接报错
                    final String m = (errBox[0] == null) ? "下载中断" : errBox[0];
                    runOnUi( new Runnable(){ public void run(){ msgbox( "更新下载失败：" + m ); } } );
                    return;
                }
                // r == 0：连接/首包失败 → 换下一台服务器（阿里云失败自动回退主服）
            }
            final String m = (errBox[0] == null) ? "无法连接任一更新服务器" : errBox[0];
            runOnUi( new Runnable(){ public void run(){ msgbox( "更新下载失败：" + m ); } } );
        } }, "OtaDownload" ).start();
    }

    /**
     * 从单台服务器下载更新文件（阻塞，运行于 OtaDownload 线程）。
     * @return 1=成功并已拉起安装；0=连接/首包失败（可安全回退下一台）；-2=已开始接收后失败（不可回退，避免半截文件）
     */
    private int downloadFromOne(final String host, final int port, final String savePath, final String[] errBox) {
        com.esotericsoftware.kryonet.Client c = null;
        java.io.FileOutputStream fos = null;
        final java.util.List<Object> signal = java.util.Collections.synchronizedList( new java.util.ArrayList<Object>() );
        final long[] progress = new long[]{ 0L, 0L };            // {已下载, 总大小}
        final boolean[] finished = new boolean[]{ false };
        final boolean[] started = new boolean[]{ false };        // 是否已收到首包（otaStart/otaChunk/otaDone）
        final String[] errMsg = new String[]{ null };
        try {
            fos = new java.io.FileOutputStream( savePath );
            final java.io.FileOutputStream fFos = fos;
            c = newOtaClient();
            c.addListener( new com.esotericsoftware.kryonet.Listener(){
                public void received( com.esotericsoftware.kryonet.Connection conn, Object o ){
                    if (!(o instanceof command)) return;
                    command x = (command) o;
                    try {
                        if ("otaStart".equals( x.command )) {
                            started[0] = true;
                            try { progress[1] = Long.parseLong( x.data == null ? "0" : x.data.trim() ); } catch (Exception ignore) {}
                            if (progress[1] <= 0) progress[1] = updateApkSize;
                        } else if ("otaChunk".equals( x.command )) {
                            started[0] = true;
                            byte[] b = b64decode( x.data );
                            try {
                                synchronized (fFos) { fFos.write( b ); }
                            } catch (Exception we) {
                                // 写盘失败（如磁盘写满/IO错误）：立即终止，避免把残缺文件交给安装器
                                errMsg[0] = "写入更新文件失败: " + (we.getMessage() == null ? we.toString() : we.getMessage());
                                synchronized (signal) { finished[0] = true; signal.notifyAll(); }
                                return;
                            }
                            progress[0] += b.length;
                            long total = progress[1];
                            int pct = (total > 0) ? (int) (progress[0] * 100 / total) : 0;
                            final int fp = Math.max( 0, Math.min( 100, pct ) );
                            runOnUi( new Runnable(){ public void run(){ status( "正在下载更新… " + fp + "%", 5 ); } } );
                        } else if ("otaDone".equals( x.command )) {
                            started[0] = true;
                            synchronized (signal) { finished[0] = true; signal.notifyAll(); }
                        } else if ("otaError".equals( x.command )) {
                            errMsg[0] = (x.data == null || x.data.isEmpty()) ? "服务器拒绝下载" : x.data;
                            synchronized (signal) { finished[0] = true; signal.notifyAll(); }
                        }
                    } catch (Exception ignore) {}
                }
            } );
            c.start();
            c.connect( 5000, host, port );
            command reg = new command(); reg.command = "registerID"; reg.data = OTA_GUEST_ID; c.sendTCP( reg );
            command fetch = new command(); fetch.command = "otaFetch"; c.sendTCP( fetch );
            long deadline = System.currentTimeMillis() + 10 * 60 * 1000L;   // 最长 10 分钟
            synchronized (signal) {
                while (!finished[0]) {
                    long wait = deadline - System.currentTimeMillis();
                    if (wait <= 0) { if (!started[0]) return 0; errMsg[0] = "下载超时"; break; }
                    try { signal.wait( wait ); } catch (InterruptedException ie) { if (!started[0]) return 0; errMsg[0] = "下载被中断"; break; }
                }
            }
            try { synchronized (fFos) { fFos.flush(); } } catch (Exception ignore) {}
            final String err = errMsg[0];
            final long got = progress[0];
            final long want = progress[1];
            if (err != null) { errBox[0] = err; return started[0] ? -2 : 0; }
            if (got <= 0) { errBox[0] = "未收到数据"; return 0; }
            if (want > 0 && got < want) { errBox[0] = "文件不完整（已接收 " + got + "/" + want + " 字节），请重试。"; return -2; }
            // 完整性校验：若服务器在 version.json 中提供了 sha256，则必须一致才安装，
            // 防止更新包被中间人替换或传输过程中被篡改。
            if (updateSha256 != null && !updateSha256.isEmpty()) {
                String actual = sha256File( savePath );
                if (actual == null || !actual.equalsIgnoreCase( updateSha256 )) {
                    try { new java.io.File( savePath ).delete(); } catch (Exception ignore) {}
                    errBox[0] = "更新包校验失败（SHA-256 不匹配），已丢弃，请重试。";
                    return -2;
                }
            }
            runOnUi( new Runnable(){ public void run(){
                status( "下载完成，正在拉起安装…", 4 );
                face.installApk( savePath );
            } } );
            return 1;
        } catch (Exception e) {
            errBox[0] = (e.getMessage() == null) ? e.toString() : e.getMessage();
            return started[0] ? -2 : 0;   // 连接异常且尚未开始接收→可回退；已开始→不回退
        } finally {
            try { if (fos != null) fos.close(); } catch (Exception ignore) {}
            try { if (c != null) c.stop(); } catch (Exception ignore) {}
        }
    }

    /** 计算本地文件的 SHA-256（小写十六进制）；读取失败返回 null。用于 OTA 更新包完整性校验。 */
    private static String sha256File(String path) {
        java.io.FileInputStream fis = null;
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance( "SHA-256" );
            fis = new java.io.FileInputStream( path );
            byte[] buf = new byte[ 64 * 1024 ];
            int n;
            while ((n = fis.read( buf )) > 0) md.update( buf, 0, n );
            byte[] d = md.digest();
            StringBuilder sb = new StringBuilder( d.length * 2 );
            for (byte b : d) {
                sb.append( Character.forDigit( (b >> 4) & 0xF, 16 ) ).append( Character.forDigit( b & 0xF, 16 ) );
            }
            return sb.toString();
        } catch (Exception e) {
            return null;
        } finally {
            try { if (fis != null) fis.close(); } catch (Exception ignore) {}
        }
    }

    /** 标准 Base64 解码（与服务端 java.util.Base64 兼容；忽略换行/空白与非法字符）。 */
    private static byte[] b64decode(String s) {
        if (s == null || s.isEmpty()) return new byte[0];
        java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream( s.length() / 4 * 3 + 3 );
        int buf = 0, bits = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt( i );
            if (ch == '=') break;
            int v;
            if (ch >= 'A' && ch <= 'Z') v = ch - 'A';
            else if (ch >= 'a' && ch <= 'z') v = ch - 'a' + 26;
            else if (ch >= '0' && ch <= '9') v = ch - '0' + 52;
            else if (ch == '+') v = 62;
            else if (ch == '/') v = 63;
            else continue;   // 跳过空白/非法字符
            buf = (buf << 6) | v;
            bits += 6;
            if (bits >= 8) { bits -= 8; out.write( (buf >> bits) & 0xFF ); }
        }
        return out.toByteArray();
    }

    // ===== WiFi 直连主机模式：无需独立服务器，本机即服务器 =====

    // 收集本机全部非回环 IPv4（逗号分隔，WiFi 与热点并存时可能多个）
    private String allLocalIPv4() {
        try {
            StringBuilder sb = new StringBuilder();
            for (Enumeration<NetworkInterface> en = NetworkInterface.getNetworkInterfaces(); en.hasMoreElements();) {
                NetworkInterface intf = en.nextElement();
                if (intf.isLoopback()) continue;
                for (Enumeration<InetAddress> ea = intf.getInetAddresses(); ea.hasMoreElements();) {
                    InetAddress a = ea.nextElement();
                    if (a instanceof Inet4Address && !a.isLoopbackAddress()) {
                        if (sb.length() > 0) sb.append(", ");
                        sb.append( a.getHostAddress() );
                    }
                }
            }
            return sb.length() == 0 ? null : sb.toString();
        } catch (Exception e) { return null; }
    }

    // 一键"本机开房"：启动内置服务器 → 客户端自连本机 → 自动建房
    private void startLocalHost(){
        try {
            if (hostingLocal || isServer){
                logNet( "[H] 已处于主机模式。" );
                return;
            }
            if (isConnecting){
                logNet( "[H] 正在连接中，请稍候..." );
                return;
            }
            if (isClient) stopClient();
            int tcpPort = 40686;
            try { tcpPort = Integer.parseInt( tfPort.getText().trim() ); } catch (Exception e) { tcpPort = 40686; }
            if (tcpPort <= 0){
                logNet( "请输入正确的端口号。" );
                return;
            }
            // 记住本次使用的端口
            try { prefs.putInteger("collabPort", tcpPort).flush(); } catch (Exception ignore) {}
            String rn = roomName == null ? "" : roomName.getText().trim();
            if (rn.isEmpty()) { rn = "room1"; if (roomName != null) roomName.setText( rn ); }

            String ips = allLocalIPv4();
            if (ips == null || ips.isEmpty()) ips = getLocalIpAddress();
            if (ips == null) ips = "127.0.0.1";
            localIP = ips;

            server.start();
            server.bind( tcpPort );       // 纯 TCP：勿加 UDP 端口（原因同独立服务器，纯 TCP 客户端无法 UDP 注册）
            startServerGuard();   // 启动僵尸连接清理 / 限速守护线程
            isServer = true;
            hostingLocal = true;
            collabServerIp = ips;
            tbHost.setText( z.stoplocal );
            logNet( "[H] 本机服务器已启动: TCP " + tcpPort + "（纯 TCP 模式）" );
            logNet( "[H] 你的局域网地址: " + ips );
            if (lHostHint != null) lHostHint.setText( z.hosthint );

            // 客户端自连本机放到后台线程，连接成功后再建房；避免阻塞渲染线程。
            final String fRoom = rn;
            final String fIps = ips;
            final int fPort = tcpPort;
            isConnecting = true;
            new Thread(new Runnable(){
                public void run(){
                    final boolean ok = connectClientBlocking( "127.0.0.1", fPort );
                    final String why = (lastConnectError == null) ? "" : lastConnectError;
                    runOnUi(new Runnable(){
                        public void run(){
                            isConnecting = false;
                            if (!ok){
                                stopServerGuard();
                                hostingLocal = false;
                                isServer = false;
                                collabServerIp = "";
                                if (tbHost != null) tbHost.setText( z.hostlocal );
                                updateCollabStatus();
                                logNet( "[H] 自连本机失败: " + why );
                                return;
                            }
                            isClient = true;
                            collabServerIp = fIps; // 状态栏向队友展示真实局域网 IP
                            updateCollabStatus();
                            registerID();
                            logNet( "[H] 正在创建房间: " + fRoom + " ..." );
                            createRoom();
                            logNet( "[H] 队友操作: 协作页 -> 服务器IP填 " + fIps + " 端口 " + fPort + " -> 连接 -> 加入房间 \"" + fRoom + "\"" );
                        }
                    });
                }
            }, "LocalHostConnect").start();
        }catch(Exception e){
            stopServerGuard();
            logNet( "[H] 主机启动失败: " + e );
            hostingLocal = false;
            isServer = false;
            collabServerIp = "";
            if (tbHost != null) tbHost.setText( z.hostlocal );
            updateCollabStatus();
        }
    }

    // 停止本机主机（先结束自己的房间会话，再关闭内置服务器）
    private void stopLocalHost(){
        try {
            logNet( "[H] 正在停止本机主机..." );
            stopServerGuard();   // 结束僵尸清理守护线程
            if (isClient) stopClient();
            if (isServer) {
                try { server.stop(); } catch (Exception e) {}
                isServer = false;
            }
            hostingLocal = false;
            collabServerIp = "";
            if (tbHost != null) tbHost.setText( z.hostlocal );
            if (lHostHint != null) lHostHint.setText( "" );
            activeClients.clear();
            logNet( "[H] 本机主机已停止" );
            updateCollabStatus();
        } catch (Exception e) {}
    }

    // 网络协议类已抽离为共享顶层类（shared/com/mirwanda/nottiled）：
    // TextChat / command / PlayerState / actvClients / packet / layerhistory，供客户端与独立服务器共用同一 FQCN。

    private void setTsetFromCurspr(){
        for (int ii=0; ii<tilesets.size();ii++){
            tileset ts = tilesets.get(ii);
            if (this.curspr >= ts.getFirstgid() && this.curspr < ts.getFirstgid()+ts.getTilecount()){
                curtset= ii;
                break;
            }
        }

    }

    private int getTsetFromSpr(int i){
        for (int ii=0; ii<tilesets.size();ii++){
            tileset ts = tilesets.get(ii);
            if (i >= ts.getFirstgid() && i < ts.getFirstgid()+ts.getTilecount()){
                return ii;
            }
        }

        return -1;
    }

    private int getTileFromSpr(int i,tileset t){

        for (int ii=0; ii<t.getTiles().size();ii++){
            tile ts = t.getTiles().get(ii);
            if (i == ts.getTileID()){
                return ii;
            }
        }

        return -1;
    }

    private void adjustLayer(tileset ts){
        for (property p:ts.getProperties()){
            if (p.getName().equalsIgnoreCase( "layer" )){
                for (int l=0; l<layers.size();l++){
                    if (layers.get(l).getName().equalsIgnoreCase( p.getValue() )){
                        selLayer=l;
                        updateObjectCollision();

                        switch (viewMode) {
                            case STACK:
                            case SINGLE:
                                resetCaches();
                                break;
                        }

                        break;
                    }
                }
            }
        }

    }
    private void adjustTileset(){
        for (tileset t : tilesets){
            for (property p:t.getProperties()){

                if (layers.get(selLayer).getName().equalsIgnoreCase( p.getValue() )){
                    if (t.getTerrains().size()>0){
                        for (tile tl: t.getTiles()){
                            if (tl.isTerrain() && tl.isCenter()){
                                curspr= tl.getTileID()+t.getFirstgid();
                                break;
                            }
                        }

                    }else{
                        curspr=t.getFirstgid();
                    }
                    setTsetFromCurspr();
                    recenterpick();
                    return;
                }
            }
        }
    }

    private void updateObjectCollision(){
        if (layers.size()==0) return;
       // if (layers.get(selLayer).getType()!=layer.Type.OBJECT) return;

           // for (layer l: layers){
           // if (l.getType()==layer.Type.OBJECT){

                com.badlogic.gdx.utils.Array<Body> bds = new com.badlogic.gdx.utils.Array<Body>();
                world.getBodies( bds );
                for ( Body bd : bds){
                    if (bd==body) continue;
                    if (world.getBodyCount()==0) break;
                    world.destroyBody( bd );
                }
            //}
        //}

        java.util.List<obj> obs = layers.get(selLayer).getObjects();
        if (obs == null) return;
        for (obj ob : obs){
            if (ob == null) continue;
            try {
                ob.updateVertices( world ,Tsh);
            } catch (Throwable t) {
                // 单对象重建失败不拖垮整体：清理其半成品 body 后继续后续对象
                try { if (ob.getBody() != null) { world.destroyBody( ob.getBody() ); ob.setBody( null ); } } catch (Exception e2) {}
            }
        }

    }
